name: PR189 repair inherited qualification

on:
  pull_request_review:
    types: [submitted]

permissions:
  contents: read

concurrency:
  group: pr189-inherited-repair-${{ github.event.pull_request.head.ref }}
  cancel-in-progress: false

defaults:
  run:
    shell: bash

env:
  PYTHONDONTWRITEBYTECODE: '1'
  SBT_TEST_PARALLEL: '0'
  JAVA_TOOL_OPTIONS: '-Xmx2g -XX:ActiveProcessorCount=2'
  JVM_OPTS: '-Xmx4g -Xss2m -XX:ActiveProcessorCount=2'

jobs:
  prepare:
    name: Repair exact pass routing and preserve all current-source rejection controls
    if: >-
      github.event.action == 'submitted' && github.event.review.state == 'commented' &&
      github.event.review.user.login == github.repository_owner && github.actor == github.repository_owner &&
      github.repository == 'pysolvesemi/MorphHDL' && github.event.pull_request.number == 189 &&
      github.event.pull_request.head.repo.full_name == github.repository &&
      github.event.pull_request.head.ref == 'agent/cdc-independent-parameter-consumers' &&
      github.event.pull_request.base.ref == 'parameterized-verilog' &&
      github.event.review.commit_id == github.event.pull_request.head.sha &&
      github.event.review.body == format('pr189:repair-pass-routing:{0}', github.event.pull_request.head.sha)
    runs-on: ubuntu-24.04
    timeout-minutes: 45
    permissions:
      contents: write
    env:
      EXPECTED_INPUT: ${{ github.event.pull_request.head.sha }}
      EVIDENCE: /tmp/pr189-pass-route-repair
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.event.pull_request.head.sha }}
          fetch-depth: 0
          persist-credentials: false
      - name: Apply only the pinned edits, run the source controls and export exact Git objects
        env:
          GH_OBJECT_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          mkdir -p "$EVIDENCE"
          git config user.name 'github-actions[bot]'
          git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
          python3 repro/cdc-independent-parameters/repair_pass_routes.py 2>&1 | tee "$EVIDENCE/repair.log"
          # The script exports blobs/trees/commits only. It cannot update refs.
          # Publication uses the authorized connection after these results are read.
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: pr189-pass-route-repair-${{ github.event.pull_request.head.sha }}-${{ github.run_attempt }}
          path: /tmp/pr189-pass-route-repair/
          if-no-files-found: error
          retention-days: 30

  qualify-source:
    name: Authenticate the published repair against its actual CI source receipt
    if: >-
      github.event.action == 'submitted' && github.event.review.state == 'commented' &&
      github.event.review.user.login == github.repository_owner && github.actor == github.repository_owner &&
      github.repository == 'pysolvesemi/MorphHDL' && github.event.pull_request.number == 189 &&
      github.event.pull_request.head.repo.full_name == github.repository &&
      github.event.pull_request.head.ref == 'agent/cdc-independent-parameter-consumers' &&
      github.event.pull_request.base.ref == 'parameterized-verilog' &&
      github.event.review.commit_id == github.event.pull_request.head.sha &&
      startsWith(github.event.review.body, format('pr189:qualify-pass-routing:{0}:', github.event.pull_request.head.sha))
    runs-on: ubuntu-24.04
    timeout-minutes: 15
    permissions:
      contents: read
      actions: read
    outputs:
      head: ${{ steps.identity.outputs.head }}
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.event.pull_request.head.sha }}
          fetch-depth: 0
          persist-credentials: false
      - id: identity
        name: Verify the complete source-passing candidate and unchanged PR target
        uses: actions/github-script@v7
        with:
          script: |
            const fs=require('fs'),crypto=require('crypto'),cp=require('child_process');
            const head=context.payload.pull_request.head.sha;
            const command=new RegExp('^pr189:qualify-pass-routing:'+head+':([0-9]+)$').exec(context.payload.review.body);
            if(!command) throw new Error('Malformed source qualification command');
            const run_id=Number(command[1]);
            const git=(...args)=>cp.execFileSync('git',args,{encoding:'utf8'}).trim();
            if(git('rev-parse','HEAD')!==head) throw new Error('Wrong qualification checkout');
            const {data:p}=await github.rest.pulls.get({...context.repo,pull_number:189});
            if(p.state!=='open'||p.merged||p.head.sha!==head||p.head.ref!=='agent/cdc-independent-parameter-consumers'||
                p.base.ref!=='parameterized-verilog'||p.base.sha!=='27af65abbee0d2334d6be7a6e4e2408b8af32fd9') throw new Error('PR source or target changed');
            const {data:run}=await github.rest.actions.getWorkflowRun({...context.repo,run_id});
            if(run.status!=='completed'||run.conclusion!=='success'||run.head_branch!==p.head.ref||
                run.path!=='.github/workflows/pr189-60b-source-repair.yml'||run.event!=='pull_request_review') throw new Error('No successful source-repair run');
            git('merge-base','--is-ancestor',run.head_sha,head);
            const control='.github/workflows/pr189-60b-source-repair.yml';
            if(git('rev-parse',head+':'+control)!==git('rev-parse',run.head_sha+':'+control)) throw new Error('Qualification controller differs from reviewed preparation');
            const {data:list}=await github.rest.actions.listWorkflowRunArtifacts({...context.repo,run_id,per_page:100});
            const artifacts=list.artifacts.filter(a=>a.name==='pr189-pass-route-repair-'+run.head_sha+'-'+run.run_attempt && !a.expired);
            if(artifacts.length!==1) throw new Error('Missing or ambiguous source receipt');
            const artifact=artifacts[0];
            const {data:download}=await github.rest.actions.downloadArtifact({...context.repo,artifact_id:artifact.id,archive_format:'zip'});
            const zip=Buffer.from(download);
            if(artifact.digest!=='sha256:'+crypto.createHash('sha256').update(zip).digest('hex')) throw new Error('Source evidence digest differs');
            const dir='/tmp/pr189-source-qualification';fs.mkdirSync(dir,{recursive:true});
            fs.writeFileSync(dir+'/source.zip',zip);
            const identity=JSON.parse(cp.execFileSync('python3',['-c',
              'import sys,zipfile\nz=zipfile.ZipFile(sys.argv[1])\ni=z.getinfo("source-pass.json")\nassert i.file_size<100000\nprint(z.read(i).decode())',dir+'/source.zip'],{encoding:'utf8'}));
            if(identity.candidate!==head||identity.tree!==git('rev-parse','HEAD^{tree}')||identity.input!==run.head_sha||
                identity.base!=='6ee3605c71704ca9f684d4859762cbb02f3677c8'||identity.target!==p.base.sha||
                identity.compiler_sources_unchanged!==true) throw new Error('Source identity does not match tested and published candidate');
            fs.writeFileSync(dir+'/identity.json',JSON.stringify({identity,run_id,artifact_id:artifact.id},null,2));
            core.setOutput('head',head);
      - name: Recheck exact current source before dispatching any failed workflow
        run: |
          set -euo pipefail
          python3 morphhdl/scripts/check-increment-62-wa08-source-overlay.py
          python3 morphhdl/scripts/check-increment-61-source-review.py
          python3 morphhdl/scripts/check-native-source-preservation.py
          git diff --exit-code
          git diff --cached --exit-code
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: pr189-pass-routing-source-${{ github.event.pull_request.head.sha }}-${{ github.run_attempt }}
          path: /tmp/pr189-source-qualification/
          if-no-files-found: error
          retention-days: 30

  failed-first:
    name: Rerun failed standard workflows before full qualification on the same source
    needs: qualify-source
    runs-on: ubuntu-24.04
    timeout-minutes: 330
    permissions:
      contents: read
      actions: write
    env:
      QUALIFICATION_HEAD: ${{ needs.qualify-source.outputs.head }}
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ needs.qualify-source.outputs.head }}
          fetch-depth: 0
          persist-credentials: false
      - name: Execute the pinned failed-first controller with the two reviewed workflow successors
        uses: actions/github-script@v7
        with:
          script: |
            const cp=require('child_process');
            const revision='6ee3605c71704ca9f684d4859762cbb02f3677c8';
            const path='.github/workflows/pr189-60b-source-repair.yml';
            const expected='cf673c2c9e57ff60160521143252b7f11a384ab3';
            const git=(...args)=>cp.execFileSync('git',args,{encoding:'utf8'}).trim();
            if(git('rev-parse',revision+':'+path)!==expected) throw new Error('Pinned qualification controller differs');
            const source=git('show',revision+':'+path);
            const marker='\n  failed-first:\n';
            if(source.split(marker).length!==2) throw new Error('Ambiguous failed-first definition');
            const job=source.split(marker)[1].split('\n  full-compact-current:')[0];
            const block=job.match(/^          script: \|\n((?:            [^\n]*\n|\n)+)/m);
            if(!block) throw new Error('Missing original failed-first command');
            let code=block[1].split('\n').map(line=>line.startsWith('            ')?line.slice(12):line).join('\n');
            function exact(before,after) {
              if(code.split(before).length!==2) throw new Error('Non-unique controller adaptation');
              code=code.replace(before,after);
            }
            exact("repaired='9d6d5ba21a9c1137e6c36fb5a80162402a9ae6e2'","repaired='6ee3605c71704ca9f684d4859762cbb02f3677c8'");
            exact("const baseline=path.endsWith('/increment-60b-signedness-authority.yml')?repaired:previous;",
              "const baseline=path.endsWith('/morphhdl-passes.yml')?head:(path.endsWith('/increment-60b-signedness-authority.yml')?repaired:previous);");
            // The published pass workflow is authenticated by qualify-source's
            // exact source-passing receipt and WA08 seal. All other standard
            // workflow definitions retain the original immutable comparisons.
            // Failure, missing payload, pending predecessor or source movement
            // still prevents full dispatch; no status or gate is removed.
            const AsyncFunction=Object.getPrototypeOf(async function(){}).constructor;
            await new AsyncFunction('github','context','core','require',code)(github,context,core,require);
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: pr189-pass-routing-gates-${{ needs.qualify-source.outputs.head }}-${{ github.run_attempt }}
          path: /tmp/pr189-60b-gates/
          if-no-files-found: error
          retention-days: 30

  full-compact-current:
    name: Requalify unchanged compact and record compiler on the exact full-CI head
    needs: [qualify-source, failed-first]
    runs-on: ubuntu-24.04
    timeout-minutes: 180
    container:
      image: ghcr.io/spinalhdl/docker:v1.2.0
    env:
      EXPECTED_HEAD: ${{ needs.qualify-source.outputs.head }}
      EVIDENCE: /tmp/pr189-final-compact
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ needs.qualify-source.outputs.head }}
          fetch-depth: 0
          submodules: recursive
          persist-credentials: false
      - name: Execute both unchanged full-compact command blocks from their authenticated definition
        run: |
          set -euo pipefail
          python3 - <<'PY'
          import os,re,subprocess,textwrap
          from pathlib import Path
          revision='05e8f46b76c39017958b98c36b04475493446cef'
          path='.github/workflows/pr189-compact-timeout.yml'
          expected='4c4d1ed908df6ab4c150d736b7cef57b9918241a'
          def git(*args): return subprocess.check_output(['git',*args],text=True,timeout=120).strip()
          if git('rev-parse','HEAD')!=os.environ['EXPECTED_HEAD'] or git('rev-parse',revision+':'+path)!=expected:
              raise RuntimeError('Wrong full-qualification source or command definition')
          source=git('show',revision+':'+path)
          marker='\n  full-compact-current:\n'
          if source.count(marker)!=1: raise RuntimeError('Ambiguous original full qualification job')
          job=source.split(marker,1)[1]+'\n'
          blocks=re.findall(r'^        run: \|\n((?:          [^\n]*\n|\n)+)',job,re.M)
          if len(blocks)!=2: raise RuntimeError('Expected the exact compiler/behavior and 18-source-gate blocks')
          evidence=Path(os.environ['EVIDENCE']); evidence.mkdir(parents=True,exist_ok=True)
          (evidence/'commands-origin.txt').write_text(revision+'\n'+path+'\n'+expected+'\n')
          for index,block in enumerate(blocks,1):
              command=textwrap.dedent(block)
              (evidence/('original-command-'+str(index)+'.sh')).write_text(command)
              subprocess.run(['bash','-e','-o','pipefail','-c',command],check=True)
          if git('rev-parse','HEAD')!=os.environ['EXPECTED_HEAD']: raise RuntimeError('Full qualification head moved')
          subprocess.run(['git','diff','--exit-code'],check=True)
          subprocess.run(['git','diff','--cached','--exit-code'],check=True)
          PY
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: pr189-full-compact-${{ needs.qualify-source.outputs.head }}-${{ github.run_attempt }}
          path: /tmp/pr189-final-compact/
          if-no-files-found: error
          retention-days: 30

