    if: >-
      github.event.action == 'submitted' && github.event.review.state == 'commented' &&
      github.event.review.user.login == github.repository_owner && github.actor == github.repository_owner &&
      github.repository == 'pysolvesemi/MorphHDL' && github.event.pull_request.number == 189 &&
      github.event.pull_request.head.repo.full_name == github.repository &&
      github.event.pull_request.head.ref == 'agent/cdc-independent-parameter-consumers' &&
      github.event.pull_request.base.ref == 'parameterized-verilog' &&
      github.event.review.commit_id == github.event.pull_request.head.sha &&
      github.event.review.body == format('pr189:failed-workflows:{0}', github.event.pull_request.head.sha)
    runs-on: ubuntu-24.04
    timeout-minutes: 45
    permissions:
      contents: write
      actions: read
    outputs:
      head: ${{ steps.publish.outputs.head }}
      tree: ${{ steps.publish.outputs.tree }}
    env:
      EXPECTED_INPUT: ${{ github.event.pull_request.head.sha }}
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.event.pull_request.head.sha }}
          fetch-depth: 0
          persist-credentials: true
      - name: Require the actual predecessor qualification to have succeeded
        uses: actions/github-script@v7
        with:
          script: |
            const {data: run} = await github.rest.actions.getWorkflowRun({...context.repo, run_id: 35175042711});
            if (run.status !== 'completed' || run.conclusion !== 'success' ||
                run.head_sha !== '3fb55a9c575ea7695dd763744906dd5f3b1b876f' ||
                run.head_branch !== 'agent/cdc-independent-parameter-consumers' ||
                run.path !== '.github/workflows/pr189-compact-timeout.yml') {
              throw new Error('The pinned compact predecessor is not qualified');
            }
      - name: Seal only this reviewed workflow delta without changing any verifier algorithm
        run: |
          set -euo pipefail
          mkdir -p /tmp/pr189-ci-transition
          git config user.name 'github-actions[bot]'
          git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
          python3 - <<'PY'
          import importlib.util, json, os, re, subprocess, tempfile
          from pathlib import Path
          root = Path.cwd()
          base = 'd63ee5b1a8e6d6b0380ebd562798a92614b89614'
          qualified = 'de27c051d0db2acea18ebbc45d3f55326fba7716'
          workflow = '.github/workflows/pr189-compact-timeout.yml'
          helper = 'morphhdl/scripts/check-increment-62-wa08-source-overlay.py'
          manifest = 'morphhdl/contracts/increment-62-wa08-source-overlay.json'
          def git(*args):
              return subprocess.check_output(['git', '--literal-pathspecs', *args], timeout=120)
          def require(ok, message):
              if not ok: raise RuntimeError('PR189 CI transition: ' + message)
          def changed(a, b):
              return set(git('diff', '--name-only', '--no-renames', '-z', a, b).decode().split('\0')) - {''}
          head = git('rev-parse', 'HEAD').decode().strip()
          require(head == os.environ['EXPECTED_INPUT'], 'wrong input head')
          require(git('show', '-s', '--format=%P', head).decode().strip() == base, 'unexpected input parent')
          require(changed(base, head) == {workflow}, 'only the workflow control file may change')
          require(changed(qualified, base) == {workflow, helper, manifest}, 'predecessor changed compiler or tests')
          require(not git('status', '--porcelain', '--untracked-files=all'), 'dirty input')
          git('merge-base', '--is-ancestor', qualified, base)
          git('merge-base', '--is-ancestor', '27af65abbee0d2334d6be7a6e4e2408b8af32fd9', head)
          spec = importlib.util.spec_from_file_location('reviewed_wa08', root / helper)
          wa = importlib.util.module_from_spec(spec)
          spec.loader.exec_module(wa)
          with tempfile.TemporaryDirectory(prefix='pr189-qualified-predecessor-') as directory:
              checkout = Path(directory) / 'source'
              git('worktree', 'add', '--quiet', '--detach', str(checkout), base)
              try:
                  subprocess.run(['python3', str(checkout / helper)], cwd=checkout, check=True, timeout=300)
              finally:
                  git('worktree', 'remove', '--force', str(checkout))
          old = wa.contract(root)
          records = old['files']
          selected = [entry for entry in records if entry['path'] == workflow]
          require(len(selected) == 1, 'workflow missing from the existing exact inventory')
          require(selected[0]['after_sha256'] == wa.digest(git('show', base + ':' + workflow)), 'old workflow bytes differ')
          old_bytes = (root / helper).read_bytes()
          before_records = json.loads(json.dumps(records))
          selected[0]['after_sha256'] = wa.digest((root / workflow).read_bytes())
          for before, after in zip(before_records, records):
              if before['path'] != workflow: require(before == after, 'unrelated review entry changed')
              else: require({k:v for k,v in before.items() if k != 'after_sha256'} ==
                            {k:v for k,v in after.items() if k != 'after_sha256'}, 'baseline or mode changed')
          old['final_source_commit'] = head
          (root / manifest).write_text(json.dumps(old, indent=2) + '\n')
          replacement = ('CONTRACT_SHA256 = "' + wa.digest((root / manifest).read_bytes()) + '"').encode()
          updated, count = re.subn(rb'^CONTRACT_SHA256 = "[^"]+"$', replacement, old_bytes, count=1, flags=re.M)
          require(count == 1 and wa.normalized_helper(updated) == wa.normalized_helper(old_bytes), 'verifier logic changed')
          (root / helper).write_bytes(updated)
          git('add', '--', helper, manifest)
          git('commit', '-q', '-m', 'PR189: bind corrected failed-first CI control to its exact source review [skip ci]')
          require(changed(qualified, 'HEAD') == {workflow, helper, manifest}, 'unexpected transition delta')
          require(not git('status', '--porcelain', '--untracked-files=all'), 'uncommitted candidate bytes')
          Path('/tmp/pr189-ci-transition/identity.json').write_text(json.dumps({
              'qualified_compiler': qualified, 'previous_control': base, 'input': head,
              'head': git('rev-parse', 'HEAD').decode().strip(),
              'tree': git('rev-parse', 'HEAD^{tree}').decode().strip(),
              'changed_paths': sorted(changed(qualified, 'HEAD')),
              'compiler_and_test_sources_unchanged': True}, indent=2) + '\n')
          PY
          git diff --check
          git diff --binary de27c051d0db2acea18ebbc45d3f55326fba7716 HEAD > /tmp/pr189-ci-transition/control.patch
      - name: Check the exact source boundary and its rejection controls before publication
        run: |
          set -euo pipefail
          for checker in check-increment-62-wa08-source-overlay.py check-native-source-preservation.py check-increment-61-source-review.py; do
            python3 "morphhdl/scripts/$checker" 2>&1 | tee "/tmp/pr189-ci-transition/$checker.log"
            python3 "morphhdl/scripts/$checker" --self-test 2>&1 | tee "/tmp/pr189-ci-transition/$checker-mutations.log"
          done
          git diff --exit-code
          git diff --cached --exit-code
      - id: publish
        name: Publish only the checked control seal with automatic CI suppressed
        run: |
          set -euo pipefail
          branch='agent/cdc-independent-parameter-consumers'
          test "$(git ls-remote --exit-code origin "refs/heads/$branch" | cut -f1)" = "$EXPECTED_INPUT"
          test "$(git ls-remote --exit-code origin refs/heads/parameterized-verilog | cut -f1)" = 27af65abbee0d2334d6be7a6e4e2408b8af32fd9
          git merge-base --is-ancestor "$EXPECTED_INPUT" HEAD
          for commit in $(git rev-list "$EXPECTED_INPUT..HEAD"); do git show -s --format=%B "$commit" | grep -F '[skip ci]'; done
          git push origin "HEAD:refs/heads/$branch"
          printf 'head=%s\ntree=%s\n' "$(git rev-parse HEAD)" "$(git rev-parse HEAD^{tree})" >> "$GITHUB_OUTPUT"
          git rev-parse HEAD > /tmp/pr189-ci-transition/published-head.txt
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: pr189-ci-transition-${{ github.event.pull_request.head.sha }}-${{ github.run_attempt }}
          path: /tmp/pr189-ci-transition/
          if-no-files-found: error
          retention-days: 30

  failed-first:
    name: Run only the 20 previously failed standard workflows before full CI
    needs: seal-control
    runs-on: ubuntu-24.04
    timeout-minutes: 330
    permissions:
      contents: read
      actions: write
    env:
      QUALIFICATION_HEAD: ${{ needs.seal-control.outputs.head }}
    steps:
      - name: Dispatch or resume exact-head failed workflows and require every result
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const directory = '/tmp/pr189-failed-first'; fs.mkdirSync(directory, {recursive:true});
            const head = process.env.QUALIFICATION_HEAD;
            const branch = 'agent/cdc-independent-parameter-consumers';
            const target = '27af65abbee0d2334d6be7a6e4e2408b8af32fd9';
            fs.writeFileSync(directory+'/start.json',JSON.stringify({head,target,run_id:context.runId},null,2));
            if (!/^[0-9a-f]{40}$/.test(head)) throw new Error('Missing sealed qualification head');
            const cases = [
              ['cdc-independent-parameter-consumers.yml',35128354201],
              ['increment-59c-named-field-vectors.yml',35128354515],
              ['increment-59e-composite-reduction.yml',35079236409],
              ['increment-59g-register-bridges.yml',35128354261],
              ['increment-60a-sint-baseline.yml',35079236544],
              ['increment-60c-signed-declarations.yml',35128353956],
              ['increment-60d-pure-sint-casts.yml',35128354322],
              ['increment-60e-signedness-boundaries.yml',35128354509],
              ['increment-60f-equivalence-closure.yml',35079236525],
              ['increment-60g-default-signed-verilog.yml',35128354285],
              ['increment-61-compatibility-matrix.yml',35128354346],
              ['increment-61-one-file-per-component.yml',35128354463],
              ['increment-62-wa08-source-overlay.yml',35128354490],
              ['independent-parameter-domains.yml',35079236335],
              ['morphhdl-baseline.yml',35079236462],
              ['morphhdl-enum-localparams.yml',35079236663],
              ['morphhdl-external-symbolic-width.yml',35128354317],
              ['morphhdl-mill.yml',35079236819],
              ['morphhdl-native-source-guard.yml',35079236455],
              ['morphhdl-native-stream-width-adapter.yml',35079236383]
            ];
            // Read the raw REST envelope explicitly. Octokit's pagination plugin
            // normalizes collections, so response.data.workflow_runs is not a
            // valid mapper after that normalization (including an empty page).
            async function collect(method,params,key) {
              const rows=[];
              for(let page=1;page<=20;page++) {
                const {data}=await method({...params,per_page:100,page});
                if(!Array.isArray(data[key])) throw new Error('Unexpected API collection: '+key);
                rows.push(...data[key]);
                if(data[key].length<100 || rows.length>=data.total_count) return rows;
              }
              throw new Error('API pagination bound exceeded: '+key);
            }
            async function guard() {
              const {data:p} = await github.rest.pulls.get({...context.repo,pull_number:189});
              if (p.state !== 'open' || p.merged || p.head.sha !== head || p.head.ref !== branch ||
                  p.head.repo.full_name !== 'pysolvesemi/MorphHDL' || p.base.ref !== 'parameterized-verilog' ||
                  p.base.sha !== target) throw new Error('PR head or target changed; full CI is forbidden');
            }
            async function runs() {
              return await collect(github.rest.actions.listWorkflowRunsForRepo,
                {...context.repo,branch,head_sha:head,event:'workflow_dispatch'},'workflow_runs');
            }
            const selected=[];
            await guard();
            for (const [file,id] of cases) {
              const {data:old} = await github.rest.actions.getWorkflowRun({...context.repo,run_id:id});
              if (old.conclusion !== 'failure' || old.status !== 'completed' || old.head_branch !== branch ||
                  old.path !== '.github/workflows/'+file) throw new Error('Failed-workflow inventory changed: '+file);
              const {data:source} = await github.rest.repos.getContent({...context.repo,path:old.path,ref:head});
              if (!/^  workflow_dispatch:/m.test(Buffer.from(source.content,'base64').toString('utf8')))
                throw new Error('No selective dispatch trigger: '+file);
              selected.push({file,workflow_id:old.workflow_id,historical_failure:id});
            }
            fs.writeFileSync(directory+'/selected.json',JSON.stringify({head,target,selected},null,2));
            let existing=await runs();
            for(const row of selected) {
              await guard();
              const prior=existing.filter(r=>r.workflow_id===row.workflow_id && r.head_sha===head && r.event==='workflow_dispatch')
                .sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at))[0];
              if(prior && (prior.conclusion==='success' || prior.status!=='completed')) {
                row.run_id=prior.id;row.minimum_attempt=prior.run_attempt;core.info('REUSE '+JSON.stringify(row));
              } else if(prior && prior.conclusion==='failure') {
                await github.request('POST /repos/{owner}/{repo}/actions/runs/{run_id}/rerun-failed-jobs',{...context.repo,run_id:prior.id});
                row.run_id=prior.id;row.minimum_attempt=prior.run_attempt+1;core.info('RETRY_FAILED_JOBS '+JSON.stringify(row));
              } else {
                row.requested_at=Date.now();
                await github.rest.actions.createWorkflowDispatch({...context.repo,workflow_id:row.workflow_id,ref:branch,
                  ...(row.file==='cdc-independent-parameter-consumers.yml'?{inputs:{mode:'checks'}}:{})});
                core.info('DISPATCH_FAILED_WORKFLOW '+JSON.stringify(row));
              }
              fs.writeFileSync(directory+'/selected.json',JSON.stringify({head,target,selected},null,2));
            }
            const deadline=Date.now()+300*60*1000;
            while(Date.now()<deadline) {
              await guard();existing=await runs();
              const failures=[];let successful=0;
              for(const row of selected) {
                const matches=existing.filter(r=>r.workflow_id===row.workflow_id && r.head_sha===head && r.event==='workflow_dispatch' &&
                  (row.run_id?r.id===row.run_id:Date.parse(r.created_at)>=row.requested_at-2000));
                if(matches.length>1) throw new Error('Ambiguous exact-head run identity: '+row.file);
                if(!matches.length) continue;
                const r=matches[0];row.run_id=r.id;row.minimum_attempt ||= r.run_attempt;
                row.url=r.html_url;row.status=r.status;row.conclusion=r.conclusion;row.run_attempt=r.run_attempt;
                if(r.run_attempt<row.minimum_attempt) continue;
                if(r.status==='completed') {
                  if(r.conclusion==='success') successful++;
                  else failures.push(row);
                }
              }
              fs.writeFileSync(directory+'/selected.json',JSON.stringify({head,target,selected},null,2));
              core.info('TARGETED_PROGRESS '+successful+'/'+selected.length+' '+JSON.stringify(selected.map(r=>({file:r.file,id:r.run_id,status:r.status,conclusion:r.conclusion}))));
              if(failures.length) throw new Error('TARGETED_FAILED; full CI not started: '+JSON.stringify(failures));
              if(successful===20) {
                for(const row of selected) {
                  const jobs=await collect(github.rest.actions.listJobsForWorkflowRun,
                    {...context.repo,run_id:row.run_id,filter:'latest'},'jobs');
                  if(!jobs.some(j=>j.conclusion==='success' && j.steps && j.steps.length>2)) throw new Error('No executed qualification job: '+row.file);
                }
                await guard();
                fs.writeFileSync(directory+'/targeted-pass.json',JSON.stringify({head,target,selected},null,2));
                core.info('PR189_ALL_FAILED_WORKFLOWS_PASS '+head);return;
              }
              await new Promise(resolve=>setTimeout(resolve,45000));
            }
            throw new Error('Targeted qualification timed out; full CI not started');
      - name: Start full applicable CI only after all targeted successes on the unchanged head
        uses: actions/github-script@v7
        with:
          script: |
            const fs=require('fs');const directory='/tmp/pr189-failed-first';
            const gate=JSON.parse(fs.readFileSync(directory+'/targeted-pass.json','utf8'));
            const branch='agent/cdc-independent-parameter-consumers';
            if(gate.head!==process.env.QUALIFICATION_HEAD || gate.selected.length!==20) throw new Error('Invalid targeted gate');
            async function guard() {
              const {data:p}=await github.rest.pulls.get({...context.repo,pull_number:189});
              if(p.state!=='open' || p.merged || p.head.sha!==gate.head || p.head.ref!==branch ||
                  p.base.ref!=='parameterized-verilog' || p.base.sha!==gate.target) throw new Error('Source moved; full dispatch refused');
            }
            await guard();
            for(const row of gate.selected) {
              const {data:r}=await github.rest.actions.getWorkflowRun({...context.repo,run_id:row.run_id});
              if(r.head_sha!==gate.head || r.conclusion!=='success' || r.status!=='completed' ||
                  r.run_attempt<row.minimum_attempt || r.event!=='workflow_dispatch') throw new Error('Targeted result is not valid: '+row.file);
            }
            const {data:history}=await github.rest.actions.listWorkflowRunsForRepo({...context.repo,branch,
              head_sha:'f3c0c6fcfbeab2d9070ffd0f0c5e61fc9d77df63',event:'pull_request',per_page:100});
            if(history.total_count!==57 || history.workflow_runs.length!==57) throw new Error('Historical PR fleet needs review');
            const inventory=new Map(history.workflow_runs.map(r=>[r.path,r.workflow_id]));
            for(const row of gate.selected) inventory.set('.github/workflows/'+row.file,row.workflow_id);
            if(inventory.size!==59) throw new Error('Full qualification inventory needs review: '+inventory.size);
            // These exact historical definitions have no dispatch trigger. The
            // first three are restricted to their original implementation PR;
            // the other eight route run=false when the target already contains
            // their workflow. Do not turn those skips into qualification passes
            // or alter their conditions to manufacture extra workflow runs.
            const routedOnly={
              'increment-53d-typed-streamwidthadapter.yml':'cd2171d976b227cc7a4228987b7d317fa5d59d79',
              'increment-53e-typed-streamfifo.yml':'5b4d521b04e2e436346b86c278c2b80b4a9e5235',
              'increment-53f-typed-primitives.yml':'e5504b83e7697c064b7510f9835fdde938b922ca',
              'increment-55-concrete-compatibility-audit.yml':'d05fab68e1e88f92bbe8634f0208c261e80fdf31',
              'increment-56-native-typed-library-surface.yml':'0799647e42c1cb2c8b366009fd678ed1b212c191',
              'increment-57-broad-native-library-migration.yml':'5f0a685760765af519273e925ca818a0dc68e538',
              'increment-57a-typed-streamfifocc.yml':'02cc96023375a57712f53b5e9019dad6078d8bf7',
              'increment-57b-streamfifocc-payload-width-formal.yml':'0672e4508a36cd3b2672f95123d12da0a6631599',
              'increment-58-legacy-retirement.yml':'ab1a9376337eaa798e0662f140b5d4fc7c5aa7d0',
              'increment-59-typed-blackbox-generics.yml':'805b7fc4010e2309f1e33bc70f38e5fa50cf97c0',
              'increment-59a-recursive-verilog-module.yml':'a29ab825c2de4dfc4dcd237b33f806b3e37f24f9'
            };
            const skipped=[];
            for(const [path] of [...inventory]) {
              if(!path.startsWith('.github/workflows/') || path.includes('pr189-') || !path.endsWith('.yml')) throw new Error('Unexpected full workflow: '+path);
              const {data:source}=await github.rest.repos.getContent({...context.repo,path,ref:gate.head});
              const text=Buffer.from(source.content,'base64').toString('utf8');
              const file=path.split('/').pop();
              if(Object.prototype.hasOwnProperty.call(routedOnly,file)) {
                const {data:baseline}=await github.rest.repos.getContent({...context.repo,path,ref:gate.target});
                if(source.sha!==routedOnly[file] || baseline.sha!==routedOnly[file] || /^  workflow_dispatch:/m.test(text) ||
                    gate.selected.some(row=>row.file===file)) throw new Error('Historical routing exemption changed: '+file);
                skipped.push({path,blob:source.sha,reason:'Not applicable to this PR under its unchanged historical routing',qualification_pass:false});
                inventory.delete(path);
              } else if(!/^  workflow_dispatch:/m.test(text)) throw new Error('Unreviewed missing full-CI trigger: '+path);
            }
            if(skipped.length!==11 || inventory.size!==48) throw new Error('Applicable full-CI inventory changed');
            fs.writeFileSync(directory+'/full-applicability.json',JSON.stringify({head:gate.head,skipped,workflows:[...inventory.keys()]},null,2));
            const dispatched=[];
            for(const [path,id] of [...inventory].sort()) {
              await guard();
              await github.rest.actions.createWorkflowDispatch({...context.repo,workflow_id:id,ref:branch,
                ...(path.endsWith('/cdc-independent-parameter-consumers.yml')?{inputs:{mode:'checks'}}:{})});
              dispatched.push({path,workflow_id:id,requested_at:new Date().toISOString()});
              fs.writeFileSync(directory+'/full-dispatch.json',JSON.stringify({head:gate.head,dispatched},null,2));
              core.info('FULL_WORKFLOW_DISPATCHED '+path+' '+gate.head);
              await new Promise(resolve=>setTimeout(resolve,200));
            }
            await guard();
            core.info('PR189_FULL_CI_DISPATCHED count=48 head='+gate.head+'; dispatch receipts are not passing results');
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: pr189-failed-first-${{ needs.seal-control.outputs.head }}-${{ github.run_attempt }}
          path: /tmp/pr189-failed-first/
          if-no-files-found: error
          retention-days: 30

  full-compact-current:
    name: Full qualification of compact and independent consumers on the published commit
    needs: [seal-control, failed-first]
    runs-on: ubuntu-24.04
    timeout-minutes: 180
    container:
      image: ghcr.io/spinalhdl/docker:v1.2.0
    env:
      EXPECTED_HEAD: ${{ needs.seal-control.outputs.head }}
      EVIDENCE: /tmp/pr189-final-compact
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ needs.seal-control.outputs.head }}
          fetch-depth: 0
          submodules: recursive
          persist-credentials: false
      - name: Both Scala versions, both plugins, exact rejections and same-artifact hardware behavior
        run: |
          set -euo pipefail
          test "$(git rev-parse HEAD)" = "$EXPECTED_HEAD"
          mkdir -p "$EVIDENCE"
          git rev-parse HEAD 'HEAD^{tree}' > "$EVIDENCE/identity.txt"
          for scala in 2.12.18 2.13.12; do
            destination="$EVIDENCE/scala-$scala"
            mkdir -p "$destination"
            (
              cd repro/cdc-independent-parameters
              sbt -batch -no-colors "++$scala!" \
                "runMain spinal.core.CompactTimeoutGenerate $destination/first" \
                "runMain spinal.core.CompactTimeoutGenerate $destination/repeat" \
                "runMain spinal.core.CompactTimeoutSafety $destination/safety" \
                "runMain spinal.core.CdcConsumerSuccess $destination/consumers" \
                "runMain spinal.core.CdcConsumerSuccess $destination/consumers-repeat" \
                "runMain spinal.core.CdcConsumerSafety $destination/consumer-safety" \
                2>&1 | tee "$destination/compiler.log"
              grep -F 'COMPACT_TIMEOUT_SAFETY_PASS controls=9' "$destination/compiler.log"
              grep -F 'COMPACT_PHYSICAL_WIDTH_REJECTION_PASS' "$destination/compiler.log"
              python3 check_compact_timeout.py "$destination/first" "$destination/repeat" "$destination/validation" \
                2>&1 | tee "$destination/timer-validation.log"
              python3 check_consumers.py "$destination/consumers" "$destination/consumers-repeat" "$destination/consumer-validation" \
                2>&1 | tee "$destination/consumer-validation.log"
            )
            sbt -batch -no-colors "++$scala" core/Test/test morph/Test/test \
              2>&1 | tee "$destination/affected-regressions.log"
          done
          diff -ru "$EVIDENCE/scala-2.12.18/first" "$EVIDENCE/scala-2.13.12/first"
          diff -ru "$EVIDENCE/scala-2.12.18/consumers" "$EVIDENCE/scala-2.13.12/consumers"
          test "$(git rev-parse HEAD)" = "$EXPECTED_HEAD"
          git diff --exit-code
          git diff --cached --exit-code
      - name: Preserve all 18 source and mutation gates on the exact final source
        run: |
          set -euo pipefail
          checks=(
            'git diff --check'
