            if(receipt.input!==run.head_sha||receipt.candidate!==head||receipt.tree!==git('rev-parse','HEAD^{tree}')||receipt.target!==target||receipt.left!==left||receipt.source_groups!==23||receipt.compiler_sources_unchanged!==true||git('show','-s','--format=%P','HEAD')!==run.head_sha)throw new Error('Wrong exact sealed candidate');
