val default = projectedDefault(left) == projectedDefault(right)
val exactDomain = combineIntegerBooleanDomains(left, right)(_ == _)
val normalized = encodedPredicate(left, right)
  .orElse(encodedPredicate(right, left))

package spinal.core

import java.lang.ref.{ReferenceQueue, WeakReference}
import scala.collection.mutable

/** Authenticated symbolic expressions, with a separate on-demand exact proof engine.
  *
  * A private identity-bound expression certificate authenticates the AST, original
  * declaration objects and active restrictions. It is NOT a claim that every
  * parameter tuple has been evaluated. Native publication uses a compositional
  * conservative enclosure derived here from authenticated leaves; callers needing
  * attainable extrema or structural decisions explicitly invoke the stronger
  * bounded proof engine. Public case-class copies inherit neither authority.
  * Cancelled dependencies remain in the certificate's scope inventory.
  */
private[spinal] object ElaborationProductDomain {
  private val Role = "typed product-domain expression"
  private val Missing = "SPINAL-ELAB-DOMAIN-PRODUCT-AUTHORITY-MISSING"
  private val Unsupported = "SPINAL-ELAB-DOMAIN-PRODUCT-CORRELATION-UNSUPPORTED"
  private val MaximumJointValues = ElaborationExactDomain.MaximumDomainSize
  private val MaximumTerms = 256
  private val MaximumAxes = 32

  private type Root = ElaborationIntegerParameterRoot
  private type Environment = Map[Root, BigInt]

  // A compact axis is an authenticated closed interval, never a sampled
  // exact-domain table. Its empty finite-storage vector is NOT an admitted
  // universe; every operation which needs enumeration rejects it explicitly.
  private final case class Axis(domain: Option[ElaborationExactDomain[_]], root: Root,
                                schema: ElaborationIntegerParameter, values: Vector[BigInt]) {
    def compact: Boolean = domain.isEmpty
    def cardinality: BigInt = if (compact) schema.maximum - schema.minimum + 1 else BigInt(values.size)
    def containsValue(value: BigInt): Boolean =
      if (compact) value >= schema.minimum && value <= schema.maximum else values.contains(value)
    def representative: BigInt =
      if (compact || values.contains(schema.default)) schema.default else values.min
    def sameScope(that: Axis): Boolean = compact == that.compact && values == that.values
    def enumerationValues: Vector[BigInt] = {
      if (compact) fail("SPINAL-ELAB-DOMAIN-COMPACT-ENUMERATION-UNSUPPORTED",
        "this consumer requires exhaustive values, not compact declaration authority", root.sourceLocation)
      values
    }
  }
  private object Axis {
    def apply(domain: ElaborationExactDomain[_], values: Vector[BigInt]): Axis =
      new Axis(Some(domain), domain.root, domain.parameter, values)
    def compact(root: Root, schema: ElaborationIntegerParameter): Axis =
      new Axis(None, root, schema, Vector.empty)
  }
  private final case class Extrema(minimum: BigInt, maximum: BigInt) {
    def constant: Boolean = minimum == maximum
    def scale(coefficient: BigInt): Extrema =
      if (coefficient >= 0) Extrema(minimum * coefficient, maximum * coefficient)
      else Extrema(maximum * coefficient, minimum * coefficient)
  }

  private sealed trait Atom {
    def roots: Set[Root]
    def evaluate(values: Environment): BigInt
  }
  private final case class CompactLeaf(root: Root) extends Atom {
    val roots: Set[Root] = Set(root)
    def evaluate(environment: Environment): BigInt = environment(root)
  }
  private final case class Leaf(root: Root, values: Map[BigInt, BigInt]) extends Atom {
    val roots: Set[Root] = Set(root)
    def evaluate(environment: Environment): BigInt = values(environment(root))
  }
  private final case class Operation(operator: String, operands: Vector[Form]) extends Atom {
    lazy val roots: Set[Root] = operands.flatMap(_.roots).toSet
    def evaluate(environment: Environment): BigInt = {
      def at(index: Int): BigInt = operands(index).evaluate(environment)
      operator match {
        case "*" => at(0) * at(1)
        case "/" => at(0) / at(1)
        case "%" => at(0) % at(1)
        case "min" => at(0).min(at(1))
        case "max" => at(0).max(at(1))
        case "<" => boolean(at(0) < at(1))
        case "==" => boolean(at(0) == at(1))
        case "&&" => boolean(at(0) != 0 && at(1) != 0)
        case "||" => boolean(at(0) != 0 || at(1) != 0)
        case "choose" => if (at(0) != 0) at(1) else at(2)
        case "log2Up" => if (at(0) == 0) BigInt(0) else BigInt((at(0) - 1).bitLength)
        case "addressWidth" => BigInt(math.max(1, (at(0) - 1).bitLength))
        case "pow2" => BigInt(1) << at(0).toInt
        case "isPow2" => boolean(at(0) >= 0 && at(0).bitCount == 1)
        case other => throw new IllegalArgumentException(s"unknown certified operator '$other'")
      }
    }
  }
  private final case class Form(constant: BigInt, terms: Map[Atom, BigInt]) {
    lazy val roots: Set[Root] = terms.keysIterator.flatMap(_.roots).toSet
    def evaluate(environment: Environment): BigInt =
      terms.foldLeft(constant) { case (value, (atom, coefficient)) =>
        value + coefficient * atom.evaluate(environment)
      }
    def scale(coefficient: BigInt): Form =
      if (coefficient == 0) literal(0)
      else Form(constant * coefficient, terms.map { case (atom, value) => atom -> (value * coefficient) })
    def +(that: Form): Form = {
      val merged = that.terms.foldLeft(terms) { case (known, (atom, coefficient)) =>
        val sum = known.getOrElse(atom, BigInt(0)) + coefficient
        if (sum == 0) known - atom else known.updated(atom, sum)
      }
      if (merged.size > MaximumTerms)
        fail(Unsupported, s"normalized expression exceeds $MaximumTerms terms", None)
      Form(constant + that.constant, merged)
    }
    def -(that: Form): Form = this + that.scale(-1)
  }
  private def literal(value: BigInt): Form = Form(value, Map.empty)
  private def atom(value: Atom): Form = Form(0, Map(value -> BigInt(1)))
  private def boolean(value: Boolean): BigInt = if (value) BigInt(1) else BigInt(0)
  private def operation(operator: String, left: Form, right: Form): Form = operator match {
    case "+" => left + right
    case "-" => left - right
    case "*" if left.terms.isEmpty => right.scale(left.constant)
    case "*" if right.terms.isEmpty => left.scale(right.constant)
    case ">" => atom(Operation("<", Vector(right, left)))
    case "<=" => literal(1) - atom(Operation("<", Vector(right, left)))
    case ">=" => literal(1) - atom(Operation("<", Vector(left, right)))
    case _ => atom(Operation(operator, Vector(left, right)))
  }

  private final case class TrustedExpressionEvidence(form: Form, axes: Vector[Axis])
  private final class Identity(value: AnyRef, queue: ReferenceQueue[AnyRef])
      extends WeakReference[AnyRef](value, queue) {
    private val hash = System.identityHashCode(value)
    override def hashCode(): Int = hash
    override def equals(other: Any): Boolean = other match {
      case that: Identity => (this eq that) || ((get ne null) && (get eq that.get))
      case _ => false
    }
  }
  private val queue = new ReferenceQueue[AnyRef]()
  private val retained = mutable.HashMap.empty[Identity, TrustedExpressionEvidence]
  private def reap(): Unit = {
    var reference = queue.poll()
    while (reference != null) {
      retained.remove(reference.asInstanceOf[Identity])
      reference = queue.poll()
    }
  }
  private def certificate(value: AnyRef): Option[TrustedExpressionEvidence] = synchronized {
    reap()
    if (value == null) None else retained.get(new Identity(value, null))
  }
  private def retain(value: AnyRef, proof: TrustedExpressionEvidence): Unit = synchronized {
    reap()
    retained.put(new Identity(value, queue), proof)
    ()
  }
  /** Classification only: the publication caller must separately validate
    * the exact live owner. Public schemas or equal names cannot mint this bit.
    */
  private[core] def hasCompactParameter(value: ElaborationIntegerExpression,
      parameter: ElaborationIntegerParameter): Boolean =
    certificate(value).exists(_.axes.exists(axis => axis.compact &&
      (axis.schema eq parameter) && axis.root.isAuthoritativeSchema(parameter)))

  private[core] def isRetained(value: ElaborationIntegerExpression): Boolean = certificate(value).nonEmpty
  private[core] def isRetained(value: ElaborationBooleanExpression): Boolean = certificate(value).nonEmpty
  private[core] def needs(left: ElaborationIntegerExpression, right: ElaborationIntegerExpression): Boolean =
    isRetained(left) || isRetained(right) ||
      (left.completedParameterRoots ++ right.completedParameterRoots).distinct.size > 1
  private[core] def needs(left: ElaborationBooleanExpression, right: ElaborationBooleanExpression): Boolean =
    isRetained(left) || isRetained(right) ||
      (left.completedParameterRoots ++ right.completedParameterRoots).distinct.size > 1

  private def fail(code: String, detail: String, location: Option[String]): Nothing =
    ParameterizedVerilogException.fail(code, s"$Role $detail", location)

  /** The only compact ingress: a one-use permit for a bare frontend
    * declaration AST, not a public expression summary or sampled table.
    */
  private[core] def compactDeclaration(value: ElaborationIntegerExpression,
      sourceIdentity: AnyRef, permit: ExternalCompilerPermit): ElaborationIntegerExpression = {
    ExternalCompilerPermit.requireAnalyzedCompactDeclaration(permit, value, sourceIdentity)
    ElabInt.validateExpression(value, "compact parameter declaration")
    if (ElaborationDomainContext.hasActiveRestrictions)
      fail("SPINAL-ELAB-DOMAIN-COMPACT-SCOPE-UNSUPPORTED",
        "compact declarations cannot be minted in a structural branch", value.sourceLocation)
    val schema = value.parameters match {
      case Vector(parameter) => parameter
      case _ => fail(Missing, "compact ingress needs exactly one declaration", value.sourceLocation)
    }
    val root = value.completedParameterRoots match {
      case Vector(declaration) => declaration
      case _ => fail(Missing, "compact ingress lost its exact root", value.sourceLocation)
    }
    if (schema.minimum < 1 || !schema.maximum.isValidInt ||
        schema.maximum - schema.minimum + 1 <= MaximumJointValues ||
        value.default != schema.default || value.minimum != schema.minimum || value.maximum != schema.maximum ||
        value.verilog != schema.name || root.name != schema.name ||
        value.generateIndex.nonEmpty || value.exactDomain.nonEmpty || value.projectionProvenance.nonEmpty)
      fail("SPINAL-ELAB-DOMAIN-COMPACT-DECLARATION-INVALID",
        "compact ingress requires an unchanged positive Int-sized direct declaration", value.sourceLocation)
    root.bindAuthoritativeSchema(schema, "compact parameter declaration", value.sourceLocation)
    retain(value, TrustedExpressionEvidence(atom(CompactLeaf(root)), Vector(Axis.compact(root, schema))))
    value
  }

  private def merge(sources: Vector[TrustedExpressionEvidence], location: Option[String]): Vector[Axis] = {
    val axes = sources.flatMap(_.axes).foldLeft(Vector.empty[Axis]) { (known, axis) =>
      known.find(_.root.name == axis.root.name) match {
        case Some(previous) if previous.schema != axis.schema =>
          fail("SPINAL-ELAB-INT-PARAMETER-SCHEMA-CONFLICT",
            s"has conflicting schemas for '${axis.root.name}'", location)
        case Some(previous) if (previous.root ne axis.root) || (previous.schema ne axis.schema) =>
          fail("SPINAL-ELAB-INT-INDEPENDENT-ROOTS-UNSUPPORTED",
            s"has distinct declarations for the same emitted name '${axis.root.name}'", location)
        case Some(previous) if !previous.sameScope(axis) =>
          fail("SPINAL-ELAB-DOMAIN-EVIDENCE-SCOPE-MISMATCH",
            s"has incompatible authorized scopes for '${axis.root.name}'", location)
        case Some(_) => known
        case None => known :+ axis
      }
    }.sortBy(_.root.name)
    if (axes.size > MaximumAxes)
      fail(Unsupported, s"exceeds $MaximumAxes independent axes", location)
    axes
  }

  private def active(proof: TrustedExpressionEvidence, role: String, location: Option[String]): TrustedExpressionEvidence = {
    val axes = proof.axes.map { axis =>
      if (axis.compact) {
        // This first compact ingress deliberately grants no branch projection.
        if (ElaborationDomainContext.hasActiveRestrictions)
          fail("SPINAL-ELAB-DOMAIN-COMPACT-SCOPE-UNSUPPORTED",
            s"$role cannot use a compact declaration under structural restrictions", location)
        axis
      } else {
        val requested = ElaborationDomainContext.admitted(axis.domain.get)
        if (requested.isEmpty || !requested.subsetOf(axis.values.toSet))
          fail("SPINAL-ELAB-DOMAIN-EVIDENCE-SCOPE-MISMATCH",
            s"$role cannot use '${axis.root.name}' outside its authorized branch", location)
        axis.copy(values = requested.toVector.sorted)
      }
    }
    proof.copy(axes = axes)
  }
  private def validateInventory(parameters: Vector[ElaborationIntegerParameter], roots: Vector[Root],
                                proof: TrustedExpressionEvidence, role: String, location: Option[String]): Unit = {
    if (roots.size != proof.axes.size || parameters.size != proof.axes.size || proof.axes.exists { axis =>
        !roots.exists(_ eq axis.root) || !parameters.exists(_ eq axis.schema) ||
          !axis.root.isAuthoritativeSchema(axis.schema)
      }) fail(Missing, s"$role lost its declaration/schema identities", location)
  }
  private[core] def requireInteger(value: ElaborationIntegerExpression, role: String): Unit = {
    ElabInt.validateExpression(value, role)
    val proof = certificate(value).getOrElse(fail(Missing, s"$role lacks its private certificate", value.sourceLocation))
    if (value.generateIndex.nonEmpty) fail(Missing, s"$role includes a generate index", value.sourceLocation)
    validateInventory(value.parameters, value.completedParameterRoots, proof, role, value.sourceLocation)
    active(proof, role, value.sourceLocation)
    ()
  }
  private[core] def requireBoolean(value: ElaborationBooleanExpression, role: String): Unit = {
    ElabInt.validateExpression(value, role)
    val proof = certificate(value).getOrElse(fail(Missing, s"$role lacks its private certificate", value.sourceLocation))
    validateInventory(value.parameters, value.completedParameterRoots, proof, role, value.sourceLocation)
    active(proof, role, value.sourceLocation)
    ()
  }

  private def source(value: ElaborationIntegerExpression): TrustedExpressionEvidence = certificate(value) match {
    case Some(proof) =>
      requireInteger(value, Role)
      active(proof, Role, value.sourceLocation)
    case None =>
      val exact = ElabInt.requireAuthoritativeIntegerDomain(value, Role, Missing, requireExactExtrema = false)
      exact match {
        case None => TrustedExpressionEvidence(literal(value.default), Vector.empty)
        case Some(domain) =>
          val values = ElaborationDomainContext.requireEvidence(domain, Role, value.sourceLocation).toVector.sorted
          TrustedExpressionEvidence(atom(Leaf(domain.root, domain.evaluations.toMap)), Vector(Axis(domain, values)))
      }
  }
  private def source(value: ElaborationBooleanExpression): TrustedExpressionEvidence = certificate(value) match {
    case Some(proof) =>
      requireBoolean(value, Role)
      active(proof, Role, value.sourceLocation)
    case None =>
      val exact = ElabInt.requireAuthoritativeBooleanDomain(value, Role, Missing)
      exact match {
        case None => TrustedExpressionEvidence(literal(boolean(value.default)), Vector.empty)
        case Some(domain) =>
          val values = ElaborationDomainContext.requireEvidence(domain, Role, value.sourceLocation).toVector.sorted
          TrustedExpressionEvidence(atom(Leaf(domain.root, domain.evaluations.map { case (key, result) => key -> boolean(result) }.toMap)),
            Vector(Axis(domain, values)))
      }
  }
  private def representative(axes: Vector[Axis]): Environment = axes.map { axis =>
    axis.root -> axis.representative
  }.toMap
  private def relevant(roots: Set[Root], axes: Vector[Axis]): Vector[Axis] = axes.filter(axis => roots(axis.root))
  private def domainSize(axes: Vector[Axis]): BigInt = axes.foldLeft(BigInt(1))((n, axis) => n * axis.cardinality)

  /** Streaming fallback: no product vector is built, and only overlapping
    * dependencies enter this evaluator. The cap is a rejection, not a sample.
    */
  private def foreachTuple(axes: Vector[Axis], location: Option[String])(body: Environment => Unit): Unit = {
    val size = domainSize(axes)
    if (size > MaximumJointValues)
      fail(Unsupported, s"non-separable correlation requires $size tuples, above the exact fallback limit $MaximumJointValues",
        location)
    def visit(index: Int, values: Environment): Unit = {
      if (index == axes.size) body(values)
      else axes(index).values.foreach(value => visit(index + 1, values.updated(axes(index).root, value)))
    }
    visit(0, Map.empty)
  }
  private def enumerate(form: Form, axes: Vector[Axis], location: Option[String]): Extrema = {
    var low: Option[BigInt] = None
    var high: Option[BigInt] = None
    foreachTuple(relevant(form.roots, axes), location) { values =>
      val result = form.evaluate(values)
      low = Some(low.fold(result)(_.min(result)))
      high = Some(high.fold(result)(_.max(result)))
    }
    Extrema(low.get, high.get)
  }
  private def image(form: Form, axes: Vector[Axis], location: Option[String]): Set[BigInt] = {
    val results = mutable.HashSet.empty[BigInt]
    foreachTuple(relevant(form.roots, axes), location)(values => results += form.evaluate(values))
    results.toSet
  }

  private def bounds(form: Form, axes: Vector[Axis], location: Option[String]): Extrema = {
    // Connected components, not a binary 'different roots' heuristic: a term
    // depending on {a,b} and one depending on {b,c} belong to the same proof.
    var groups = Vector.empty[Map[Atom, BigInt]]
    form.terms.foreach { case term @ (current, _) =>
      val (overlap, disjoint) = groups.partition(group =>
        group.keysIterator.exists(other => (current.roots intersect other.roots).nonEmpty))
      groups = disjoint :+ (overlap.foldLeft(Map(term))(_ ++ _))
    }
    // A new component may connect earlier components transitively; the fold
    // above merges all of them at once, preserving that connected closure.
    val limits = groups.map { group =>
      if (group.size == 1) {
        val (value, coefficient) = group.head
        atomBounds(value, axes, location).scale(coefficient)
      } else enumerate(Form(0, group), axes, location)
    }
    Extrema(form.constant + limits.map(_.minimum).sum, form.constant + limits.map(_.maximum).sum)
  }
  private def atomBounds(value: Atom, axes: Vector[Axis], location: Option[String]): Extrema = value match {
    case CompactLeaf(root) =>
      val axis = axes.find(_.root eq root).get
      Extrema(axis.schema.minimum, axis.schema.maximum)
    case leaf: Leaf =>
      val values = axes.find(_.root eq leaf.root).get.values.map(leaf.values)
      Extrema(values.min, values.max)
    case current @ Operation(operator, operands) =>
      def b(index: Int): Extrema = bounds(operands(index), axes, location)
      def fallback: Extrema = enumerate(atom(current), axes, location)
      def independent: Boolean = (operands(0).roots intersect operands(1).roots).isEmpty
      operator match {
        case "*" =>
          val l = b(0); val r = b(1)
          if (independent || l.constant || r.constant) {
            val corners = Vector(l.minimum * r.minimum, l.minimum * r.maximum,
              l.maximum * r.minimum, l.maximum * r.maximum)
            Extrema(corners.min, corners.max)
          } else fallback
        case "/" =>
          val l = b(0); val r = b(1)
          if (l.minimum < 0 || r.minimum <= 0)
            fail("SPINAL-ELAB-INT-DIVISION-DOMAIN-UNSUPPORTED", "division needs a non-negative dividend and positive divisor", location)
          if (independent || r.constant) Extrema(l.minimum / r.maximum, l.maximum / r.minimum)
          else fallback
        case "%" =>
          val l = b(0); val r = b(1)
          if (l.minimum < 0 || r.minimum <= 0)
            fail("SPINAL-ELAB-INT-MODULO-DOMAIN-UNSUPPORTED", "remainder needs a non-negative dividend and positive divisor", location)
          if (operands(0) == operands(1) || (r.constant && r.minimum == 1)) Extrema(0, 0)
          else if (l.maximum < r.minimum) l
          else fallback
        case "<" =>
          val difference = bounds(operands(0) - operands(1), axes, location)
          if (difference.maximum < 0) Extrema(1, 1)
          else if (difference.minimum >= 0) Extrema(0, 0)
          else Extrema(0, 1) // both attained extrema give opposite truth values
        case "==" =>
          val difference = bounds(operands(0) - operands(1), axes, location)
          if (difference.minimum == 0 && difference.maximum == 0) Extrema(1, 1)
          else if (difference.minimum > 0 || difference.maximum < 0) Extrema(0, 0)
          else if (difference.minimum == 0 || difference.maximum == 0) Extrema(0, 1)
          else if (independent) {
            val l = image(operands(0), axes, location)
            val r = image(operands(1), axes, location)
            if ((l intersect r).isEmpty) Extrema(0, 0)
            else if (l.size == 1 && r.size == 1) Extrema(1, 1)
            else Extrema(0, 1)
          } else fallback
        case "&&" | "||" =>
          val l = b(0); val r = b(1)
          if (operator == "&&" && (l.maximum == 0 || r.maximum == 0)) Extrema(0, 0)
          else if (operator == "||" && (l.minimum == 1 || r.minimum == 1)) Extrema(1, 1)
          else if (l.constant) r
          else if (r.constant || operands(0) == operands(1)) l
          else if (operands(0) + operands(1) == literal(1))
            if (operator == "&&") Extrema(0, 0) else Extrema(1, 1)
          else if (independent) Extrema(0, 1)
          else fallback
        case "min" | "max" =>
          val difference = bounds(operands(0) - operands(1), axes, location)
          if (difference.minimum >= 0) b(if (operator == "max") 0 else 1)
          else if (difference.maximum <= 0) b(if (operator == "max") 1 else 0)
          else if (independent) {
            val l = b(0); val r = b(1)
            if (operator == "max") Extrema(l.minimum.max(r.minimum), l.maximum.max(r.maximum))
            else Extrema(l.minimum.min(r.minimum), l.maximum.min(r.maximum))
          } else fallback
        case "choose" =>
          val guard = b(0)
          if (guard.constant) b(if (guard.minimum != 0) 1 else 2)
          else if (operands(1) == operands(2)) b(1)
          else if ((operands(0).roots intersect (operands(1).roots ++ operands(2).roots)).isEmpty) {
            val yes = b(1); val no = b(2)
            Extrema(yes.minimum.min(no.minimum), yes.maximum.max(no.maximum))
          } else if (operands(0).roots.size == 1) {
            val root = operands(0).roots.head
            val axis = axes.find(_.root eq root).get
            val (yesValues, noValues) = axis.enumerationValues.partition(value => operands(0).evaluate(Map(root -> value)) != 0)
            val choices = Vector(yesValues -> operands(1), noValues -> operands(2)).collect {
              case (values, arm) if values.nonEmpty =>
                bounds(arm, axes.map(a => if (a.root eq root) a.copy(values = values) else a), location)
            }
            Extrema(choices.map(_.minimum).min, choices.map(_.maximum).max)
          } else fallback
        case "log2Up" | "addressWidth" =>
          val input = b(0)
          if (operator == "log2Up" && input.minimum < 0)
            fail("SPINAL-ELAB-INT-LOG2-DOMAIN-NEGATIVE", "log2Up input must stay non-negative", location)
          if (operator == "addressWidth" && input.minimum < 1)
            fail("SPINAL-ELAB-INT-ADDRESS-WIDTH-DOMAIN-NONPOSITIVE", "addressWidth input must stay positive", location)
          def evaluate(value: BigInt): BigInt =
            if (operator == "addressWidth") BigInt(math.max(1, (value - 1).bitLength))
            else if (value == 0) BigInt(0) else BigInt((value - 1).bitLength)
          Extrema(evaluate(input.minimum), evaluate(input.maximum))
        case "pow2" =>
          val input = b(0)
          if (input.minimum < 0 || input.maximum > 30)
            fail("SPINAL-ELAB-INT-POW2-DOMAIN-INVALID", "power-of-two exponent must be in 0..30", location)
          Extrema(BigInt(1) << input.minimum.toInt, BigInt(1) << input.maximum.toInt)
        case "isPow2" => fallback
        case other => throw new IllegalArgumentException(s"unknown certified operator '$other'")
      }
  }

  /** A sound enclosure, not necessarily attainable extrema. No Cartesian
    * evaluator, image enumeration or exact `bounds` call is permitted here.
    */
  private final case class Enclosure(minimum: BigInt, maximum: BigInt) {
    def constant: Boolean = minimum == maximum
    def scale(k: BigInt): Enclosure =
      if (k >= 0) Enclosure(minimum * k, maximum * k)
      else Enclosure(maximum * k, minimum * k)
  }
  private def enclosure(proof: TrustedExpressionEvidence, location: Option[String]): Enclosure = {
    val memo = mutable.HashMap.empty[Form, Enclosure]
    def visit(form: Form): Enclosure = memo.getOrElseUpdate(form, {
      val parts = form.terms.toVector.map { case (value, k) => atomEnclosure(value).scale(k) }
      Enclosure(form.constant + parts.map(_.minimum).sum, form.constant + parts.map(_.maximum).sum)
    })
    def atomEnclosure(value: Atom): Enclosure = value match {
      case CompactLeaf(root) =>
        val axis = proof.axes.find(_.root eq root).get
        Enclosure(axis.schema.minimum, axis.schema.maximum)
      case leaf: Leaf =>
        val values = proof.axes.find(_.root eq leaf.root).get.values.map(leaf.values)
        Enclosure(values.min, values.max)
      case Operation(operator, operands) =>
        def b(i: Int): Enclosure = visit(operands(i))
        operator match {
          case "*" =>
            val l = b(0); val r = b(1)
            val corners = Vector(l.minimum * r.minimum, l.minimum * r.maximum,
              l.maximum * r.minimum, l.maximum * r.maximum)
            Enclosure(corners.min, corners.max)
          case "/" | "%" =>
            val l = b(0); val r = b(1)
            if (l.minimum < 0 || r.minimum <= 0)
              fail(if (operator == "/") "SPINAL-ELAB-INT-DIVISION-DOMAIN-UNSUPPORTED"
                else "SPINAL-ELAB-INT-MODULO-DOMAIN-UNSUPPORTED",
                "division/remainder needs a non-negative dividend and positive divisor", location)
            if (operator == "/") Enclosure(l.minimum / r.maximum, l.maximum / r.minimum)
            else if (operands(0) == operands(1) || (r.constant && r.minimum == 1)) Enclosure(0, 0)
            else if (l.maximum < r.minimum) l
            else Enclosure(0, l.maximum.min(r.maximum - 1))
          case "<" | "==" =>
            val difference = visit(operands(0) - operands(1))
            if (operator == "<") {
              if (difference.maximum < 0) Enclosure(1, 1)
              else if (difference.minimum >= 0) Enclosure(0, 0)
              else Enclosure(0, 1)
            } else {
              if (difference.constant && difference.minimum == 0) Enclosure(1, 1)
              else if (difference.minimum > 0 || difference.maximum < 0) Enclosure(0, 0)
              else Enclosure(0, 1)
            }
          case "&&" | "||" =>
            val l = b(0); val r = b(1)
            if (operator == "&&" && (l.maximum == 0 || r.maximum == 0)) Enclosure(0, 0)
            else if (operator == "||" && (l.minimum == 1 || r.minimum == 1)) Enclosure(1, 1)
            else if (l.constant) r
            else if (r.constant || operands(0) == operands(1)) l
            else if (operands(0) + operands(1) == literal(1))
              if (operator == "&&") Enclosure(0, 0) else Enclosure(1, 1)
            else Enclosure(0, 1)
          case "min" | "max" =>
            val l = b(0); val r = b(1)
            if (operator == "max") Enclosure(l.minimum.max(r.minimum), l.maximum.max(r.maximum))
            else Enclosure(l.minimum.min(r.minimum), l.maximum.min(r.maximum))
          case "choose" =>
            val c = b(0); val y = b(1); val n = b(2)
            if (c.constant) if (c.minimum == 1) y else n
            else Enclosure(y.minimum.min(n.minimum), y.maximum.max(n.maximum))
          case "log2Up" | "addressWidth" =>
            val v = b(0)
            if (operator == "log2Up" && v.minimum < 0)
              fail("SPINAL-ELAB-INT-LOG2-DOMAIN-NEGATIVE", "log2Up input must stay non-negative", location)
            if (operator == "addressWidth" && v.minimum < 1)
              fail("SPINAL-ELAB-INT-ADDRESS-WIDTH-DOMAIN-NONPOSITIVE", "addressWidth input must stay positive", location)
            def f(n: BigInt): BigInt = if (operator == "addressWidth") BigInt(math.max(1, (n - 1).bitLength))
              else if (n == 0) BigInt(0) else BigInt((n - 1).bitLength)
            Enclosure(f(v.minimum), f(v.maximum))
          case "pow2" =>
            val v = b(0)
            if (v.minimum < 0 || v.maximum > 30)
              fail("SPINAL-ELAB-INT-POW2-DOMAIN-INVALID", "power-of-two exponent must be in 0..30", location)
            Enclosure(BigInt(1) << v.minimum.toInt, BigInt(1) << v.maximum.toInt)
          case "isPow2" => Enclosure(0, 1)
          case other => throw new IllegalArgumentException(s"unknown authenticated operator '$other'")
        }
    }
    visit(proof.form)
  }
  private def checkedEnclosure(proof: TrustedExpressionEvidence, location: Option[String]): Enclosure = {
    val result = enclosure(proof, location)
    if (!result.minimum.isValidInt || !result.maximum.isValidInt)
      fail("SPINAL-ELAB-DOMAIN-EVIDENCE-RESULT-OUT-OF-RANGE",
        s"cannot establish checked Int arithmetic inside [${result.minimum}, ${result.maximum}]", location)
    result
  }

  /** Stronger observation: structural/native-library consumers may explicitly
    * request attainable extrema. This can fail when joint proof exceeds the cap.
    */
  private[core] def exactLimits(value: ElaborationIntegerExpression): (BigInt, BigInt) = {
    val result = checkedExtrema(source(value), value.sourceLocation)
    result.minimum -> result.maximum
  }
  private[core] def publicationTruth(value: ElaborationBooleanExpression): ElabBool.Truth = {
    val result = enclosure(source(value), value.sourceLocation)
    if (result.minimum == 1) ElabBool.AlwaysTrue
    else if (result.maximum == 0) ElabBool.AlwaysFalse
    else ElabBool.Unknown // not a claim that both outcomes have witnesses
  }

  /** Physical publication of a potentially non-positive packed width. The
    * clamped expression has its own authenticated AST; raw positivity is a
    * separate legality obligation, never fabricated as exact raw-width evidence.
    */
  private[core] def safePackedWidth(value: ElaborationIntegerExpression): ElaborationIntegerExpression = {
    val proof = source(value)
    publishInteger(s"(($$signed(${value.verilog}) > 0) ? ${value.verilog} : 1)",
      proof.copy(form = operation("max", proof.form, literal(1))), value.sourceLocation)
  }

  private def checkedExtrema(proof: TrustedExpressionEvidence, location: Option[String]): Extrema = {
    val limits = bounds(proof.form, proof.axes, location)
    if (!limits.minimum.isValidInt || !limits.maximum.isValidInt)
      fail("SPINAL-ELAB-DOMAIN-EVIDENCE-RESULT-OUT-OF-RANGE",
        s"reaches [${limits.minimum}, ${limits.maximum}] outside the Scala/Verilog Int domain", location)
    limits
  }
  private def publishInteger(verilog: String, proof: TrustedExpressionEvidence,
                             location: Option[String]): ElaborationIntegerExpression = {
    val limits = checkedEnclosure(proof, location)
    val default = proof.form.evaluate(representative(proof.axes))
    if (proof.axes.isEmpty)
      return ElaborationIntegerExpression(default.toString, default, default, default, Vector.empty, sourceLocation = location)
    val result = ElaborationIntegerExpression(verilog, default, limits.minimum, limits.maximum,
      proof.axes.map(_.schema), sourceLocation = location, parameterRoots = proof.axes.map(_.root))
    // Retain the complete dependency/scope inventory even for an exactly
    // constant function. A cancelled branch-local root must not escape.
    retain(result, if (limits.constant) proof.copy(form = literal(limits.minimum)) else proof)
    result
  }
  private def publishBoolean(verilog: String, proof: TrustedExpressionEvidence, location: Option[String]): ElabBool = {
    val limits = enclosure(proof, location)
    if (limits.minimum < 0 || limits.maximum > 1)
      fail(Missing, "Boolean derivation is not exactly 0/1", location)
    val result = ElaborationBooleanExpression(verilog, proof.form.evaluate(representative(proof.axes)) != 0,
      proof.axes.map(_.schema), sourceLocation = location, parameterRoots = proof.axes.map(_.root))
    retain(result, if (limits.constant) proof.copy(form = literal(limits.minimum)) else proof)
    ElabBool(result, if (limits.minimum == 1) ElabBool.AlwaysTrue
      else if (limits.maximum == 0) ElabBool.AlwaysFalse else ElabBool.Unknown)
  }
  private def truth(limits: Extrema): ElabBool.Truth =
    if (limits.minimum == 1) ElabBool.AlwaysTrue
    else if (limits.maximum == 0) ElabBool.AlwaysFalse
    else ElabBool.Unknown

  private[core] def integer(operator: String, left: ElaborationIntegerExpression,
                            right: ElaborationIntegerExpression): ElaborationIntegerExpression = {
    val l = source(left); val r = source(right)
    val location = left.sourceLocation.orElse(right.sourceLocation)
    publishInteger(s"(${left.verilog} $operator ${right.verilog})",
      TrustedExpressionEvidence(operation(operator, l.form, r.form), merge(Vector(l, r), location)), location)
  }
  private[core] def compare(operator: String, left: ElaborationIntegerExpression,
                            right: ElaborationIntegerExpression): ElabBool = {
    val l = source(left); val r = source(right)
    val location = left.sourceLocation.orElse(right.sourceLocation)
    publishBoolean(s"($$signed(${left.verilog}) $operator $$signed(${right.verilog}))",
      TrustedExpressionEvidence(operation(operator, l.form, r.form), merge(Vector(l, r), location)), location)
  }
  private[core] def logical(operator: String, left: ElaborationBooleanExpression,
                            right: ElaborationBooleanExpression): ElabBool = {
    val l = source(left); val r = source(right)
    val location = left.sourceLocation.orElse(right.sourceLocation)
    publishBoolean(s"($$signed(${left.verilog}) $operator $$signed(${right.verilog}))",
      TrustedExpressionEvidence(operation(operator, l.form, r.form), merge(Vector(l, r), location)), location)
  }
  private[core] def not(value: ElaborationBooleanExpression): ElabBool = {
    val proof = source(value)
    publishBoolean(s"!(${value.verilog})", proof.copy(form = literal(1) - proof.form), value.sourceLocation)
  }
  private[core] def toInteger(value: ElaborationBooleanExpression): ElaborationIntegerExpression =
    publishInteger(s"((${value.verilog}) ? 1 : 0)", source(value), value.sourceLocation)
  private[core] def unary(operator: String, value: ElaborationIntegerExpression): ElaborationIntegerExpression = {
    val proof = source(value)
    val verilog = operator match {
      case "log2Up" => s"morphhdl_ceil_log2(${value.verilog})"
      case "addressWidth" => s"morphhdl_address_width(${value.verilog})"
      case "pow2" => s"(1 << (${value.verilog}))"
    }
    publishInteger(verilog, proof.copy(form = atom(Operation(operator, Vector(proof.form)))), value.sourceLocation)
  }
  private[core] def isPow2(value: ElaborationIntegerExpression): ElabBool = {
    val proof = source(value)
    publishBoolean(s"((${value.verilog} > 0) && ((${value.verilog} & (${value.verilog} - 1)) == 0))",
      proof.copy(form = atom(Operation("isPow2", Vector(proof.form)))), value.sourceLocation)
  }
  private[core] def extremum(operator: String, left: ElaborationIntegerExpression,
                             right: ElaborationIntegerExpression): ElaborationIntegerExpression = {
    val l = source(left); val r = source(right)
    val location = left.sourceLocation.orElse(right.sourceLocation)
    val axes = merge(Vector(l, r), location)
    // Even a dominated arm may carry a branch restriction needed by the
    // dominance proof. Keep all original axes and the authored selection.
    val comparison = if (operator == "max") ">" else "<"
    publishInteger(s"((${left.verilog} $comparison ${right.verilog}) ? ${left.verilog} : ${right.verilog})",
      TrustedExpressionEvidence(operation(operator, l.form, r.form), axes), location)
  }
  private[core] def choose(condition: ElaborationBooleanExpression, yes: ElaborationIntegerExpression,
                           no: ElaborationIntegerExpression): ElaborationIntegerExpression = {
    val c = source(condition); val y = source(yes); val n = source(no)
    val location = condition.sourceLocation.orElse(yes.sourceLocation).orElse(no.sourceLocation)
    publishInteger(s"(${condition.verilog} ? ${yes.verilog} : ${no.verilog})",
      TrustedExpressionEvidence(atom(Operation("choose", Vector(c.form, y.form, n.form))), merge(Vector(c, y, n), location)), location)
  }

  private[core] def projectedTruth(value: ElaborationBooleanExpression): ElabBool.Truth = {
    val classified = publicationTruth(value)
    if (classified != ElabBool.Unknown) classified
    else {
      val proof = source(value)
      truth(bounds(proof.form, proof.axes, value.sourceLocation))
    }
  }
  private[core] def project(value: ElaborationIntegerExpression, role: String): ElaborationIntegerExpression =
    certificate(value) match {
      case None => ElabInt.projectExpression(value, role)
      case Some(original) =>
        val current = source(value)
        if (current.axes == original.axes) value else publishInteger(value.verilog, current, value.sourceLocation)
    }
  private[core] def project(value: ElaborationBooleanExpression, role: String): ElaborationBooleanExpression =
    certificate(value) match {
      case None => ElabBool.projectExpression(value, role)
      case Some(original) =>
        val current = source(value)
        if (current.axes == original.axes) value else publishBoolean(value.verilog, current, value.sourceLocation).expression
    }
  private[core] def hasCompleteDomain(value: ElaborationIntegerExpression): Boolean =
    certificate(value).exists(_.axes.forall(axis => axis.compact || axis.values.toSet == axis.domain.get.universe))
  private[core] def equivalent(left: ElaborationIntegerExpression, right: ElaborationIntegerExpression): Boolean = {
    val l = source(left); val r = source(right)
    if (!sameAxes(l.axes, r.axes)) false
    else {
      val limits = bounds(l.form - r.form, l.axes, left.sourceLocation.orElse(right.sourceLocation))
      limits.minimum == 0 && limits.maximum == 0
    }
  }
  /** Fixed typed relations can use compositional proofs; an arbitrary Scala
    * callback must instead be evaluated exhaustively within the fallback cap.
    */
  private[core] def provesPositiveComparison(left: ElaborationIntegerExpression,
      right: ElaborationIntegerExpression, operator: String): Boolean = {
    require(Set("==", "<", "<=", ">", ">=")(operator), "unsupported typed comparison")
    val l = source(left); val r = source(right)
    val location = left.sourceLocation.orElse(right.sourceLocation)
    val axes = merge(Vector(l, r), location)
    bounds(l.form, axes, location).minimum > 0 &&
      bounds(r.form, axes, location).minimum > 0 &&
      bounds(operation(operator, l.form, r.form), axes, location).minimum == 1
  }
  private[core] def provesRelation(left: ElaborationIntegerExpression,
      right: ElaborationIntegerExpression)(relation: (BigInt, BigInt) => Boolean): Boolean = {
    val l = source(left); val r = source(right)
    val location = left.sourceLocation.orElse(right.sourceLocation)
    val axes = merge(Vector(l, r), location)
    var result = true
    foreachTuple(relevant(l.form.roots ++ r.form.roots, axes), location) { values =>
      if (!relation(l.form.evaluate(values), r.form.evaluate(values))) result = false
    }
    result
  }
  private[core] def conditionedExtrema(value: ElaborationIntegerExpression,
      condition: ElaborationBooleanExpression): Option[(BigInt, BigInt)] = {
    val v = source(value); val c = source(condition)
    val location = value.sourceLocation.orElse(condition.sourceLocation)
    val axes = merge(Vector(v, c), location)
    val guard = bounds(c.form, axes, location)
    def pair(limits: Extrema): Option[(BigInt, BigInt)] = Some(limits.minimum -> limits.maximum)
    if (guard.maximum == 0) None
    else if (guard.minimum == 1 || (c.form.roots intersect v.form.roots).isEmpty)
      pair(bounds(v.form, axes, location))
    else if (c.form.roots.size == 1) {
      val root = c.form.roots.head
      val selected = axes.map(axis => if (axis.root ne root) axis else
        axis.copy(values = axis.enumerationValues.filter(n => c.form.evaluate(Map(root -> n)) != 0)))
      pair(bounds(v.form, selected, location))
    } else {
      var low: Option[BigInt] = None
      var high: Option[BigInt] = None
      foreachTuple(relevant(v.form.roots ++ c.form.roots, axes), location) { values =>
        if (c.form.evaluate(values) != 0) {
          val result = v.form.evaluate(values)
          low = Some(low.fold(result)(_.min(result)))
          high = Some(high.fold(result)(_.max(result)))
        }
      }
      low.map(_ -> high.get)
    }
  }

  private def sameAxes(left: Vector[Axis], right: Vector[Axis]): Boolean =
    left.size == right.size && left.forall(l => right.exists(r =>
      (l.root eq r.root) && (l.schema eq r.schema) && l.sameScope(r)))
  private[core] def evaluate(value: ElaborationIntegerExpression, bindings: Vector[(Root, BigInt)]): Option[BigInt] = {
    val proof = source(value)
    evaluate(proof, bindings)
  }
  private def evaluate(proof: TrustedExpressionEvidence, bindings: Vector[(Root, BigInt)]): Option[BigInt] = {
    if (bindings.map(_._1).distinct.size != bindings.size) return None
    if (proof.axes.exists(axis => !bindings.find(_._1 eq axis.root).exists(entry => axis.containsValue(entry._2)))) None
    else Some(proof.form.evaluate(bindings.toMap))
  }

  /** A post-capture proof bound to the exact native owner. No construction
    * branch is reopened and no default tuple is substituted for that owner.
    */
  private[core] final class OwnerProof private[ElaborationProductDomain] (private val proof: TrustedExpressionEvidence,
                                                                         val sourceLocation: Option[String]) {
    private lazy val limits = checkedExtrema(proof, sourceLocation)
    private[ElaborationProductDomain] val publicationBounds = checkedEnclosure(proof, sourceLocation)
    val roots: Vector[Root] = proof.axes.map(_.root)
    val schemas: Vector[ElaborationIntegerParameter] = proof.axes.map(_.schema)
    def rootValues: Vector[Vector[BigInt]] = proof.axes.map(_.enumerationValues)
    def publicationRange: (BigInt, BigInt) = publicationBounds.minimum -> publicationBounds.maximum
    def minimum: BigInt = limits.minimum
    def maximum: BigInt = limits.maximum
    val default: BigInt = proof.form.evaluate(representative(proof.axes))
    def evaluate(bindings: Vector[(Root, BigInt)]): Option[BigInt] = ElaborationProductDomain.evaluate(proof, bindings)
    def sameDomain(that: OwnerProof): Boolean = sameAxes(proof.axes, that.proof.axes)
    def equivalent(that: OwnerProof): Boolean = sameDomain(that) && {
      val difference = bounds(proof.form - that.proof.form, proof.axes, sourceLocation)
      difference.minimum == 0 && difference.maximum == 0
    }
    def nonNegativeDifference(that: OwnerProof): Boolean = {
      val axes = merge(Vector(proof, that.proof), sourceLocation)
      bounds(proof.form - that.proof.form, axes, sourceLocation).minimum >= 0
    }
    def combine(operator: String, that: OwnerProof): OwnerProof = {
      val axes = merge(Vector(proof, that.proof), sourceLocation.orElse(that.sourceLocation))
      new OwnerProof(TrustedExpressionEvidence(operation(operator, proof.form, that.proof.form), axes), sourceLocation)
    }
  }
  private[core] def literalOwner(value: BigInt): OwnerProof =
    new OwnerProof(TrustedExpressionEvidence(literal(value), Vector.empty), None)

  // Retain the existing JVM/API entrypoint; old finite consumers do not gain
  // compact authority merely because their callback accepts a Set.
  private[core] def owner(value: ElaborationIntegerExpression, role: String, location: Option[String])(
      ownerValues: (Root, Set[BigInt]) => Set[BigInt]): Option[OwnerProof] =
    ownerWithCompact(value, role, location)(ownerValues, (_, _) =>
      fail("SPINAL-ELAB-DOMAIN-COMPACT-OWNER-UNSUPPORTED",
        s"$role has no compact native-owner validator", location))

  private[core] def ownerWithCompact(value: ElaborationIntegerExpression, role: String, location: Option[String])(
      ownerValues: (Root, Set[BigInt]) => Set[BigInt],
      compactOwner: (Root, ElaborationIntegerParameter) => Unit): Option[OwnerProof] = {
    val retainedProof = certificate(value)
    if (retainedProof.isEmpty) {
      // Authenticate raw single-root metadata through the very same carrier
      // validator as construction, but against the captured native owner.
      val exact = ElabInt.authoritativeIntegerOwnerDomain(value, role, Missing)(ownerValues)
      return Some(exact match {
        case None => literalOwner(value.default)
        case Some((domain, admitted)) =>
          new OwnerProof(TrustedExpressionEvidence(atom(Leaf(domain.root, domain.evaluations.toMap)),
            Vector(Axis(domain, admitted.toVector.sorted))), location)
      })
    }
    retainedProof.map { original =>
    ElabInt.validateExpression(value, role)
    validateInventory(value.parameters, value.completedParameterRoots, original, role, location)
    val axes = original.axes.map { axis =>
      if (axis.compact) {
        compactOwner(axis.root, axis.schema)
        axis
      } else {
        val requested = ownerValues(axis.root, axis.domain.get.universe)
        if (requested.isEmpty || !requested.subsetOf(axis.values.toSet))
          fail("SPINAL-ELAB-DOMAIN-PROJECTION-OWNER-SCOPE-MISMATCH",
            s"$role exceeds its authorized owner scope for '${axis.root.name}'", location)
        axis.copy(values = requested.toVector.sorted)
      }
    }
    val owned = new OwnerProof(original.copy(axes = axes), location)
    if (owned.default != value.default)
      fail("SPINAL-ELAB-DOMAIN-PROJECTION-OWNER-REPRESENTATIVE-MISMATCH",
        s"$role witness ${value.default} does not match owner representative ${owned.default}", location)
    if (owned.publicationBounds.minimum < value.minimum || owned.publicationBounds.maximum > value.maximum)
      fail("SPINAL-ELAB-DOMAIN-PROJECTION-BOUNDS-MISMATCH", s"$role escapes its authenticated publication enclosure", location)
    owned
  }
  }
}

package spinal.core

/** Consumer-specific publication authority; never grants a finite structural domain. */
private[spinal] object ElaborationPublicationValue {
  def projected(value: ElabInt, role: String, failureCode: String,
                requireProjectedExactExtrema: Boolean): ElaborationIntegerExpression = {
    if (ElaborationProductDomain.isRetained(value.expression)) {
      // Authenticate before projection, so a copied public summary cannot be laundered.
      ElaborationProductDomain.requireInteger(value.expression, role)
      val expression = value.projectedExpression(role)
      ElaborationProductDomain.requireInteger(expression, role)
      expression
    } else value.authoritativeProjectedExpression(role, failureCode, requireProjectedExactExtrema)
  }
}

if (ElaborationProductDomain.isRetained(expression))
  fail("SPINAL-ELAB-DOMAIN-PRODUCT-CORRELATION-UNSUPPORTED", Role,
    "requires the compositional proof path rather than a finite width table", expression.sourceLocation)

if (ElaborationProductDomain.isRetained(expression))
  fail("SPINAL-ELAB-DOMAIN-PRODUCT-CORRELATION-UNSUPPORTED", Role,
    "requires the compositional predicate path rather than a finite width table", expression.sourceLocation)

if (ElaborationProductDomain.isRetained(left) || ElaborationProductDomain.isRetained(right))
  ElaborationProductDomain.integer("+", left, right)
else if (equivalent(left, right)) binary(left, right, (l, _) => s"(2 * $l)", _ + _)

if (ElaborationProductDomain.isRetained(left) || ElaborationProductDomain.isRetained(right))
  ElaborationProductDomain.integer("+", left, right)
else binary(left, right, (l, r) => s"($l + $r)", _ + _)

if (ElaborationProductDomain.isRetained(left) || ElaborationProductDomain.isRetained(right))
  ElaborationProductDomain.integer("-", left, right)
else binary(left, right, (l, r) => s"($l - $r)", _ - _)

if (ElaborationProductDomain.isRetained(left) || ElaborationProductDomain.isRetained(right))
  ElaborationProductDomain.integer("*", left, right)
else binary(left, right, (l, r) => s"($l * $r)", _ * _)

/** Native width relations with a known typed operation can be proved
  * compositionally without materializing independent parameter products.
  */
private[core] def provesPositiveComparison(left: ElaborationIntegerExpression,
    right: ElaborationIntegerExpression, operator: String): Boolean = {
  if (ElaborationProductDomain.isRetained(left) || ElaborationProductDomain.isRetained(right))
    return ElaborationProductDomain.provesPositiveComparison(left, right, operator)
  provesRelation(left, right) { (a, b) =>
    a > 0 && b > 0 && (operator match {
      case "==" => a == b
      case "<=" => a <= b
      case "<" => a < b
      case ">=" => a >= b
      case ">" => a > b
      case _ => throw new IllegalArgumentException("unsupported typed comparison")
    })
  }
}

private[core] def claimCompactDeclaration(
    expression: ElaborationIntegerExpression, source: AnyRef
): Boolean = synchronized {
  if (consumed || !(kind eq ExternalCompilerPermit.AnalyzedCompactDeclaration) ||
      !(integerExpression eq expression) || !(sourceIdentity eq source)) false
  else { consumed = true; true }
}

private[core] case object AnalyzedCompactDeclaration extends Kind

private[core] def analyzedCompactDeclaration(source: AnyRef,
    expression: ElaborationIntegerExpression): ExternalCompilerPermit = {
  require(source != null && expression != null, "compact analyzed source must not be null")
  new ExternalCompilerPermit(AnalyzedCompactDeclaration, source, expression, source)
}

private[core] def requireAnalyzedCompactDeclaration(permit: ExternalCompilerPermit,
    expression: ElaborationIntegerExpression, source: AnyRef): Unit = {
  if (permit == null || source == null || expression == null ||
      !permit.claimCompactDeclaration(expression, source))
    ParameterizedVerilogException.fail("SPINAL-ELAB-INT-COMPACT-AUTHORIZATION-MISMATCH",
      "compact declaration received a missing, consumed, copied, stale or foreign frontend permit",
      Option(expression).flatMap(_.sourceLocation))
}

package spinal.core

import java.lang.ref.{ReferenceQueue, WeakReference}
import scala.collection.mutable

/** Native, simulation-only parameter legality. This registry is not proof that
  * an obligation holds, nor may structural consumers use it to narrow a domain.
  * Only authenticated typed expressions can enter; records belong to the exact
  * live Component identity. No copyable public annotation grants this authority.
  */
object NativeSymbolicLegality {
  private object Enabled
  /** Backend mode setup; this flag alone grants no expression or proof authority. */
  def configure(config: SpinalConfig, enabled: Boolean): SpinalConfig = {
    require(config != null, "SpinalConfig must not be null")
    val flags = config.flags.clone()
    if (enabled) flags += Enabled else flags -= Enabled
    config.copy(flags = flags)
  }
  private val Missing = "SPINAL-ELAB-DOMAIN-PRODUCT-AUTHORITY-MISSING"
  private final case class Obligation(condition: ElaborationBooleanExpression,
      encoded: ElaborationIntegerExpression, message: String, location: Option[String])
  private final class Identity(value: Component, queue: ReferenceQueue[Component])
      extends WeakReference[Component](value, queue) {
    private val hash = System.identityHashCode(value)
    override def hashCode(): Int = hash
    override def equals(other: Any): Boolean = other match {
      case that: Identity => (this eq that) || ((get ne null) && (get eq that.get))
      case _ => false
    }
  }
  private val queue = new ReferenceQueue[Component]()
  private val storage = mutable.HashMap.empty[Identity, Vector[Obligation]]
  private def reap(): Unit = {
    var reference = queue.poll()
    while (reference != null) {
      storage.remove(reference.asInstanceOf[Identity]); reference = queue.poll()
    }
  }
  private def records(component: Component): Vector[Obligation] = synchronized {
    reap()
    if (component == null) Vector.empty else storage.getOrElse(new Identity(component, null), Vector.empty)
  }
  private def enabled: Boolean =
    try Component.current != null && GlobalData.get.config.flags.contains(Enabled)
    catch { case _: NullPointerException => false }

  /** Publication classification is deliberately not the exact/structural query.
    * Unknown means neither universal result was proved, not default == true.
    */
  private[spinal] def classification(condition: ElabBool): ElabBool.Truth = {
    if (condition eq null) throw new IllegalArgumentException("require condition must not be null")
    if (ElaborationProductDomain.isRetained(condition.expression))
      ElaborationProductDomain.publicationTruth(condition.expression)
    else ElabBool.projectedTruth(condition)
  }

  private def validate(record: Obligation): Unit = {
    // Top-level obligations have no captured branch restrictions. The exact
    // owner object is the private registry key; the AST must retain its own
    // native authority as well. Validating does not ask for universal truth.
    // The private obligation registry binds a full-domain predicate to the
    // exact Component. requireSymbolic rejects all structural restrictions.
    ElaborationProductDomain.ownerWithCompact(record.encoded, "symbolic legality publication", record.location)(
      (_, universe) => universe,
      (_, _) => ()
    ).getOrElse(ParameterizedVerilogException.fail(Missing, "legality expression lost native authority", record.location))
    ()
  }

  private[spinal] def requireSymbolic(condition: ElabBool, message: => Any, location: Option[String]): Unit = {
    classification(condition) match {
      case ElabBool.AlwaysTrue => ()
      case ElabBool.AlwaysFalse =>
        ParameterizedVerilogException.fail("SPINAL-ELAB-REQUIRE-ALWAYS-FALSE", String.valueOf(message), location)
      case ElabBool.Unknown =>
        if (!enabled)
          ParameterizedVerilogException.fail("SPINAL-ELAB-REQUIRE-PUBLICATION-CONTEXT-MISSING",
            "a deferred requirement needs a native parameterized Component", location)
        // A requirement scoped under structural capture cannot be made global.
        // Keep this boundary fail-closed until obligations have structural-owner
        // activation predicates and participate in capture rollback.
        if (ElaborationDomainContext.hasActiveRestrictions)
          ParameterizedVerilogException.fail("SPINAL-ELAB-REQUIRE-STRUCTURAL-SCOPE-UNSUPPORTED",
            "mixed symbolic legality under a structural branch needs an owner-scoped obligation", location)
        val projected = condition.projectedExpression("symbolic legality")
        val encoded = condition.toElabInt.projectedExpression("symbolic legality")
        val record = Obligation(projected, encoded, String.valueOf(message), location)
        validate(record)
        synchronized {
          reap()
          val component = Component.current
          val key = new Identity(component, queue)
          storage.update(key, storage.getOrElse(key, Vector.empty) :+ record)
        }
    }
  }

  private[core] def packedWidth(raw: ElaborationIntegerExpression, role: String): ElaborationIntegerExpression = {
    if (raw.minimum > 0) return raw
    if (raw.default <= 0 || raw.parameters.isEmpty || !enabled || !ElaborationProductDomain.isRetained(raw))
      return raw // Existing concrete/default/domain validators give their precise diagnostic.
    requireSymbolic(ElabInt.fromExpression(raw) > 0,
      s"$role must be greater than zero: ${raw.verilog}", raw.sourceLocation)
    ElaborationProductDomain.safePackedWidth(raw)
  }

  private[spinal] def parametersOf(component: Component): Vector[ElaborationIntegerParameter] = {
    val values = records(component)
    values.foreach(validate)
    values.flatMap(_.encoded.parameters).distinct
  }
  private[spinal] def rootsOf(component: Component): Vector[ElaborationIntegerParameterRoot] = {
    val values = records(component)
    values.foreach(validate)
    values.flatMap(_.encoded.completedParameterRoots).distinct
  }
  private[spinal] def hasRequirements(component: Component): Boolean = records(component).nonEmpty

  /** Called by ComponentEmitterVerilog, not a generated-text post-processor. */
  private[core] def render(component: Component, allocate: String => String): String = {
    val values = records(component)
    if (values.isEmpty) return ""
    values.foreach(validate)
    def quote(text: String): String = text.flatMap {
      case '\\' => "\\\\"
      case '"' => "\\\""
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case c if c < ' ' => " "
      case c => c.toString
    }
    val guards = values.zipWithIndex.map { case (value, index) =>
      val label = allocate(s"g_morphhdl_parameter_legality_$index")
      s"""    if (!(${value.condition.verilog})) begin : $label
         |      initial $$fatal(1, "%s", "${quote("MorphHDL parameter legality failed: " + value.message)}");
         |    end
         |""".stripMargin
    }.mkString
    // A failed require is fatal, not a recoverable simulation report. Use one
    // task carrying the original message, with a fixed format so user '%' text
    // is literal. The finish_number is 1; the simulator determines its nonzero
    // process status. This diagnostic is never synthesized hardware.
    "\n`ifndef SYNTHESIS\n  generate\n" + guards + "  endgenerate\n`endif\n"
  }
}

package spinal.core

/** Scoped observation of the existing native clone and Vec zero algorithms.
  * A backend must authenticate each exact receiver; presence of a scope alone
  * never permits symbolic zero construction. Ordinary callers keep the guard.
  */
private[spinal] object NativeVecZeroConstruction {
  trait Backend {
    def cloned(source: Data, result: Data): Unit
    def zero[T <: Data](receiver: Vec[T], native: () => Vec[T]): Vec[T]
  }

  private val backend = new ScopeProperty[Backend] {
    override def default: Backend = null
  }

  def withBackend[A](value: Backend)(body: => A): A = {
    require(value != null, "SPINAL-NATIVE-VEC-ZERO-BACKEND-NULL")
    val previous = backend.set(value)
    try body finally previous.restore()
  }

  private[core] def cloned(source: Data, result: Data): Unit = {
    val selected = backend.get
    if (selected != null) selected.cloned(source, result)
  }

  private[core] def construct[T <: Data](receiver: Vec[T])(native: => Vec[T]): Vec[T] = {
    val selected = backend.get
    if (ParameterizedVec.shapeOf(receiver).isEmpty) native
    else if (selected == null) {
      ParameterizedVec.rejectUnsupported(receiver, "Vec zero construction")
      native
    } else selected.zero(receiver, () => native)
  }
}

/** An optional late optimization cannot reopen an elaboration branch after
  * its captured domain has ended. Missing scoped evidence retains the
  * original graph; malformed metadata and unrelated compiler errors still
  * propagate. Construction-time callers continue to use widthOf directly.
  */
def availableEvidence[A](proof: => A): Option[A] = {
  try Some(proof)
  catch {
    case failure: ParameterizedVerilogException
        if failure.code == "SPINAL-ELAB-DOMAIN-PROJECTION-SCOPE-EXPANSION" ||
          failure.code == "SPINAL-PARAMETERIZED-VERILOG-WIDTH-EXACT-DOMAIN-REQUIRED" => None
  }
}

def optionalWidthOf(expression: Expression): Option[ElaborationIntegerExpression] =
  availableEvidence(widthOf(expression)).flatten

case value: BitVectorRangedAccessFixed =>
  for (geometry <- rangeOf(value); width <- widthOf(value.source))
    yield geometry.resultWidth(width)

private[core] def retainCloneShape[T <: Data](source: T, result: T): T = {
  val copied = ParameterizedWidth.copyCloneMetadata(source, result)
  NativeVecZeroConstruction.cloned(source, copied)
  copied
}

private def offset(width: ElaborationIntegerExpression, amount: Int): ElaborationIntegerExpression =
  if (amount == 0) width
  else if (amount < 0) ElaborationWidthAuthority.subtract(width, ElabInt.literal(-amount).expression)
  else ElaborationWidthAuthority.add(width, ElabInt.literal(amount).expression)

/** Bounds explicitly recorded at a native source-relative construction site.
  * The flags are never inferred from equality with the default width.
  */
final class RangeGeometry private[NativeWidthProvenance] (
    val highRelative: Boolean, val highOffset: Int,
    val lowRelative: Boolean, val lowOffset: Int
) {
  val key: (Boolean, Int, Boolean, Int) = (highRelative, highOffset, lowRelative, lowOffset)
  def high(width: ElaborationIntegerExpression): ElaborationIntegerExpression =
    if (highRelative) offset(width, highOffset) else ElabInt.literal(highOffset).expression
  def low(width: ElaborationIntegerExpression): ElaborationIntegerExpression =
    if (lowRelative) offset(width, lowOffset) else ElabInt.literal(lowOffset).expression
  def resultWidth(width: ElaborationIntegerExpression): ElaborationIntegerExpression =
    offset(ElaborationWidthAuthority.subtract(high(width), low(width)), 1)
  def validFor(width: ElaborationIntegerExpression): Boolean =
    low(width).minimum >= 0 && resultWidth(width).minimum >= 1 &&
      ElaborationWidthAuthority.subtract(width, high(width)).minimum >= 1
}
private final case class RangeRecord(
    access: WeakReference[BitVectorRangedAccessFixed],
    source: WeakReference[Expression with WidthProvider],
    hi: Int, lo: Int, sourceWidth: Int,
    authoritativeWidth: ElaborationIntegerExpression, geometry: RangeGeometry)
private val retainedRanges = ArrayBuffer.empty[RangeRecord]

/** A changed access/source/index no longer carries the original certificate.
  * Freshness compares the retained symbolic identity, not equivalence after
  * projecting to the currently active branch (which may be a singleton).
  */
def rangeOf(access: BitVectorRangedAccessFixed): Option[RangeGeometry] = synchronized {
  retainedRanges --= retainedRanges.filter(_.access.get == null)
  retainedRanges.find(record => (record.access.get eq access) &&
    (record.source.get eq access.source) && record.source.get != null &&
    record.hi == access.hi && record.lo == access.lo &&
    record.source.get.getWidth == record.sourceWidth &&
    widthOf(access.source).exists(current =>
      ElabInt.equivalentExpression(record.authoritativeWidth, current))).map(_.geometry)
}

private[core] def retainRange(access: BitVectorRangedAccessFixed, geometry: RangeGeometry): Unit = synchronized {
  val width = widthOf(access.source).getOrElse(
    throw new IllegalArgumentException("SPINAL-NATIVE-RANGE-WIDTH-AUTHORITY: source width is unproved"))
  require(geometry.validFor(width) && geometry.high(width).default == access.hi &&
    geometry.low(width).default == access.lo,
    "SPINAL-NATIVE-RANGE-GEOMETRY: recorded native bounds must match throughout their exact domain")
  retainedRanges.find(_.access.get eq access) match {
    case Some(record) => require(rangeOf(access).contains(record.geometry) && record.geometry.key == geometry.key,
      "SPINAL-NATIVE-RANGE-CONFLICT: exact native range already has different geometry")
    case None => retainedRanges += RangeRecord(new WeakReference(access), new WeakReference(access.source),
      access.hi, access.lo, access.source.getWidth, width, geometry)
  }
}

private[core] def retainRelativeRange[T <: BitVector](source: BitVector, result: T,
    highOffset: Int, lowRelative: Boolean, lowOffset: Int): T = {
  if (result.hasOnlyOneStatement) result.head.source match {
    case access: BitVectorRangedAccessFixed if access.source eq source =>
      widthOf(source).foreach { width =>
        val geometry = new RangeGeometry(true, highOffset, lowRelative, lowOffset)
        if (geometry.validFor(width)) {
          retainRange(access, geometry)
          ParameterizedWidth.retainNativeWidth(result, geometry.resultWidth(width))
        }
      }
    case _ =>
  }
  result
}

private final case class RelativeWidth(
    target: WeakReference[BitVector], source: WeakReference[BitVector],
    amount: Int, width: ElaborationIntegerExpression,
    authoritativeSourceWidth: ElaborationIntegerExpression, targetWidth: Int, sourceWidth: Int)
private val relativeWidths = ArrayBuffer.empty[RelativeWidth]

private[core] def retainRelativeWidth[T <: BitVector](source: BitVector, result: T, amount: Int): T = synchronized {
  widthOf(source).foreach { sourceWidth =>
    val width = offset(sourceWidth, amount)
    if (width.minimum >= 1) {
      require(width.default == result.getBitsWidth,
        "SPINAL-NATIVE-RESULT-GEOMETRY: native result must match the retained source-relative width")
      ParameterizedWidth.retainNativeWidth(result, width)
      relativeWidths --= relativeWidths.filter(_.target.get == null)
      relativeWidths.find(_.target.get eq result) match {
        case Some(record) => require((record.source.get eq source) && record.amount == amount &&
          ElabInt.equivalentExpression(record.width, width) &&
          ElabInt.equivalentExpression(record.authoritativeSourceWidth, sourceWidth),
          "SPINAL-NATIVE-RESULT-CONFLICT: exact native result already has different geometry")
        case None => relativeWidths += RelativeWidth(new WeakReference(result), new WeakReference(source),
          amount, width, sourceWidth, result.getBitsWidth, source.getBitsWidth)
      }
    }
  }
  result
}

final class FillGeometry private[NativeWidthProvenance] (
    private val relativeSource: Option[WeakReference[BitVector]],
    val amount: Int, val width: ElaborationIntegerExpression
) {
  def source: Option[BitVector] = relativeSource.flatMap(value => Option(value.get))
  def resultWidth(sourceWidth: ElaborationIntegerExpression): ElaborationIntegerExpression =
    if (relativeSource.nonEmpty) offset(sourceWidth, amount) else width
}
private final case class FillRecord(literal: WeakReference[BitVectorLiteral],
    value: BigInt, bits: Int, specified: Boolean,
    sourceWidth: Option[ElaborationIntegerExpression], geometry: FillGeometry)
private val retainedFills = ArrayBuffer.empty[FillRecord]

def fillOf(literal: BitVectorLiteral): Option[FillGeometry] = synchronized {
  retainedFills --= retainedFills.filter(_.literal.get == null)
  retainedFills.find(record => (record.literal.get eq literal) && !literal.hasPoison &&
    literal.value == record.value && literal.bitCount == record.bits &&
    literal.hasSpecifiedBitCount == record.specified &&
    (record.sourceWidth match {
      case None => record.geometry.source.isEmpty
      case Some(original) => record.geometry.source.flatMap(widthOf).exists(current =>
        ElabInt.equivalentExpression(original, current))
    })).map(_.geometry)
}
def fillWidthOf(literal: BitVectorLiteral): Option[ElaborationIntegerExpression] =
  fillOf(literal).map(_.width)

private[core] def retainFill(literal: BitVectorLiteral, width: ElaborationIntegerExpression,
    source: Option[BitVector], amount: Int): Unit = synchronized {
  require(width.minimum >= 1 && !literal.hasPoison && literal.value == (BigInt(1) << width.default.toInt) - 1 &&
    literal.getWidth == width.default,
    "SPINAL-NATIVE-FILL-GEOMETRY: only the exact native all-ones literal may retain fill geometry")
  val sourceWidth = source.flatMap(widthOf)
  // This is a fresh construction transfer in its admitted branch, unlike
  // the immutable source/width comparisons made when reusing a record.
  source.foreach(value => require(sourceWidth.exists(original =>
    ElaborationWidthAuthority.equivalent(offset(original, amount), width)),
    "SPINAL-NATIVE-FILL-SOURCE: source-relative fill must retain its exact width transfer"))
  retainedFills.find(_.literal.get eq literal) match {
    case Some(record) => require(fillOf(literal).contains(record.geometry) &&
      record.geometry.source.size == source.size &&
      record.geometry.source.zip(source).forall { case (a, b) => a eq b } && record.geometry.amount == amount &&
      ElabInt.equivalentExpression(record.geometry.width, width),
      "SPINAL-NATIVE-FILL-CONFLICT: exact native literal already has different geometry")
    case None => retainedFills += FillRecord(new WeakReference(literal), literal.value,
      literal.bitCount, literal.hasSpecifiedBitCount, sourceWidth,
      new FillGeometry(source.map(value => new WeakReference[BitVector](value)), amount, width))
  }
}

private[core] def retainAllOnes[T <: BitVector](target: BitVector, value: T): T = synchronized {
  widthOf(target).filter(_.minimum >= 1).foreach { width =>
    if (value.hasOnlyOneStatement) value.head.source match {
      case literal: BitVectorLiteral =>
        val relative = relativeWidths.find(record => (record.target.get eq target) &&
          record.source.get != null && record.source.get.getBitsWidth == record.sourceWidth &&
          target.getBitsWidth == record.targetWidth &&
          ElabInt.equivalentExpression(record.width, width) &&
          widthOf(record.source.get).exists(current =>
            ElabInt.equivalentExpression(record.authoritativeSourceWidth, current)))
        retainFill(literal, width, relative.map(_.source.get), relative.map(_.amount).getOrElse(0))
        ParameterizedWidth.retainNativeWidth(value, width)
      case _ =>
    }
  }
  value
}

package spinal.core

/** Compiler-owned packed geometry boundary retained through native lowering.
  *
  * Unlike `dontSimplifyIt`, this is not user preservation intent. An optional
  * expression optimizer may discharge it only after proving that substitution
  * retains the exact typed width and interpretation in every receiver. The
  * ordinary native simplifier must continue to retain the carrier. The marker
  * contains no native references and must never authorize dropping other tags
  * or an explicit `dontSimplifyIt` request on the same declaration.
  */
object ParameterizedExpressionCarrier {
  private object GeometryBoundary extends SpinalTag {
    override def canSymplifyHost: Boolean = false
    override def allowMultipleInstance: Boolean = false
  }

  private[spinal] def retain[T <: BaseType](value: T): T = {
    value.addTag(GeometryBoundary)
    value
  }

  /** Identity comparison keeps arbitrary user tags outside this contract. */
  def isGeometryBoundary(tag: SpinalTag): Boolean = tag eq GeometryBoundary
}

}

/** Rebuild nested shape metadata only while an unused native clone receives
  * independently certified leaf widths. The exact source depth/root/capacity
  * survive; ordinary copies and existing registry conflicts stay immutable.
  */
private[spinal] def withFreshCloneWidths[A](source: Data, target: Data)(body: => A): A = synchronized {
  def invalid(detail: String): Nothing = fail("SPINAL-ELAB-VEC-FRESH-CLONE-SHAPE", detail)
  if (source == null || target == null || (source eq target))
    invalid("width substitution requires distinct source and fresh native clone identities")
  val sourceLeaves = source.flatten.toVector
  val targetLeaves = target.flatten.toVector
  if (sourceLeaves.isEmpty || sourceLeaves.size != targetLeaves.size ||
      targetLeaves.distinct.size != targetLeaves.size)
    invalid("fresh clone must preserve a nonempty, unaliased native leaf inventory")
  def unused(leaf: BaseType): Boolean = leaf.isDirectionLess && !leaf.isReg &&
    !leaf.isAnalog && leaf.head == null
  sourceLeaves.zip(targetLeaves).foreach { case (from, to) =>
    if (sourceLeaves.exists(_ eq to) || from.getClass != to.getClass ||
        (from.component ne to.component) || !unused(to) ||
        from.getBitsWidth != to.getBitsWidth ||
        !ElabInt.equivalentExpression(
          ParameterizedWidth.expressionOf(from).getOrElse(literal(from.getBitsWidth)),
          ParameterizedWidth.expressionOf(to).getOrElse(literal(to.getBitsWidth))))
      invalid("only unused exact native clones may receive substituted leaf widths")
  }
  val vectors = ArrayBuffer.empty[(Vec[_], Option[Entry], Option[ParameterizedVecShape])]
  def collect(from: Data, to: Data): Unit = (from, to) match {
    case (a: MultiData, b: MultiData) =>
      val left = a.elements.toVector
      val right = b.elements.toVector
      if (a.getClass != b.getClass || left.map(_._1) != right.map(_._1))
        invalid("fresh clone changed recursive container kinds or field paths")
      left.zip(right).foreach { case ((_, x), (_, y)) => collect(x, y) }
      (a, b) match {
        case (original: Vec[_], cloned: Vec[_]) =>
          val before = retained.get(new ParameterizedVecIdentityRef(cloned, null))
          val expected = shapeOf(original)
          if (before.map(_.shape).size != expected.size ||
              before.zip(expected).exists { case (entry, shape) =>
                !equivalentShape(entry.shape, shape) || entry.operations.nonEmpty ||
                  entry.completedWriteInvocations.nonEmpty || entry.formalBindings.nonEmpty
              }) invalid("fresh clone must retain its original unused Vec depth, roots and capacity")
          vectors += ((cloned, before, expected))
        case (_: Vec[_], _) | (_, _: Vec[_]) => invalid("fresh clone changed a Vec container")
        case _ =>
      }
    case (_: BaseType, _: BaseType) =>
    case _ => invalid("fresh clone changed native data kinds")
  }
  collect(source, target)
  val rollbackWidths = targetLeaves.collect { case leaf: BitVector =>
    ParameterizedWidth.beginFreshCloneWidthChange(leaf)
  }
  vectors.foreach { case (vector, _, _) => retained.remove(new ParameterizedVecIdentityRef(vector, null)) }
  try {
    val result = body
    if (target.flatten.toVector.zip(targetLeaves).exists { case (a, b) => a ne b } ||
        target.flatten.size != targetLeaves.size || targetLeaves.exists(leaf => !unused(leaf)))
      invalid("fresh width substitution changed native identities or introduced drivers")
    // Descendants precede ancestors, so recapturing an enclosing Vec uses
    // the new logical element widths and the original exact nested depths.
    vectors.foreach { case (vector, _, expected) =>
      expected match {
        case Some(shape) => attach(vector.asInstanceOf[Vec[Data]], shape.depth,
          shape.witnessDepth, shape.carrierCapacity, shape.sourceLocation)
        case None => attachConcreteDepthIfSymbolicElement(vector.asInstanceOf[Vec[Data]], vector.vec.size)
      }
    }
    result
  } catch {
    case error: Throwable =>
      vectors.foreach { case (vector, before, _) =>
        val key = new ParameterizedVecIdentityRef(vector, null)
        retained.remove(key)
        before.foreach(entry => retained.update(new ParameterizedVecIdentityRef(vector, queue), entry))
      }
      rollbackWidths.foreach(_.apply())
      throw error
  }

/** Substitute certified scalar widths without changing recursive packing.
  * Every finite carrier copy of a Vec element must still describe the same
  * logical element. Depth and capacity are preserved from this layout;
  * neither the active witness nor flattened names establish geometry.
  */
def withLeafWidths(widths: Vector[ElaborationIntegerExpression]): Layout = {
  def invalid(detail: String): Nothing =
    ParameterizedVerilogException.fail("SPINAL-ELAB-VEC-LAYOUT-WIDTH-SUBSTITUTION", detail)
  if (widths == null || widths.size != leaves.size || widths.exists(_ == null))
    invalid("substitution must retain the complete recursive scalar inventory")
  widths.foreach(width => ElaborationWidthAuthority.requireAuthoritative(width,
    "recursive layout width substitution", "SPINAL-ELAB-VEC-LAYOUT-WIDTH-SUBSTITUTION"))
  var ordinal = 0
  def visit(node: Node): Node = node match {
    case Scalar(kind, _) =>
      val width = widths(ordinal)
      ordinal += 1
      if (width.minimum < 1 ||
          ((kind eq spinal.core.internals.TypeBool) && (width.minimum != 1 || width.maximum != 1)))
        invalid("substitution requires positive scalar widths and a one-bit Bool")
      Scalar(kind, width)
    case Fields(kind, values) => Fields(kind, values.map { case (name, child) => name -> visit(child) })
    case Dimension(depth, capacity, element) =>
      if (capacity < 1) invalid("a nested carrier must retain positive capacity")
      val first = visit(element)
      (1 until capacity).foreach { _ =>
        if (!equivalent(first, visit(element)))
          invalid("substitution changed width functions between copies of one nested Vec element")
      }
      Dimension(depth, capacity, first)
  }
  val result = Layout(visit(root))
  if (ordinal != widths.size) invalid("substitution lost recursive scalar coverage")
  result
}

val ret = NativeWidthProvenance.retainRelativeWidth(this, UInt(getWidth-m bit), -m)
when(NativeWidthProvenance.retainRelativeRange(this,
  this(getWidth-1 downto getWidth-m), -1, true, -m).asBits.orR) {

// The typed planner already bounds the complete expanded expression and
// proves every receiving context. Do not recreate its eliminated chain
// solely because the legacy breadth-frontier depth cutter sees it again.
// Mandatory wraps installed before this optional depth cut still win.
expressionToWrap.retain { expression =>
  requiredBeforeDepthCut.containsKey(expression) || !wrappersProvenRedundant.containsKey(expression)

edits.before:
// The depth planner visits a whole breadth frontier, including leaves.
// A carrier for an eligible sized literal cannot shorten a computation;
// avoid recreating it after the typed expression plan has accepted it.
// Keep all non-literal depth fences and all pre-existing mandatory wraps.
expressionToWrap.retain {
  case literal: Literal =>
    requiredBeforeDepthCut.containsKey(literal) || !wrappersProvenRedundant.containsKey(literal)
  case _ => true

edits.after:
private val expressionSelectFunctions = mutable.LinkedHashMap[(String, Int, Int), String]()
private lazy val expressionSelectWidthNamesReserved: Unit =
  component.dslBody.walkDeclarations {
    case value: BaseType => ParameterizedWidth.expressionOf(value).foreach { width =>
      width.parameters.foreach(parameter => component.localNamingScope.lockName(parameter.name))
    }
    case _ =>
  }

/** Verilog-2001 cannot select an arbitrary expression. A function argument
  * evaluates in the full original unsigned width; the function's fixed
  * result then supplies the exact slice before any comparison/mux context.
  * A bitwise mask is not equivalent for X/Z, and narrowing the argument before
  * a right shift would discard live input bits. No such rewrite is used here.
  */
private def expressionSelect(owner: Expression, source: Expression, hi: Int, lo: Int): Option[String] = {
  if (!wrappersProvenRedundant.containsKey(owner) || source.isInstanceOf[BaseType] ||
      VerilogEmitterExpressionInlining.directSelectBase(component, source).nonEmpty ||
      wrappedExpressionToName.contains(source)) return None
  NativeWidthProvenance.optionalWidthOf(source).filter(width => width.minimum > hi && lo >= 0 && hi >= lo).map { width =>
    // Width parameters may be published after native naming. MorphHDL also
    // reserves the complete module parameter inventory in its pre-emission
    // phase; these exact width names cover direct users of the core opt-in.
    expressionSelectWidthNamesReserved
    width.parameters.foreach(parameter => component.localNamingScope.lockName(parameter.name))
    val key = (width.verilog, hi, lo)
    val name = expressionSelectFunctions.getOrElseUpdate(key, {
      val allocated = component.localNamingScope.allocateName("_morphhdl_slice")
      val argument = component.localNamingScope.allocateName("value")
      declarations ++= s"  function [${hi-lo}:0] $allocated;\n"
      declarations ++= s"    input [${width.verilog}-1:0] $argument;\n"
      declarations ++= s"    begin\n      $allocated = $argument[$hi:$lo];\n    end\n  endfunction\n"
      allocated
    })
    s"$name(${emitExpression(source)})"
  }
}

/** Optional storage owned by the concrete emitter, not by the historical
  * VerilogBase interface. A field in that interface would add abstract JVM
  * accessors and break already-compiled implementations. The strong reference
  * lives exactly as long as its owner; no global or thread-local registry is
  * involved, even when a policy itself retains the emitter.
  */
private[spinal] trait DeclarationPolicyOwner { self: VerilogBase =>
  @volatile private var boundPolicy: DeclarationPolicy = null

  private[VerilogBase] final def currentDeclarationPolicy: DeclarationPolicy = boundPolicy

  private[VerilogBase] final def installDeclarationPolicy(policy: DeclarationPolicy): Unit = synchronized {
    require(policy != null && boundPolicy == null,
      "a Verilog declaration policy must be non-null and bound exactly once")
    boundPolicy = policy
  }
}

// Concrete default accessors keep old VerilogBase implementations stateless
// and unsigned. Only an explicitly policy-capable emitter owns a policy slot.
private def declarationPolicy: DeclarationPolicy = this match {
  case owner: DeclarationPolicyOwner => owner.currentDeclarationPolicy
  case _ => null
}

private def declarationPolicy_=(policy: DeclarationPolicy): Unit = this match {
  case owner: DeclarationPolicyOwner => owner.installDeclarationPolicy(policy)
  case _ => throw new IllegalArgumentException(
    "binding a Verilog declaration policy requires DeclarationPolicyOwner")
}

def emitExpressionWrap(e: Expression, name: String): String =
  emitExpressionWrapWithRange(e, name, None)

/** A retained late carrier has no BaseType for the parameterized declaration
  * publisher to revisit. Its actual native allocation therefore preserves
  * unsigned logical geometry directly from the typed expression graph. This
  * is independent of signed declaration mode and never changes a real
  * declaration or grants a signed interpretation.
  */
private[internals] final def emitExpressionWrap(
    e: Expression, name: String, printer: ComponentEmitterVerilog): String = {
  require(printer != null && printer.usesVerilogBase(this),
    "an expression wrapper must belong to this native emitter")
  val range = if (VerilogEmitterExpressionInlining.isEnabled(printer.spinalConfig) &&
      !e.isInstanceOf[BaseType] &&
      !printer.isRetainedVecOperationExpression(e) &&
      (e.getTypeObject == TypeUInt || e.getTypeObject == TypeBits)) {
    VerilogEmitterExpressionInlining.availableWidthEvidence(NativeWidthProvenance.widthOf(e))
      .flatten.filter(width => width.parameters.nonEmpty && width.minimum > 0 &&
        width.default == e.asInstanceOf[WidthProvider].getWidth)
      .map(width => s"[${width.verilog}-1:0]")
  } else None
  emitExpressionWrapWithRange(e, name, range)
}

private def emitExpressionWrapWithRange(
    e: Expression, name: String, unsignedRange: Option[String]): String = {

/** Width composition normally runs inside an elaboration branch. This
  * optional late proof has no authority to reopen a finished branch: retain
  * its wrapper when branch-scoped evidence is unavailable. Other metadata,
  * graph and backend failures must continue to report their original error.
  */
private[internals] def availableWidthEvidence[A](proof: => A): Option[A] = {
  NativeWidthProvenance.availableEvidence(proof)
}

/** A condition may be printed once per split process even when the native
  * expression has only one use. Keep this distinct from arbitrary expression
  * sharing: the ordinary complete sizing proof must already accept the exact
  * condition identity, and the complete subtree supplies a conservative
  * upper bound on the number of emitted process copies. This only declines
  * the condition-sharing request; other mandatory wrapping reasons survive.
  */
private[internals] def redundantSharedCondition(
    component: Component,
    config: SpinalConfig,
    expression: Expression,
    approved: IdentityHashMap[Expression, java.lang.Boolean]
): Boolean = {
  if (!isEnabled(config) || !approved.containsKey(expression) ||
      expression.getTypeObject != TypeBool) return false
  val pending = ArrayBuffer(expression)
  var nodes = 0
  while (pending.nonEmpty) {
    val next = pending.remove(pending.size - 1)
    nodes += 1
    if (next == null || nodes > 64) return false
    next match {
      case _: BaseType =>
      case _ => next.foreachDrivingExpression(child => pending += child)
    }
  }
  var nativeConditions = 0
  var leaves = 0
  component.dslBody.walkStatements {
    case when: WhenStatement if when.cond eq expression =>
      nativeConditions += 1
      when.whenTrue.walkLeafStatements(_ => leaves += 1)
      when.whenFalse.walkLeafStatements(_ => leaves += 1)
    case _ =>
  }
  nativeConditions == 1 && leaves >= 1 && leaves <= 32 &&
    leaves.toLong * nodes <= 256
}

/** A late identity-sized unsigned resize can itself be a legal select base:
  * its printer emits only the existing declaration's reference. This is not
  * expression slicing or arithmetic reassociation. Every link must retain
  * the exact native type and fixed width; annotations and symbolic resizing
  * fail closed. The real source (including its name/protection) is untouched.
  */
private[internals] def directSelectBase(
    component: Component,
    expression: Expression
): Option[BaseType] = {
  def follow(node: Expression, depth: Int): Option[BaseType] = {
    if (node == null || depth > 32) return None
    node match {
      case base: BaseType if (base.component eq component) &&
          (base.getTypeObject == TypeUInt || base.getTypeObject == TypeBits) &&
          base.getBitsWidth > 0 && !base.isAnalog && !base.isInOut &&
          ParameterizedWidth.expressionOf(base).isEmpty => Some(base)
      case resize: Resize if
          (resize.isInstanceOf[ResizeUInt] || resize.isInstanceOf[ResizeBits]) &&
          isUnannotated(resize) && resize.input != null && resize.size > 0 &&
          resize.size == resize.input.getWidth &&
          resize.getTypeObject == resize.input.getTypeObject &&
          ParameterizedWidth.resizeExpressionOf(resize).isEmpty =>
        follow(resize.input, depth + 1)
      case _ => None
    }
  }
  follow(expression, 0)
}

val publicationExpressions = ParameterizedVec.retainedOperationExpressions(component)
val publicationIdentities = new IdentityHashMap[Expression, java.lang.Boolean]()
publicationExpressions.foreach(publicationIdentities.put(_, java.lang.Boolean.TRUE))
val publicationDependencies = new IdentityHashMap[Expression, java.lang.Boolean]()
def reachesPublication(expression: Expression): Boolean = {
  if (publicationIdentities.containsKey(expression)) return true
  val known = publicationDependencies.get(expression)
  if (known != null) return known.booleanValue
  // A cycle supplies no independent scalar proof. Inferred declarations
  // may delegate their geometry to one driver, so inspect that same edge
  // before a scalar width query can flatten a publisher-owned Vec shape.
  publicationDependencies.put(expression, java.lang.Boolean.TRUE)
  val found = expression match {
    case value: BitVector if ParameterizedWidth.expressionOf(value).isEmpty &&
        !value.isFixedWidth && value.hasOnlyOneStatement => value.head match {
      case assignment: DataAssignmentStatement if (assignment.target eq value) &&
          (assignment.finalTarget eq value) => reachesPublication(assignment.source)
      case _ => false
    }
    case _: BaseType => false
    case _ =>
      var found = false
      expression.foreachDrivingExpression(child => if (reachesPublication(child)) found = true)
      found
  }
  publicationDependencies.put(expression, java.lang.Boolean.valueOf(found))
  found
}

val widths = new IdentityHashMap[Expression, Option[ElaborationIntegerExpression]]()
def logicalWidth(expression: Expression): Option[ElaborationIntegerExpression] = {
  if (reachesPublication(expression)) return None
  if (!widths.containsKey(expression)) widths.put(expression,
    availableWidthEvidence(NativeWidthProvenance.widthOf(expression)).flatten
      .filter(value => value.minimum > 0 && value.default == width(expression)))
  widths.get(expression)
}
def sameWidth(left: Option[ElaborationIntegerExpression],
              right: Option[ElaborationIntegerExpression]): Boolean = (left, right) match {
  case (Some(a), Some(b)) =>
    availableWidthEvidence(ElaborationWidthAuthority.equivalent(a, b)).contains(true)
  case _ => false
}
def fixedWidth(value: Int): Option[ElaborationIntegerExpression] =
  Some(ElabInt.literal(value).expression)
val approvals = new IdentityHashMap[Expression, java.lang.Integer]()

// This layout-only flag protects process separation. The planner
// changes neither the target nor its driver/scope, so retain the flag
// while proving its pure RHS. All other target metadata still fences
// optimization; use singleton identity, never custom tag equality.
target.getTags().forall(_ eq noBackendCombMerge) &&
logicalWidth(target).nonEmpty

def publish(nodes: scala.collection.Seq[(Expression, Int)]): Unit = nodes.foreach { case (node, id) =>
  if (published.add(id)) {
    val count = approvals.get(node)
    approvals.put(node, if (count == null) 1 else count.intValue + 1)
  }

  plan(assignment.source, logicalWidth(target))
// Whole-register assignments each establish their own sizing context.
// Prove the existing pure RHS at that exact location; initialization,
// priority, clock/reset ownership and blocking/nonblocking order stay
// untouched. This does not inline a register or move any assignment.
case target: BaseType if target.isReg && fixedTargetBoundary(target) =>
  plan(assignment.source, logicalWidth(target))
// A no-op unsigned carrier which prints an existing reference has no
// arithmetic or assignment-context obligation. This narrow fallback
// handles repeated/nested register updates without enabling arbitrary
// expression inlining across multiple assignments or priority trees.
case target: BaseType if fixedTargetBoundary(target) =>
  assignment.source.walkExpression {
    case resize: Resize if directSelectBase(component, resize).nonEmpty =>
      result.put(resize, java.lang.Boolean.TRUE)
    case _ =>
  }

// Each shared use must independently pass its receiving sizing context.
// Approving one sibling must not release a carrier used by an unsupported
// sibling. Expanded walk counts and per-root budgets bound text growth.
val subtreeSizes = new IdentityHashMap[Expression, java.lang.Integer]()
val sizing = new IdentityHashMap[Expression, java.lang.Boolean]()
def expandedSize(node: Expression): Int = {
  if (node == null || sizing.containsKey(node)) return 257
  val cached = subtreeSizes.get(node)
  if (cached != null) return cached.intValue
  sizing.put(node, java.lang.Boolean.TRUE)
  var size = 1
  node match {
    case _: BaseType =>
    case _ => node.foreachDrivingExpression { child =>
      if (size <= 256) size = math.min(257, size + expandedSize(child))
    }
  }
  sizing.remove(node)
  subtreeSizes.put(node, size)
  size
}
val approved = approvals.entrySet().iterator()
while (approved.hasNext) {
  val entry = approved.next()
  val count = occurrences.get(entry.getKey)
  if (count != null && entry.getValue.intValue == count.intValue && count.intValue <= 32 &&
      expandedSize(entry.getKey).toLong * count.intValue <= 256)
    result.put(entry.getKey, java.lang.Boolean.TRUE)
}
// Recorded Vec operations are still owned by the parameterized publisher.
// Their witness slices and carrier aliases are generalized after emission;
// replacing them by arbitrary-expression functions loses that exact journal.
publicationExpressions.foreach(result.remove)

