def run(argv, log):
    p = subprocess.run(argv, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=180)
    log.write_text(p.stdout)
    if p.returncode:
        raise RuntimeError(f"{argv[0]} failed ({p.returncode}): {log}\n{p.stdout[-5000:]}")
