def rejected(argv, log, marker):
    p = subprocess.run(argv, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=180)
    log.write_text(p.stdout)
    assert p.returncode != 0 and marker in p.stdout, f'mutation was not rejected by the intended check: {log}'

FILL = r'''module OracleBench;
  parameter integer P=3;
  localparam integer W=P+2;
  localparam [17:0] CAP=(18'd1 << P)+18'd1;
  reg bypass;
  reg [W-1:0] upper,lower;
  wire [W-1:0] writeFill,readFill;
  wire [W-1:0] oracleWrite = bypass ? {W{1'b0}} : ((upper > CAP) ? CAP : upper);
  wire [W-1:0] oracleRead = (bypass || (lower > CAP)) ? {W{1'b0}} : lower;
  RecursiveFillCleanupRepro #(.FIFO_LOG_DEPTH(P)) dut(
    .bypass(bypass),.upper(upper),.lower(lower),.writeFill(writeFill),.readFill(readFill));
  integer i,j,k,seed,checks;
  reg [W-1:0] values[0:5];
  task check;
    begin
      #1;
      if (writeFill !== oracleWrite || readFill !== oracleRead)
        $fatal(1,"occupancy P=%0d bypass=%b upper=%b lower=%b got=%b,%b expected=%b,%b",
          P,bypass,upper,lower,writeFill,readFill,oracleWrite,oracleRead);
      $display("TRACE %b %b %b %b %b",bypass,upper,lower,writeFill,readFill);
      checks=checks+1;
    end
  endtask
  task controls;
    begin bypass=0;check; bypass=1;check; bypass=1'bx;check; bypass=1'bz;check;end
  endtask
  initial begin
    seed=13579; checks=0;
    values[0]=0;values[1]=1;values[2]=CAP-1;values[3]=CAP;values[4]=CAP+1;values[5]={W{1'b1}};
    for(i=0;i<6;i=i+1) for(j=0;j<6;j=j+1) begin upper=values[i];lower=values[j];controls;end
    for(i=0;i<1000;i=i+1) begin upper=$random(seed);lower=$random(seed);controls;end
    for(i=0;i<W;i=i+1) begin
      upper=CAP;lower=CAP;upper[i]=1'bx;controls;
      upper=CAP;lower=CAP;lower[i]=1'bz;controls;
      upper=0;lower=0;upper[i]=1'bz;lower[i]=1'bx;controls;
    end
    upper={W{1'bx}};lower={W{1'bz}};controls;
    $display("PASS occupancy P=%0d checks=%0d",P,checks);$finish;
  end
endmodule
'''

NAMING = r'''module OracleBench;
  parameter integer P=3;
  localparam integer W=P+2;
  reg [W-1:0] a,b;
  wire [17:0] wide,namedWide,zzNamedWide;
  wire [W-1:0] roundTrip;
  // Modular subtraction is completed at W bits BEFORE widening.
  wire [W-1:0] modularDifference=a-b;
  wire [17:0] oracleWide={{(18-W){1'b0}},modularDifference};
  ResizeTemporaryNamingRepro #(.FIFO_LOG_DEPTH(P)) dut(
    .a(a),.b(b),.wide(wide),.namedWide(namedWide),.zzNamedWide(zzNamedWide),.roundTrip(roundTrip));
  integer i,j,seed,checks;
  reg [W-1:0] values[0:4];
  task check;
    begin
      #1;
      if(wide !== oracleWide || namedWide !== oracleWide || zzNamedWide !== oracleWide || roundTrip !== modularDifference)
        $fatal(1,"resize P=%0d a=%b b=%b got=%b,%b,%b,%b expected=%b,%b",
          P,a,b,wide,namedWide,zzNamedWide,roundTrip,oracleWide,modularDifference);
      $display("TRACE %b %b %b %b %b %b",a,b,wide,namedWide,zzNamedWide,roundTrip);
      checks=checks+1;
    end
  endtask
  initial begin
    seed=24680;checks=0;
    values[0]=0;values[1]=1;values[2]={W{1'b1}};values[3]={1'b1,{(W-1){1'b0}}};values[4]=values[3]-1;
    for(i=0;i<5;i=i+1) for(j=0;j<5;j=j+1) begin a=values[i];b=values[j];check;end
    for(i=0;i<1000;i=i+1) begin a=$random(seed);b=$random(seed);check;end
    for(i=0;i<W;i=i+1) begin
      a=0;b=1;a[i]=1'bx;check;
      a=0;b=1;b[i]=1'bz;check;
      a={W{1'b1}};b=0;a[i]=1'bz;b[i]=1'bx;check;
    end
    $display("PASS naming P=%0d checks=%0d",P,checks);$finish;
  end
endmodule
'''

NAMING_PROTECTED = NAMING.replace('wire [17:0] wide,namedWide,zzNamedWide;',
    'wire [17:0] wide,namedWide,zzNamedWide,userPrefixWide,collisionWide;').replace(
    '.roundTrip(roundTrip));', '.roundTrip(roundTrip),.userPrefixWide(userPrefixWide),.collisionWide(collisionWide));').replace(
    'if(wide !== oracleWide', 'if(userPrefixWide !== oracleWide || collisionWide !== oracleWide || wide !== oracleWide')

FILL_ORACLE = r'''module RecursiveFillCleanupRepro #(parameter integer FIFO_LOG_DEPTH=3)(
  input wire bypass,
  input wire [FIFO_LOG_DEPTH+1:0] upper,lower,
  output wire [FIFO_LOG_DEPTH+1:0] writeFill,readFill);
  wire [17:0] capacity=(18'd1 << FIFO_LOG_DEPTH)+18'd1;
  assign writeFill=bypass ? 0 : ((upper > capacity) ? capacity : upper);
  assign readFill=(bypass || (lower > capacity)) ? 0 : lower;
endmodule
'''
NAMING_ORACLE = r'''module ResizeTemporaryNamingRepro #(parameter integer FIFO_LOG_DEPTH=3)(
  input wire [FIFO_LOG_DEPTH+1:0] a,b,
  output wire [17:0] wide,namedWide,zzNamedWide,userPrefixWide,collisionWide,
  output wire [FIFO_LOG_DEPTH+1:0] roundTrip);
  wire [FIFO_LOG_DEPTH+1:0] difference=a-b;
  assign wide={{(16-FIFO_LOG_DEPTH){1'b0}},difference};
  assign namedWide=wide;
  assign zzNamedWide=wide;
  assign userPrefixWide=wide;
  assign collisionWide=wide;
  assign roundTrip=difference;
endmodule
'''

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('artifact_directory', type=Path)
    args=p.parse_args(); root=args.artifact_directory.resolve()
    proof=root/'oracle-proofs';proof.mkdir(exist_ok=True)
    matrix=[]
    for prefix,top,tb,oracle in [('fill','RecursiveFillCleanupRepro',FILL,FILL_ORACLE),('naming','ResizeTemporaryNamingRepro',NAMING_PROTECTED,NAMING_ORACLE),('hierarchy','ResizeNamingHierarchy',NAMING_PROTECTED.replace('ResizeTemporaryNamingRepro','ResizeNamingHierarchy').replace('.FIFO_LOG_DEPTH(P)', '.COUNT_BITS(P+2)'),NAMING_ORACLE.replace('ResizeTemporaryNamingRepro','ResizeNamingHierarchy').replace('FIFO_LOG_DEPTH=3','COUNT_BITS=5').replace('FIFO_LOG_DEPTH+1','COUNT_BITS-1').replace('16-FIFO_LOG_DEPTH','18-COUNT_BITS'))]:
        oracle_path=proof/(prefix+'-oracle.v');oracle_path.write_text(oracle)
        bench=proof/(prefix+'-tb.v');bench.write_text(tb)
        for depth in DEPTHS:
            parameter = 'COUNT_BITS' if prefix == 'hierarchy' else 'FIFO_LOG_DEPTH'
            parameter_value = depth + 2 if prefix == 'hierarchy' else depth
            traces=[]
            for mode in ('on','off'):
                rtl=root/(prefix+'-'+mode)/(top+'.v')
                assert rtl.is_file(),rtl
                key=f'{prefix}-{mode}-p{depth}'
                binary=proof/(key+'.vvp')
                run(['iverilog','-Wall','-g2012','-s','OracleBench','-P',f'OracleBench.P={depth}','-o',str(binary),*[str(p) for p in sorted(rtl.parent.glob('*.v'))],str(bench)],proof/(key+'-compile.log'))
                traces.append(run(['vvp',str(binary)],proof/(key+'-oracle.log')))
            assert traces[0]==traces[1],f'on/off four-state port observations differ: {prefix} P={depth}'
            script=proof/f'{prefix}-p{depth}.ys'
            def load(mode,name):
                rtl=root/(prefix+'-'+mode)/(top+'.v')
                files=' '.join('\"'+str(p)+'\"' for p in sorted(rtl.parent.glob('*.v')))
                return f'read_verilog {files}\nchparam -set {parameter} {parameter_value} {top}\nhierarchy -top {top}\nproc\nflatten\nopt\ncheck -assert\nrename {top} {name}\ndesign -stash {name}\n'
            finish='design -copy-from gold -as gold gold\ndesign -copy-from gate -as gate gate\nequiv_make gold gate equiv\nhierarchy -top equiv\nequiv_simple\nequiv_status -assert\n'
            script.write_text(load('off','gold')+load('on','gate')+finish)
            run(['yosys','-Q','-s',str(script)],proof/f'{prefix}-p{depth}-equivalence.log')
            for mode in ('on','off'):
                oracle_script=proof/f'{prefix}-{mode}-p{depth}-oracle.ys'
                oracle_script.write_text(f'read_verilog "{oracle_path}"\nchparam -set {parameter} {parameter_value} {top}\nhierarchy -top {top}\nproc\nflatten\nopt\ncheck -assert\nrename {top} gold\ndesign -stash gold\n'+load(mode,'gate')+finish)
                run(['yosys','-Q','-s',str(oracle_script)],proof/f'{prefix}-{mode}-p{depth}-oracle-formal.log')
            matrix.append({'fixture':prefix,'depth':depth,'four_state':'passed','equivalence':'passed','oracle_formal':'passed'})
            print(f'PASS {prefix} depth={depth}: independent oracle, exact four-state on/off observations, Yosys on/off and oracle equivalence')
    # Deliberately wrong independent models validate that neither simulator nor
    # formal checker can pass by merely comparing two equally wrong artifacts.
    # Only these handwritten oracle copies change; generated HDL is untouched.
    mutations=[]
    for prefix,top,tb,oracle in [
        ('fill','RecursiveFillCleanupRepro',FILL,
         FILL_ORACLE.replace('assign writeFill=bypass ?', 'assign writeFill=!bypass ?')),
        ('naming','ResizeTemporaryNamingRepro',NAMING_PROTECTED,
         NAMING_ORACLE.replace("assign wide={{(16-FIFO_LOG_DEPTH){1'b0}},difference};", 'assign wide=a-b;'))]:
        bad=proof/(prefix+'-wrong-oracle.v');bad.write_text(oracle)
        bench=proof/(prefix+'-tb.v')
        binary=proof/(prefix+'-mutation.vvp')
        run(['iverilog','-g2012','-s','OracleBench','-P','OracleBench.P=3','-o',str(binary),str(bad),str(bench)],proof/(prefix+'-mutation-compile.log'))
        rejected(['vvp',str(binary)],proof/(prefix+'-mutation-simulation.log'),'FATAL:')
        rtl=root/(prefix+'-on')/(top+'.v')
        script=proof/(prefix+'-mutation.ys')
        script.write_text(f'read_verilog "{bad}"\nchparam -set FIFO_LOG_DEPTH 3 {top}\nhierarchy -top {top}\nproc\nopt\nrename {top} gold\ndesign -stash gold\n'
            +f'read_verilog "{rtl}"\nchparam -set FIFO_LOG_DEPTH 3 {top}\nhierarchy -top {top}\nproc\nopt\nrename {top} gate\ndesign -stash gate\n'+finish)
        rejected(['yosys','-Q','-s',str(script)],proof/(prefix+'-mutation-formal.log'),'unproven $equiv')
        mutations.append({'fixture':prefix,'four_state':'rejected','formal':'rejected'})
    (root/'publication-qualification.json').write_text(json.dumps({'matrix':matrix,'mutations':mutations},indent=2)+'\n')

if __name__=='__main__': main()

#!/usr/bin/env python3
"""CDC-WIRE-01 emitted-artifact qualification with independent four-state oracles.

Run CdcWireCleanupArtifactWriter first. Every external tool is mandatory: this
gate never turns missing simulation/formal infrastructure into a passing skip.
The source fixtures are generic native HDL, and structure is checked using the
declared graph rather than interpreting a generated identifier as provenance.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import re
import shutil
import subprocess


MATRICES = {
    "CdcSliceCompareRepro": ("DATA_BITS", (1, 32, 120, 2048)),
    "CdcGrayChainRepro": ("FIFO_LOG_DEPTH", (2, 3, 4, 16)),
    "CdcWhenPredicateRepro": ("GENERATION_BITS", (2, 32, 64)),
    "CdcWireControls": ("CONTROL_BITS", (4, 8, 16)),
}
IDENTIFIER = r"[A-Za-z_][A-Za-z0-9_$]*"


def run(work: Path, command: list[str], label: str, expect_failure: bool = False) -> str:
    result = subprocess.run(command, cwd=work, text=True, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, timeout=300)
    (work / (label + ".log")).write_text(result.stdout)
    if expect_failure:
        assert result.returncode != 0, f"mutation survived: {label}\n{result.stdout}"
    else:
        assert result.returncode == 0, f"{label}: {' '.join(command)}\n{result.stdout}"
    return result.stdout


def internal_wires(source: str) -> set[str]:
    return set(re.findall(r"(?m)^\s*(?:\(\*[^\n]*?\*\)\s*)?wire\s+"
                          r"(?:signed\s+)?(?:\[[^\]]+\]\s+)?(" + IDENTIFIER + r")\s*;", source))


def interface(source: str) -> list[tuple[str, str]]:
    return re.findall(r"(?m)^\s*(input|output)\s+(?:wire|reg)\s+(?:signed\s+)?"
                      r"(?:\[[^\]]+\]\s+)?(" + IDENTIFIER + r")\s*[,)]", source)


def parameter_bindings(source: str) -> set[str]:
    """Named typed elaboration-value boundaries are not runtime wire chains."""
    parameters = set(re.findall(r"\bparameter\s+integer\s+(" + IDENTIFIER + r")\s*=", source))
    bindings = set()
    for name in internal_wires(source):
        drivers = re.findall(r"(?m)^\s*assign\s+" + re.escape(name) + r"\s*=\s*(.*?);", source)
        if len(drivers) != 1:
            continue
        expression = re.sub(r"\b[0-9]+'[sS]?[bBoOdDhH][0-9a-fA-F_]+", "0", drivers[0])
        references = set(re.findall(IDENTIFIER, expression))
        if references and references <= parameters and re.fullmatch(r"[A-Za-z0-9_$\s()+*/%<>&|^~?:-]+", expression):
            bindings.add(name)
    return bindings


def structural_check(root: Path) -> dict:
    report = {}
    for top in MATRICES:
        enabled = (root / "enabled" / (top + ".v")).read_text()
        disabled = (root / "disabled" / (top + ".v")).read_text()
        repeat = (root / "repeat" / (top + ".v")).read_text()
        assert enabled == repeat, f"nondeterministic emission: {top}"
        assert interface(enabled) == interface(disabled), f"public interface changed: {top}"
        fixed_point = json.loads((root / "enabled" / (top + ".fixed-point.json")).read_text())
        assert fixed_point["second_invocation_changes"] == 0, top
        old_wires, new_wires = internal_wires(disabled), internal_wires(enabled)
        retained_parameters = parameter_bindings(enabled)
        if top != "CdcWireControls":
            assert not (new_wires - retained_parameters), f"{top} retained runtime carriers: {sorted(new_wires - retained_parameters)}"
            assert old_wires - parameter_bindings(disabled), f"disabled negative control lost its chain: {top}"
        else:
            protected = {"protectedKeep", "protectedGuard", "protectedDebug", "protectedCdc",
                         "protectedGeometry", "when_user_l42"}
            assert protected <= new_wires, ("protection erased", protected - new_wires)
            assert "async_reg" in enabled, "CDC attribute disappeared"
            assert re.search(r"if\s*\(when_user_l42\)", enabled), "explicit user predicate identity erased"
        if top == "CdcWhenPredicateRepro":
            for register in ("writeCount", "readCount", "writeGray", "readGray"):
                assert re.search(r"\b" + register + r"\s*<=", enabled), register
            assert enabled.count("always @") == disabled.count("always @"), "process structure changed"
        report[top] = {
            "before_internal_wires": len(old_wires), "after_internal_wires": len(new_wires),
            "retained_parameter_bindings": sorted(retained_parameters),
            "before_bytes": len(disabled.encode()), "after_bytes": len(enabled.encode()),
            "before_operators": len(re.findall(r">>>|>>|<<|!=|==|&&|\|\||[+^~]", disabled)),
            "after_operators": len(re.findall(r">>>|>>|<<|!=|==|&&|\|\||[+^~]", enabled)),
            "native_fixed_point": fixed_point,
        }
    return report


def instance(top: str, parameter: str, value: int, ports: str, suffix: str) -> str:
    names = ports.split()
    return f"{top}{suffix} #(.{parameter}({value})) {suffix or 'dut'} (" + ",".join(
        f".{name}({suffix + '_' if name in OUTPUTS[top] else ''}{name})" for name in names) + ");"


OUTPUTS = {
    "CdcSliceCompareRepro": "valid stale consume".split(),
    "CdcGrayChainRepro": "decoded fill".split(),
    "CdcWhenPredicateRepro": "writeCount readCount writeGray readGray".split(),
    "CdcWireControls": "left right kept guardedValue debugged synchronized geometryGuarded arithmetic logical widenedSlice widenedSum sumEqualsWide namedPredicate state".split(),
}
PORTS = {
    "CdcSliceCompareRepro": "payload activeGeneration enabled ready valid stale consume",
    "CdcGrayChainRepro": "gray readCount decoded fill",
    "CdcWhenPredicateRepro": "bypass sourceValid sourceUp full destinationUp empty ready recordGeneration activeGeneration writeCount readCount writeGray readGray clk reset",
    "CdcWireControls": "a b signedValue wideValue wideReference shift choose advance left right kept guardedValue debugged synchronized geometryGuarded arithmetic logical widenedSlice widenedSum sumEqualsWide namedPredicate state clk reset",
}


def pair(top: str, parameter: str, value: int) -> str:
    return "\n".join(instance(top, parameter, value, PORTS[top], suffix) for suffix in ("gate", "gold"))


def compare(top: str) -> str:
    return "\n".join(f'if (gate_{name} !== gold_{name}) $fatal(1, "enabled/disabled {name}");'
                     for name in OUTPUTS[top])


def slice_bench(value: int) -> str:
    top = "CdcSliceCompareRepro"
    return f"""module CdcWireBench;
localparam integer DATA_BITS={value}, W=DATA_BITS+57, OFFSET=DATA_BITS+7;
reg [W-1:0] payload;
reg [31:0] activeGeneration;
reg enabled,ready;
wire gate_valid,gate_stale,gate_consume,gold_valid,gold_stale,gold_consume;
reg [W-1:0] shifted;
reg [31:0] generation;
reg mismatch;
integer n,j;
{pair(top, 'DATA_BITS', value)}
task check;
begin
  #1;
  shifted=payload >> OFFSET;
  generation=shifted[31:0];
  mismatch=(generation != activeGeneration);
  if (gate_valid !== (enabled && !mismatch)) $fatal(1,"truncated valid oracle");
  if (gate_stale !== (enabled && mismatch)) $fatal(1,"truncated stale oracle");
  if (gate_consume !== (enabled && (mismatch || ready))) $fatal(1,"truncated consume oracle");
  {compare(top)}
end endtask
initial begin
  enabled=1; ready=0; activeGeneration=0; payload=0;
  // The roadmap vector: DATA_BITS=32 gives exactly 89'h800000000000000000.
  payload[OFFSET+32]=1'b1;
  check;
  if (gate_valid !== 1'b1 || gate_stale !== 1'b0 || gate_consume !== 1'b0)
    $fatal(1,"discarded bit 32 incorrectly influenced comparison");
  // Discarded metadata, including unknowns, must not contaminate low 32 bits.
  payload={{W{{1'b1}}}}; payload[OFFSET +: 32]=0; check;
  payload[OFFSET+32]=1'bx; check;
  payload[OFFSET+33]=1'bz; check;
  for (n=0;n<160;n=n+1) begin
    for(j=0;j<W;j=j+1) payload[j]=$random;
    activeGeneration=$random; enabled=n[0]; ready=n[1];
    case(n%8)
      0: payload=0;
      1: payload={{W{{1'b1}}}};
      2: activeGeneration=payload[OFFSET +: 32];
      3: payload[OFFSET+n%32]=1'bx;
      4: payload[OFFSET+n%32]=1'bz;
      5: activeGeneration=32'bx;
      6: enabled=1'bx;
      7: ready=1'bz;
    endcase
    check;
  end
  $display("CDC_WIRE_ORACLE_PASS slice"); $finish;
end
endmodule
"""


def gray_bench(value: int) -> str:
    top = "CdcGrayChainRepro"
    return f"""module CdcWireBench;
localparam integer W={value}+2;
reg [W-1:0] gray,readCount;
wire [W-1:0] gate_decoded,gate_fill,gold_decoded,gold_fill;
reg [W-1:0] oracle,expectedFill;
integer n,j;
{pair(top, 'FIFO_LOG_DEPTH', value)}
task check;
begin
  #1;
  // Independent linear prefix-XOR oracle, not the library's shift/XOR tree.
  // XOR with zero intentionally converts a Z input to X, as the original
  // parameterized library's XOR stages do even at the most significant bit.
  oracle[W-1]=gray[W-1]^1'b0;
  for(j=W-2;j>=0;j=j-1) oracle[j]=oracle[j+1]^gray[j];
  expectedFill=oracle-readCount;
  if(gate_decoded !== oracle) $fatal(1,"independent prefix-XOR oracle");
  if(gate_fill !== expectedFill) $fatal(1,"modular fill oracle");
  {compare(top)}
end endtask
initial begin
  gray=0; readCount=0; check;
  gray={{W{{1'b1}}}}; check;
  for(n=0;n<W;n=n+1) begin
    gray=0; gray[n]=1'b1; readCount=0; check;
    readCount={{W{{1'b1}}}}; check;
    gray[n]=1'bx; check;
    gray[n]=1'bz; check;
  end
  gray=0; readCount=1; check;
  gray=0; readCount={{W{{1'b1}}}}; check;
  for(n=0;n<256;n=n+1) begin
    gray=$random; readCount=$random; check;
  end
  gray={{W{{1'bx}}}}; readCount=0; check;
  gray={{W{{1'bz}}}}; check;
  gray=0; readCount={{W{{1'bx}}}}; check;
  $display("CDC_WIRE_ORACLE_PASS gray"); $finish;
end
endmodule
"""


def predicate_bench(value: int) -> str:
    top = "CdcWhenPredicateRepro"
    return f"""module CdcWireBench;
localparam integer W={value};
reg bypass,sourceValid,sourceUp,full,destinationUp,empty,ready,clk,reset;
reg [W-1:0] recordGeneration,activeGeneration;
wire [7:0] gate_writeCount,gate_readCount,gate_writeGray,gate_readGray;
wire [7:0] gold_writeCount,gold_readCount,gold_writeGray,gold_readGray;
reg [7:0] oracleWrite,oracleRead,oracleWriteGray,oracleReadGray;
integer n,e;
{pair(top, 'GENERATION_BITS', value)}
task cycle;
begin
  #1;
  if(reset) begin oracleWrite=0; oracleRead=0; end
  else begin
    if(!bypass && sourceValid && sourceUp && !full) oracleWrite=oracleWrite+8'd1;
    if(!bypass && destinationUp && !empty && ((recordGeneration!=activeGeneration)||ready))
      oracleRead=oracleRead+8'd1;
  end
  oracleWriteGray=oracleWrite^(oracleWrite>>1);
  oracleReadGray=oracleRead^(oracleRead>>1);
  clk=1; #1;
  if(gate_writeCount !== oracleWrite || gate_readCount !== oracleRead ||
     gate_writeGray !== oracleWriteGray || gate_readGray !== oracleReadGray)
    $fatal(1,"sequential predicate/count/Gray oracle");
  {compare(top)}
  clk=0; #1;
end endtask
initial begin
  clk=0; reset=1; bypass=0; sourceValid=0; sourceUp=0; full=0;
  destinationUp=0; empty=1; ready=0; recordGeneration=0; activeGeneration=0;
  cycle; reset=0;
  for(e=0;e<2;e=e+1) begin
    recordGeneration=e;
    for(n=0;n<128;n=n+1) begin
      {{bypass,sourceValid,sourceUp,full,destinationUp,empty,ready}}=n;
      cycle;
    end
  end
  // Successive simultaneous updates cross the eight-bit count-wrap boundary.
  bypass=0; sourceValid=1; sourceUp=1; full=0; destinationUp=1; empty=0; ready=1;
  for(n=0;n<520;n=n+1) cycle;
  for(n=0;n<7;n=n+1) begin
    {{bypass,sourceValid,sourceUp,full,destinationUp,empty,ready}}=7'b0110101;
    case(n)
      0: bypass=1'bx; 1: sourceValid=1'bx; 2: sourceUp=1'bz;
      3: full=1'bz; 4: destinationUp=1'bx; 5: empty=1'bx; 6: ready=1'bz;
    endcase
    recordGeneration={{W{{1'bx}}}}; cycle;
    recordGeneration={{W{{1'bz}}}}; cycle;
  end
  // A dominating false control must suppress unknown inner predicates.
  bypass=1; cycle; reset=1; cycle; reset=0; cycle;
  $display("CDC_WIRE_ORACLE_PASS predicate"); $finish;
end
endmodule
"""


def controls_bench(value: int) -> str:
    top = "CdcWireControls"
    return f"""module CdcWireBench;
localparam integer W={value};
reg [W-1:0] a,b;
reg signed [11:0] signedValue;
reg [47:0] wideValue,wideShifted;
reg [W:0] wideReference;
reg [3:0] shift;
