import scala.util.control.NonFatal

import spinal.core.SpinalConfig

import morphhdl.MorphVerilogStage.{OutputWrite, SingleSourceGeneration}

private[morphhdl] final case class MorphPreparedPublicationFile(
    relativePath: String,
    content: Array[Byte],
    reportAsSource: Boolean
)

/** Safe publication of the native emitter's already-separated component files.
  *
  * Module boundaries are supplied by the native one-file-per-component emitter.
  * This object never concatenates files or parses Verilog to rediscover logical
  * component identity. It only captures the private workspace and publishes an
  * ownership-tracked file set after the parameterized rewrite phases succeed.
  */
private[morphhdl] object MorphPerComponentPublication {
  private val ManifestVersion = "MORPHDL_ONE_FILE_PER_COMPONENT_V2"
  private val ManifestSuffix = ".morphhdl-one-file-per-component.manifest"
  private val OwnerMarkerVersion = "MORPHDL_ONE_FILE_PER_COMPONENT_OWNER_V1"
  private val OwnerDirectorySuffix = ".morphhdl-one-file-per-component.owners"
  private val OwnerMarkerSuffix = ".owner"

  def capture(
      workspace: Path,
      top: String
  ): Either[MorphVerilogFailure, Vector[MorphPreparedPublicationFile]] =
    try {
      val root = workspace.toAbsolutePath.normalize()
      if (!Files.isDirectory(root) || Files.isSymbolicLink(root)) {
        throw new IllegalArgumentException(
          "MORPHDL-ONE-FILE-CAPTURE-WORKSPACE-INVALID: private generation workspace is unavailable"
        )
      }
      val stream = Files.walk(root)
      val paths = try {
        stream.iterator().asScala.toVector
      } finally stream.close()
      val files = paths
        .filter(path => path != root)
        .filter { path =>
          if (Files.isSymbolicLink(path)) {
            throw new IllegalArgumentException(
              s"MORPHDL-ONE-FILE-CAPTURE-SYMLINK-REJECTED: $path"
            )
          }
          Files.isRegularFile(path)
        }
        .flatMap { path =>
          val relative = normalizedRelative(root.relativize(path))
          if (
            relative.endsWith(".lst") ||
            relative.endsWith(ManifestSuffix) ||
            relative.contains(".morphhdl.tmp")
          ) None
          else
            Some(
              MorphPreparedPublicationFile(
                relative,
                Files.readAllBytes(path),
                reportAsSource = relative.endsWith(".v")
              )
            )
        }
      validateUniquePaths(files)
      val topFile = top + ".v"
      if (!files.exists(file => file.relativePath == topFile && file.reportAsSource)) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-CAPTURE-TOP-MISSING: expected '$topFile'"
        )
      }
      val ordered = files.sortBy { file =>
        val rank =
          if (!file.reportAsSource) 0
          else if (file.relativePath == topFile) 2
          else 1
        (rank, file.relativePath)
      }
      Right(ordered)
    } catch {
      case NonFatal(error) =>
        Left(
          MorphVerilogFailure(
            SingleSourceGeneration,
            Option(error.getMessage).filter(_.nonEmpty).getOrElse(error.getClass.getName),
            cause = Some(error)
          )
        )
    }

  def publish(
      config: SpinalConfig,
      top: String,
      files: Vector[MorphPreparedPublicationFile]
  ): Either[MorphVerilogFailure, Vector[Path]] =
    try {
      if (files.isEmpty) {
        throw new IllegalArgumentException(
          "MORPHDL-ONE-FILE-PUBLISH-EMPTY: no generated files were captured"
        )
      }
      validateUniquePaths(files)
      val directory = Paths.get(config.targetDirectory).normalize()
      Files.createDirectories(directory)
      if (!Files.isDirectory(directory) || Files.isSymbolicLink(directory)) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-DIRECTORY-INVALID: $directory"
        )
      }

      val sources = files.filter(_.reportAsSource)
      if (sources.isEmpty) {
        throw new IllegalArgumentException(
          "MORPHDL-ONE-FILE-PUBLISH-SOURCES-EMPTY: no Verilog source was captured"
        )
      }
      val listRelative = top + ".lst"
      val listContent =
        (sources.map(_.relativePath).mkString("\n") + "\n")
          .getBytes(StandardCharsets.UTF_8)
      val managed = files :+ MorphPreparedPublicationFile(
        listRelative,
        listContent,
        reportAsSource = false
      )
      validateUniquePaths(managed)

      val manifest = directory.resolve("." + top + ManifestSuffix)
      val owners = directory.resolve("." + top + OwnerDirectorySuffix)
      val previous = readManifest(manifest, owners)
      preflight(directory, managed, previous)
      ensureOwnerDirectory(owners)

      managed.foreach { file =>
        val target = resolveManaged(directory, file.relativePath)
        ensureSafeParentChain(directory, target.getParent)
        publishAtomically(target, file.content)
      }

      val currentHashes = managed.map(file => file.relativePath -> sha256(file.content)).toMap
      val currentPaths = currentHashes.keySet
      previous.toVector.sortBy(_._1).foreach { case (relative, expectedHash) =>
        if (!currentPaths(relative)) {
          val target = resolveManaged(directory, relative)
          if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
            requireRegularUnmodified(target, expectedHash, "stale managed output")
            Files.delete(target)
          }
          Files.deleteIfExists(ownerMarkerPath(owners, relative))
        }
      }

      currentHashes.toVector.sortBy(_._1).foreach { case (relative, hash) =>
        publishAtomically(
          ownerMarkerPath(owners, relative),
          renderOwnerMarker(relative, hash).getBytes(StandardCharsets.UTF_8)
        )
      }
      validateOwnerInventory(owners, currentPaths)

      val manifestContent = renderManifest(managed)
      publishAtomically(manifest, manifestContent.getBytes(StandardCharsets.UTF_8))
      Right(sources.map(file => resolveManaged(directory, file.relativePath)))
    } catch {
      case NonFatal(error) =>
        Left(
          MorphVerilogFailure(
            OutputWrite,
            Option(error.getMessage).filter(_.nonEmpty).getOrElse(error.getClass.getName),
            cause = Some(error)
          )
        )
    }

  private def preflight(
      directory: Path,
      managed: Vector[MorphPreparedPublicationFile],
      previous: Map[String, String]
  ): Unit = {
    val current = managed.map(file => file.relativePath -> sha256(file.content)).toMap
    managed.foreach { file =>
      val target = resolveManaged(directory, file.relativePath)
      if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
        if (!Files.isRegularFile(target) || Files.isSymbolicLink(target)) {
          throw new IllegalArgumentException(
            s"MORPHDL-ONE-FILE-PUBLISH-TARGET-INVALID: ${file.relativePath}"
          )
        }
        val actual = sha256(Files.readAllBytes(target))
        previous.get(file.relativePath) match {
          case Some(expected) if actual != expected =>
            throw new IllegalArgumentException(
              s"MORPHDL-ONE-FILE-PUBLISH-MANAGED-MODIFIED: ${file.relativePath}"
            )
          case Some(_) =>
          case None =>
            throw new IllegalArgumentException(
              s"MORPHDL-ONE-FILE-PUBLISH-UNOWNED-COLLISION: ${file.relativePath}"
            )
        }
      }
    }
    previous.toVector.foreach { case (relative, expected) =>
      if (!current.contains(relative)) {
        val target = resolveManaged(directory, relative)
        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
          requireRegularUnmodified(target, expected, "stale managed output")
        }
      }
    }
  }

  private def requireRegularUnmodified(
      target: Path,
      expectedHash: String,
      context: String
  ): Unit = {
    if (!Files.isRegularFile(target) || Files.isSymbolicLink(target)) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-STALE-INVALID: $context '$target'"
      )
    }
    val actual = sha256(Files.readAllBytes(target))
    if (actual != expectedHash) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-STALE-MODIFIED: $context '$target'"
      )
    }
  }

  private def readManifest(
      path: Path,
      owners: Path
  ): Map[String, String] = {
    if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
      if (Files.exists(owners, LinkOption.NOFOLLOW_LINKS)) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-OWNER-DIRECTORY-ORPHANED: $owners"
        )
      }
      Map.empty
    } else {
      if (!Files.isRegularFile(path) || Files.isSymbolicLink(path)) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-MANIFEST-INVALID: $path"
        )
      }
      val normalizedText = new String(Files.readAllBytes(path), StandardCharsets.UTF_8)
        .replace("\r\n", "\n")
        .replace('\r', '\n')
      if (!normalizedText.endsWith("\n")) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-MANIFEST-TERMINATOR: $path"
        )
      }
      val lines = normalizedText
        .split("\n", -1)
        .toVector
        .dropRight(1)
      if (lines.headOption != Some(ManifestVersion)) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-MANIFEST-VERSION: $path"
        )
      }
      val entries = lines.drop(1).filter(_.nonEmpty).map { line =>
        val fields = line.split("\\t", -1)
        if (
          fields.length != 2 ||
          fields(0).length != 64 ||
          !fields(0).forall(character => Character.digit(character, 16) >= 0)
        ) {
          throw new IllegalArgumentException(
            s"MORPHDL-ONE-FILE-PUBLISH-MANIFEST-ENTRY: $line"
          )
        }
        val relative = normalizedRelative(Paths.get(fields(1)))
        relative -> fields(0).toLowerCase(Locale.ROOT)
      }
      if (entries.isEmpty) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-MANIFEST-EMPTY: $path"
        )
      }
      if (entries.map(_._1.toLowerCase(Locale.ROOT)).distinct.size != entries.size) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-MANIFEST-DUPLICATE: $path"
        )
      }
      val previous = entries.toMap
      validateOwnerInventory(owners, previous.keySet)
      previous.toVector.foreach { case (relative, hash) =>
        val marker = ownerMarkerPath(owners, relative)
        val expected = renderOwnerMarker(relative, hash).getBytes(StandardCharsets.UTF_8)
        val actual = Files.readAllBytes(marker)
        if (!java.util.Arrays.equals(actual, expected)) {
          throw new IllegalArgumentException(
            s"MORPHDL-ONE-FILE-PUBLISH-OWNER-MARKER-TAMPERED: $relative"
          )
        }
      }
      previous
    }
  }

  private def ensureOwnerDirectory(path: Path): Unit = {
    if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
      if (!Files.isDirectory(path) || Files.isSymbolicLink(path)) {
        throw new IllegalArgumentException(
          s"MORPHDL-ONE-FILE-PUBLISH-OWNER-DIRECTORY-INVALID: $path"
        )
      }
    } else {
      Files.createDirectory(path)
    }
  }

  private def validateOwnerInventory(
      owners: Path,
      relativePaths: Set[String]
  ): Unit = {
    if (!Files.isDirectory(owners) || Files.isSymbolicLink(owners)) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-OWNER-DIRECTORY-INVALID: $owners"
      )
    }
    val stream = Files.list(owners)
    val markerNames = try {
      stream.iterator().asScala.toVector.map { marker =>
        if (!Files.isRegularFile(marker) || Files.isSymbolicLink(marker)) {
          throw new IllegalArgumentException(
            s"MORPHDL-ONE-FILE-PUBLISH-OWNER-MARKER-INVALID: $marker"
          )
        }
        marker.getFileName.toString
      }.toSet
    } finally stream.close()
    val expected = relativePaths.map(ownerMarkerName)
    if (markerNames != expected) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-OWNER-INVENTORY: expected [${expected.toVector.sorted.mkString(", ")}], " +
          s"observed [${markerNames.toVector.sorted.mkString(", ")}]"
      )
    }
  }

  private def ownerMarkerPath(owners: Path, relative: String): Path =
    owners.resolve(ownerMarkerName(relative))

  private def ownerMarkerName(relative: String): String =
    sha256(normalizedRelative(Paths.get(relative)).getBytes(StandardCharsets.UTF_8)) + OwnerMarkerSuffix

  private def renderOwnerMarker(relative: String, hash: String): String =
    OwnerMarkerVersion + "\n" + hash + "\t" + normalizedRelative(Paths.get(relative)) + "\n"

  private def renderManifest(
      files: Vector[MorphPreparedPublicationFile]
  ): String = {
    val entries = files
      .map(file => sha256(file.content) + "\t" + file.relativePath)
      .sorted
    (ManifestVersion +: entries).mkString("\n") + "\n"
  }

  private def validateUniquePaths(
      files: Vector[MorphPreparedPublicationFile]
  ): Unit = {
    files.foreach(file => normalizedRelative(Paths.get(file.relativePath)))
    val duplicate = files
      .groupBy(_.relativePath.toLowerCase(Locale.ROOT))
      .collectFirst { case (name, values) if values.size != 1 => name }
    duplicate.foreach { name =>
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-FILENAME-COLLISION: $name"
      )
    }
  }

  private def normalizedRelative(path: Path): String = {
    if (path == null || path.isAbsolute || path.getNameCount == 0) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-PATH-INVALID: $path"
      )
    }
    val normalized = path.normalize()
    if (
      normalized != path ||
      normalized.iterator().asScala.exists { element =>
        val value = element.toString
        value.isEmpty || value == "." || value == ".." ||
        value.contains('\t') || value.contains('\n') || value.contains('\r')
      }
    ) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-PATH-INVALID: $path"
      )
    }
    normalized.iterator().asScala.map(_.toString).mkString("/")
  }

  private def resolveManaged(directory: Path, relative: String): Path = {
    val normalized = normalizedRelative(Paths.get(relative))
    val root = directory.toAbsolutePath.normalize()
    val target = directory.resolve(normalized).normalize()
    val absoluteTarget = target.toAbsolutePath.normalize()
    if (!absoluteTarget.startsWith(root) || absoluteTarget == root) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-PATH-ESCAPE: $relative"
      )
    }
    validateSafeParentChain(directory, target.getParent)
    target
  }

  private def validateSafeParentChain(directory: Path, parent: Path): Unit =
    inspectSafeParentChain(directory, parent, createMissing = false)

  private def ensureSafeParentChain(directory: Path, parent: Path): Unit =
    inspectSafeParentChain(directory, parent, createMissing = true)

  private def inspectSafeParentChain(
      directory: Path,
      parent: Path,
      createMissing: Boolean
  ): Unit = {
    val root = directory.toAbsolutePath.normalize()
    val absoluteParent = parent.toAbsolutePath.normalize()
    if (!absoluteParent.startsWith(root)) {
      throw new IllegalArgumentException(
        s"MORPHDL-ONE-FILE-PUBLISH-PARENT-ESCAPE: $parent"
      )
    }
    var current = root
    val elements = root.relativize(absoluteParent).iterator().asScala.toVector
    elements.foreach { element =>
      current = current.resolve(element)
      if (!Files.exists(current, LinkOption.NOFOLLOW_LINKS) && createMissing) {
        Files.createDirectory(current)
      }
      if (Files.exists(current, LinkOption.NOFOLLOW_LINKS)) {
        if (Files.isSymbolicLink(current)) {
          throw new IllegalArgumentException(
            s"MORPHDL-ONE-FILE-PUBLISH-PARENT-SYMLINK: $current"
          )
        }
        if (!Files.isDirectory(current, LinkOption.NOFOLLOW_LINKS)) {
          throw new IllegalArgumentException(
            s"MORPHDL-ONE-FILE-PUBLISH-PARENT-INVALID: $current"
          )
        }
      }
    }
  }

  private def sha256(bytes: Array[Byte]): String =
    MessageDigest
      .getInstance("SHA-256")
      .digest(bytes)
      .map(value => f"${value & 0xff}%02x")
      .mkString

  private def publishAtomically(target: Path, content: Array[Byte]): Unit = {
    val parent = target.getParent
    val temporary = Files.createTempFile(
      parent,
      "." + target.getFileName.toString + ".",
      ".morphhdl.tmp"
    )
    var committed = false
    try {
      Files.write(
        temporary,
        content,
        StandardOpenOption.TRUNCATE_EXISTING,
        StandardOpenOption.WRITE
      )
      Files.move(
        temporary,
        target,
        StandardCopyOption.ATOMIC_MOVE,
        StandardCopyOption.REPLACE_EXISTING
      )
      committed = true
    } finally {
      if (!committed) Files.deleteIfExists(temporary)
    }
  }
}

if (config.oneFilePerComponent && !allowSingleSourceFormal) {
  errors += "oneFilePerComponent is supported only by the typed single-source MorphVerilog path"
}
if (config.oneFilePerComponent && config.netlistFileName != null) {
  errors += "netlistFileName cannot be combined with oneFilePerComponent"

private def publishSingleSource(
    config: SpinalConfig,
    top: String,
    files: Vector[MorphPreparedPublicationFile]
): Either[MorphVerilogFailure, Vector[Path]] = {
  if (config.oneFilePerComponent) {
    MorphPerComponentPublication.publish(config, top, files)
  } else {
    files match {
      case Vector(file) =>
        writeOutput(
          config,
          top,
          new String(file.content, StandardCharsets.UTF_8)
        ).map(path => Vector(path))
      case _ =>
        Left(
          MorphVerilogFailure(
            SingleSourceGeneration,
            s"consolidated parameterized generation captured ${files.size} files; expected exactly one"
          )
        )
    }
  }
}

// The recursive adapter brackets PhaseVerilog. Install it before every
// caller-owned inserter so a pre-existing strict signedness observation can
// still claim the exact phase immediately before the emitter. Consolidated
// publication must not acquire these otherwise inactive lifecycle phases.
if (config.oneFilePerComponent)
  phaseInserters.insert(0, MorphHdlRecursivePerComponentPublication.install _)

private def readSingleSourcePublication[T <: Component](
    config: SpinalConfig,
    report: SpinalReport[T],
    workspace: Path
): Either[MorphVerilogFailure, Vector[MorphPreparedPublicationFile]] = {
  if (config.oneFilePerComponent) {
    MorphPerComponentPublication.capture(workspace, report.toplevelName)
  } else {
    readSingleSourceModule(report).map { verilog =>
      val filename = Option(config.netlistFileName)
        .getOrElse(report.toplevelName + ".v")
      Vector(
        MorphPreparedPublicationFile(
          filename,
          verilog.getBytes(StandardCharsets.UTF_8),
          reportAsSource = true
        )
      )
    }
  }
}

val sourceIntent = new NativeConditionSourceIntent
phases.update(cleanup(2), new ProductionWireAssignmentPhase(sourceIntent))
// Capture after application transformation phases but before any native
// liveness sweep can infer vital bits. The complete per-generation identity
// inventory then distinguishes explicit preservation from inferred liveness.
val firstLiveness = phases.indexWhere(_.isInstanceOf[PhaseRemoveUselessStuff])
if (firstLiveness < 0 || firstLiveness >= cleanup(2))
  throw new IllegalStateException("condition source intent requires a pre-optimization liveness boundary")
phases.insert(firstLiveness, sourceIntent)
// Native helper names share a namespace with parameters published by the
// external backend. Reserve the complete module inventory after native
// declaration allocation, leaving the signedness observation immediately
// adjacent to its emitter as required by the existing phase-plan contract.
val emitterIndex = phases.indexWhere(_.isInstanceOf[PhaseVerilog])
if (emitterIndex >= 0) {
  val allocationIndex = phases.indexWhere(_.isInstanceOf[PhaseAllocateNames])
  if (allocationIndex < 0 || allocationIndex >= emitterIndex)
    throw new IllegalStateException("emitter parameter reservation requires prior native name allocation")
  phases.insert(allocationIndex + 1, new MorphHdlEmitterParameterNames)
}

private final class ProductionWireAssignmentPhase(sourceIntent: NativeConditionSourceIntent) extends Phase {
  // Legacy callers have no pre-liveness capture. A fresh, uncaptured inventory
  // fails closed for condition inlining without sharing mutable phase state.
  def this() = this(new NativeConditionSourceIntent)

  )
}
val generated =
  if (isolatedConfig.oneFilePerComponent)
    reported.filter(path => Files.isRegularFile(Paths.get(path))).distinct
  else reported
if (generated.isEmpty) {
  throw new IllegalStateException(
    "normal SpinalHDL per-component generation published no internal Verilog source"

// The native-resize publisher already owns an explicitly preserved
// live typed boundary. In that case no normalization-recovery journal
// is needed: retaining the adjacent same-width forwarding assignment
// would incorrectly make it part of the resize's publication identity.
// Establish ownership while BOTH original edges still exist; never
// drop, forgive or reclassify an invalid/inactive captured record later.
val nativeOwner = !record.witnessInactive && record.typedTarget.nonEmpty &&
  validCurrentRecord(component, record) &&
  (record.outer.source eq record.resizeSource) &&
  (record.outer.parentScope eq component.dslBody) &&
  (record.sourceDriver.parentScope eq component.dslBody) &&
  typedTargetMatches(record, record.target) &&
  ExternalParameterizedNativeResize.provesAssignment(component, record.sourceDriver) &&
  ExternalParameterizedNativeResize.targetWidthOf(component, record.resizeSource).exists { width =>
    record.typedTarget.exists(expected =>
      NativePublicationWidth.equivalentAtOwner(width, expected, component, record.resizeSource))
  }
if (!nativeOwner) {
  storage.byStatement.put(record.outer, record)
  storage.byStatement.put(record.sourceDriver, record)
  storage.byResizeSource.put(record.resizeSource, record)
}

/** Captured resize records retain native identities until publication consumes
  * them. Cleanup must not rewrite an input out from under the exact-lineage
  * validator, including when that validator still owes a rejection. This is
  * an ownership query, so it deliberately does not require a validRecord.
  */
private[internals] def retainsWireIdentity(component: Component, alias: BaseType): Boolean = {
  if (component == null || alias == null) return false
  def expressionUses(expression: Expression): Boolean = {
    var found = expression eq alias
    if (expression != null) expression.walkExpression {
      case value: BaseType if value eq alias => found = true
      case _ =>
    }
    found
  }
  def assignmentUses(assignment: DataAssignmentStatement): Boolean =
    assignment != null &&
      (expressionUses(assignment.target) || expressionUses(assignment.source))

  storageOf(component).exists { storage =>
    val records = storage.byResizeSource.values().iterator()
    var retained = false
    while (records.hasNext && !retained) {
      val record = records.next()
      // Capture also inventories ordinary concrete `.resized` edges. Those
      // have no symbolic publication obligation and must not fence off the
      // existing alias-to-register cleanup. Require positive parameter-free
      // evidence for every boundary, including both the original and current
      // driver; missing/scoped evidence is not a concrete-width fallback.
      // Typed and inactive records retain identity even when corrupted, so
      // their owning validator still emits its precise rejection.
      val concreteOnly = record.typedTarget.isEmpty && !record.witnessInactive &&
        record.inactiveTargetWidth.isEmpty &&
        Vector[Expression](record.target, record.resizeSource,
          record.originalSource, record.sourceDriver.source).forall { expression =>
          NativeWidthProvenance.optionalWidthOf(expression).exists { width =>
            width.parameters.isEmpty &&
              ElaborationWidthAuthority.evaluate(width, Vector.empty).exists(_ > 0)
          }
        }
      retained = !concreteOnly && ((record.target eq alias) || (record.resizeSource eq alias) ||
        record.typedInput.exists(_ eq alias) ||
        record.typedResize.exists(expressionUses) ||
        expressionUses(record.originalSource) ||
        assignmentUses(record.outer) || assignmentUses(record.sourceDriver))
    }
    retained || storage.syntheticBoolean.exists { record =>
      (record.target eq alias) || (record.resizeSource eq alias) ||
        (record.bitsSource eq alias) || expressionUses(record.uintCast) ||
        expressionUses(record.boolCast) || assignmentUses(record.outer) ||
        assignmentUses(record.sourceDriver) || assignmentUses(record.bitsDriver)
    }
  }
}

package spinal.core.internals

import java.util.IdentityHashMap
import java.util.regex.Pattern
import scala.collection.mutable.ArrayBuffer
import spinal.core._

/** Publish exact native range and fill geometry retained before Int lowering.
  * Only a protected direct assignment with its original graph identities can
  * replace an emitted witness edge. Names locate edges; they are not proof.
  */
object ExternalParameterizedNativeGeometry {
  private object StorageKey
  private final case class Record(
      assignment: DataAssignmentStatement,
      target: BitVector,
      expression: Expression,
      source: Option[BitVector],
      width: ElaborationIntegerExpression,
      high: Option[ElaborationIntegerExpression],
      low: Option[ElaborationIntegerExpression],
      assignmentScope: NativePublicationScope,
      targetScope: NativePublicationScope,
      sourceScope: Option[NativePublicationScope],
      drivers: Vector[AssignmentStatement])

  private final class Storage(val records: Vector[Record]) {
    val byExpression = new IdentityHashMap[Expression, Record]()
    records.foreach { record =>
      if (byExpression.put(record.expression, record) != null)
        fail("one geometry expression has multiple publication owners")
    }
  }
  private def fail(detail: String): Nothing = throw new ParameterizedVerilogException(
    "SPINAL-PARAMETERIZED-VERILOG-NATIVE-GEOMETRY-LINEAGE-MISMATCH", detail)
  private def storage(component: Component): Option[Storage] =
    component.userCache.get(StorageKey).map(_.asInstanceOf[Storage])
  private val publicationValidation = new ThreadLocal[IdentityHashMap[Record, java.lang.Boolean]]()
  private def assignments(component: Component, target: BaseType): Vector[AssignmentStatement] = {
    val result = ArrayBuffer.empty[AssignmentStatement]
    component.dslBody.walkStatements {
      case assignment: AssignmentStatement if assignment.finalTarget eq target => result += assignment
      case _ =>
    }
    result.toVector
  }
  private def same[A <: AnyRef](left: Vector[A], right: Vector[A]): Boolean =
    left.size == right.size && left.zip(right).forall { case (a, b) => a eq b }

  private def sameRetainedWidth(left: ElaborationIntegerExpression,
                                right: ElaborationIntegerExpression,
                                component: Component, owner: BaseType): Boolean =
    ElabInt.equivalentExpression(left, right) &&
      NativePublicationWidth.equivalentAtOwner(left, right, component, owner)

  def install(phases: ArrayBuffer[Phase]): Unit = {
    val boundary = phases.indexWhere(_.isInstanceOf[PhaseRemoveIntermediateUnnameds])
    require(boundary >= 0, "native geometry requires the unnamed-intermediate boundary")
    phases.insert(boundary, new PhaseMisc {
      override def impl(pc: PhaseContext): Unit = pc.walkComponents { component =>
        val captured = ArrayBuffer.empty[Record]
        component.dslBody.walkStatements {
          case assignment: DataAssignmentStatement => assignment.target match {
            case target: BitVector if (assignment.finalTarget eq target) && target.isComb &&
                (target.component eq component) =>
              val geometry = assignment.source match {
                case access: BitVectorRangedAccessFixed => access.source match {
                  case source: BitVector if source.component eq component =>
                    for {
                      rule <- NativeWidthProvenance.rangeOf(access)
                      sourceWidth <- NativeWidthProvenance.widthOf(source)
                      if sourceWidth.parameters.nonEmpty
                    } yield (Some(source), rule.resultWidth(sourceWidth),
                      Some(rule.high(sourceWidth)), Some(rule.low(sourceWidth)))
                  case _ => None
                }
                case literal: BitVectorLiteral =>
                  NativeWidthProvenance.fillWidthOf(literal).filter(_.parameters.nonEmpty)
                    .map(width => (None, width, None, None))
                case _ => None
              }
              geometry.foreach { case (source, width, high, low) =>
                NativePublicationWidth.validate(width, component, target, "native geometry result")
                source.foreach { value =>
                  high.foreach(NativePublicationWidth.validate(_, component, value, "native range high"))
                  low.foreach(NativePublicationWidth.validate(_, component, value, "native range low"))
                  value.dontSimplifyIt().addTag(noBackendCombMerge)
                  if (!value.isNamed) value.setWeakName("morphhdl_range_source")
                }
                target.dontSimplifyIt().addTag(noBackendCombMerge)
                if (!target.isNamed) target.setWeakName("morphhdl_geometry")
                captured += Record(assignment, target, assignment.source, source, width, high, low,
                  NativePublicationScope.capture(component, assignment.parentScope),
                  NativePublicationScope.capture(component, target.parentScope),
                  source.map(value => NativePublicationScope.capture(component, value.parentScope)),
                  assignments(component, target))
              }
            case _ =>
          }
          case _ =>
        }
        if (captured.nonEmpty) component.userCache.put(StorageKey, new Storage(captured.toVector))
      }
    })
  }

  private def valid(component: Component, record: Record): Boolean = {
    val current = publicationValidation.get()
    (current != null && current.containsKey(record)) || validFresh(component, record)
  }

  private def validFresh(component: Component, record: Record): Boolean = {
    val currentWidth = record.expression match {
      case access: BitVectorRangedAccessFixed =>
        for {
          rule <- NativeWidthProvenance.rangeOf(access)
          source <- record.source if access.source eq source
          sourceWidth <- NativeWidthProvenance.widthOf(source)
          if record.high.exists(sameRetainedWidth(
            rule.high(sourceWidth), _, component, source))
          if record.low.exists(sameRetainedWidth(
            rule.low(sourceWidth), _, component, source))
        } yield rule.resultWidth(sourceWidth)
      case literal: BitVectorLiteral => NativeWidthProvenance.fillWidthOf(literal)
      case _ => None
    }
    var targetCount = 0
    var sourceCount = 0
    component.dslBody.walkStatements {
      case value: BaseType =>
        if (value eq record.target) targetCount += 1
        if (record.source.exists(_ eq value)) sourceCount += 1
      case _ =>
    }
    targetCount == 1 && (record.source.isEmpty || sourceCount == 1) &&
      same(assignments(component, record.target), record.drivers) &&
      record.drivers.exists(_ eq record.assignment) &&
      record.assignmentScope.matches(record.assignment.parentScope) &&
      record.targetScope.matches(record.target.parentScope) &&
      record.source.zip(record.sourceScope).forall { case (source, scope) =>
        (source.component eq component) && scope.matches(source.parentScope) &&
          source.dontSimplify && source.hasTag(noBackendCombMerge)
      } &&
      (record.assignment.target eq record.target) && (record.assignment.finalTarget eq record.target) &&
      (record.assignment.source eq record.expression) && (record.target.component eq component) &&
      record.target.isComb && record.target.dontSimplify && record.target.hasTag(noBackendCombMerge) &&
      currentWidth.exists(sameRetainedWidth(_, record.width, component, record.target))
  }

  private[internals] def widthOf(component: Component, expression: Expression)
      : Option[ElaborationIntegerExpression] = storage(component)
    .flatMap(value => Option(value.byExpression.get(expression))).map { record =>
      if (!valid(component, record)) fail("retained native geometry changed after capture")
      record.width
    }

  private[internals] def withPublicationValidation[A](component: Component)(body: => A): A = {
    val original = storage(component)
    def check(): Unit = {
      if (storage(component).orNull ne original.orNull) fail("native geometry storage changed during publication")
      original.foreach(_.records.foreach { record =>
        if (!validFresh(component, record)) fail("retained native geometry changed during publication")
      })
    }
    check()
    val previous = publicationValidation.get()
    val current = new IdentityHashMap[Record, java.lang.Boolean]()
    original.foreach(_.records.foreach(record => current.put(record, java.lang.Boolean.TRUE)))
    publicationValidation.set(current)
    try {
      val result = body
      check()
      result
    } finally {
      if (previous == null) publicationValidation.remove()
      else publicationValidation.set(previous)
    }
  }

  private[internals] def rewrite(component: Component, verilog: String): String = {
    var lines = verilog.split("\n", -1).toVector
    storage(component).foreach(_.records.foreach { record =>
      if (!valid(component, record)) fail("retained native geometry assignment changed after capture")
      val name = Option(record.target.getName()).filter(_.nonEmpty)
        .getOrElse(fail("native geometry target has no emitted name"))
      val (expected, replacement) = record.expression match {
        case access: BitVectorRangedAccessFixed =>
          val sourceName = Option(record.source.get.getName()).filter(_.nonEmpty)
            .getOrElse(fail("native geometry source has no emitted name"))
          (s"$sourceName[${access.hi} : ${access.lo}]",
            s"$sourceName[${record.high.get.verilog} : ${record.low.get.verilog}]")
        case literal: BitVectorLiteral =>
          val bits = literal.getWidth
          val witness = if (bits > 4) s"${bits}'h${literal.hexString(bits, false)}"
            else s"${bits}'b${literal.getBitsStringOn(bits, 'x')}"
          (witness, "{" + record.width.verilog + "{1'b1}}")
        case _ => fail("captured native geometry kind changed")
      }
      val assignment = ("^(\\s*(?:assign\\s+)?" + Pattern.quote(name) +
        "\\s*(?:<=|=)\\s*)(.*?)(;\\s*)$").r
      var matches = 0
      lines = lines.map {
        case assignment(prefix, rhs, suffix) if rhs.trim == expected =>
          matches += 1
          prefix + replacement + suffix
        case line => line
      }
      if (matches != 1) fail(s"native geometry '$name' has $matches exact emitted witness edges; expected one")
    })
    lines.mkString("\n")
  }
}

