  private def componentGraph(top: Component): Vector[Component] = {
    if (top == null) fail(
      "SPINAL-PARAMETERIZED-VERILOG-RECURSION-PUBLICATION-TOP-MISSING",
      "recursive publication quarantine ran without a top-level component"
