        10: h_active[0]=1'bx;
        11: h_active[0]=1'bz;
        12: v_active[0]=1'bx;
        13: v_active[0]=1'bz;
        14: begin running=0; base_x=13'bx; base_y=12'bz; end
        15: begin running=1'bx; h_active=0; v_active=0; end
      endcase
      check;
    end
    $display("PASS: %0d independent lane vectors; PPC4=0/1; all lanes; modular boundaries; X/Z", cases);
    $finish;
