  test("oneFilePerComponent rejects a shared netlist filename before elaboration") {
    withTemporaryDirectory { directory =>
      val config = SpinalConfig(
        targetDirectory = directory.toString,
        oneFilePerComponent = true
      )
      config.netlistFileName = "all-components.v"
      var factoryRuns = 0
      val result = MorphVerilog.tryGenerate(config) {
        factoryRuns += 1
        hierarchical()
      }
      result match {
        case Left(failure) =>
          assert(failure.stage == MorphVerilogStage.Configuration)
          assert(failure.detail.contains("netlistFileName"))
        case Right(report) => fail(s"expected configuration rejection, received $report")
      }
      assert(factoryRuns == 0)
    }
  }

  test("capture rejects case-insensitive file collisions without parsing module text") {
    withTemporaryDirectory { directory =>
      Files.write(directory.resolve("Top.v"), "module Top; endmodule\n".getBytes(StandardCharsets.UTF_8))
      Files.write(directory.resolve("top.v"), "module top; endmodule\n".getBytes(StandardCharsets.UTF_8))
      MorphPerComponentPublication.capture(directory, "Top") match {
        case Left(failure) =>
          assert(failure.stage == MorphVerilogStage.SingleSourceGeneration)
          assert(failure.detail.contains("FILENAME-COLLISION"))
        case Right(files) => fail(s"expected collision rejection, received $files")
      }
    }
  }

  private def checkIndependentPublication(): Unit = {
    val topName = "Increment61IndependentTop"
    val leafName = "Increment61IndependentLeaf"
    val diagnostic = "Increment61 child requires DATA_BITS >= GENERATION_BITS"
    for (split <- Vector(false, true)) {
      withTemporaryDirectory { directory =>
        val report = MorphVerilog(SpinalConfig(
          targetDirectory = directory.toString,
          oneFilePerComponent = split,
          headerWithDate = false
        ))(independent())
        val sources = report.generatedSourcesPaths.map(Paths.get(_))
        val texts = sources.map(read)
        val combined = texts.mkString("\n")
        assert(moduleDefinitions(combined).sorted ==
          Vector(leafName, topName).sorted)
        assert(combined.contains("(DATA_BITS + GENERATION_BITS)-1:0"))
        for (name <- Vector("DATA_BITS", "GENERATION_BITS")) {
          val binding = s".$name($name)"
          assert(combined.sliding(binding.length).count(_ == binding) == 2)
        }
        assert(combined.sliding("$fatal(1,".length).count(_ == "$fatal(1,") == 1)
        assert(combined.contains(diagnostic))
        if (split) {
          assert(sources.map(_.getFileName.toString) ==
            Vector(leafName + ".v", topName + ".v"))
          val leaf = read(directory.resolve(leafName + ".v"))
          assert(leaf.contains("`ifndef SYNTHESIS") && leaf.contains(diagnostic))
          assert(!read(directory.resolve(topName + ".v")).contains("$fatal("))
          assert(read(directory.resolve(topName + ".lst")).split("\n").toVector ==
            sources.map(_.getFileName.toString))
        } else assert(sources.size == 1)

        // Compile the exact complete publication, with no source concatenation
        // or text normalization. Simulation consumes these same native files.
        val fileArguments = sources.map(_.toString)
        NativeWireCompatibility.run(directory,
          Seq("iverilog", "-g2001", "-s", topName, "-tnull") ++ fileArguments)
        // The synthesizable hardware remains Verilog-2001. PR188's guarded
        // $fatal diagnostic needs a SystemVerilog parser; check that view too,
        // without SYNTHESIS, and retain the unguarded runtime rejection below.
        NativeWireCompatibility.run(directory,
          Seq("verilator", "--lint-only", "--language", "1364-2001", "-DSYNTHESIS", "--top-module", topName) ++ fileArguments)
        NativeWireCompatibility.run(directory,
          Seq("verilator", "--lint-only", "--assert", "--language", "1800-2012", "--top-module", topName) ++ fileArguments)
        NativeWireCompatibility.run(directory, Seq("yosys", "-q", "-p",
          s"read_verilog -noautowire ${fileArguments.mkString(" ")}; hierarchy -check -top $topName; proc; memory; flatten; opt; check -assert; write_verilog synthesized.v"))
        assert(!read(directory.resolve("synthesized.v")).contains(diagnostic))

        // Includes unequal axes, both domain corners, and invalid nondefault
        // tuples. These are representative overrides, not a full-domain proof.
        for ((dataBits, generationBits) <- Vector((1, 1), (2, 2), (8, 1), (8, 8), (1, 2), (1, 8))) {
          val width = dataBits + generationBits
          val testbench = directory.resolve(s"independent-$dataBits-$generationBits.v")
          Files.write(testbench, s"""module Increment61IndependentCheck;
            |  reg [$width-1:0] din;
            |  wire [$width-1:0] leftOut, rightOut;
            |  integer bitIndex;
            |  $topName #(.DATA_BITS($dataBits), .GENERATION_BITS($generationBits)) dut
            |    (.din(din), .leftOut(leftOut), .rightOut(rightOut));
            |  task check;
            |    begin
            |      #1;
            |      if (leftOut !== din || rightOut !== din)
            |        $$fatal(1, "independent publication data mismatch");
            |    end
            |  endtask
            |  initial begin
            |    if ($$bits(dut.left.din) != $width || $$bits(dut.right.din) != $width)
            |      $$fatal(1, "independent publication child width mismatch");
            |    din = 0; check;
            |    din = {$width{1'b1}}; check;
            |    for (bitIndex = 0; bitIndex < $width; bitIndex = bitIndex + 1) begin
            |      din = 0; din[bitIndex] = 1'b1; check;
            |    end
            |    din = {$width{1'bx}}; check;
            |    din = {$width{1'bz}}; check;
            |    $$display("INCREMENT61_INDEPENDENT_PUBLICATION_PASS");
            |    $$finish;
            |  end
            |endmodule
            |""".stripMargin.getBytes(StandardCharsets.UTF_8))
          val binary = directory.resolve(s"independent-$dataBits-$generationBits.vvp")
          NativeWireCompatibility.run(directory,
            Seq("iverilog", "-g2012", "-s", "Increment61IndependentCheck", "-o", binary.toString) ++
              fileArguments :+ testbench.toString)
          if (dataBits >= generationBits) {
            assert(NativeWireCompatibility.run(directory, Seq("vvp", binary.toString))
              .contains("INCREMENT61_INDEPENDENT_PUBLICATION_PASS"))
          } else {
            val failure = intercept[IllegalArgumentException] {
              NativeWireCompatibility.run(directory, Seq("vvp", binary.toString))
            }
            assert(failure.getMessage.contains(diagnostic))
            assert(!failure.getMessage.contains("INCREMENT61_INDEPENDENT_PUBLICATION_PASS"))
          }
        }
      }
    }
  }

  private def moduleDefinitions(verilog: String): Vector[String] =
    "(?m)^\\s*module\\s+([A-Za-z_][A-Za-z0-9_$]*)\\b".r
      .findAllMatchIn(verilog)
      .map(_.group(1))
      .toVector

  private def sha256(bytes: Array[Byte]): String =
    MessageDigest
      .getInstance("SHA-256")
      .digest(bytes)
      .map(value => f"${value & 0xff}%02x")
      .mkString

  private def read(path: Path): String =
    new String(Files.readAllBytes(path), StandardCharsets.UTF_8)

  private def withTemporaryDirectory[A](body: Path => A): A = {
    val directory = Files.createTempDirectory("morphhdl-increment-61-")
    try body(directory)
    finally deleteTree(directory)
  }

  private def deleteTree(root: Path): Unit = {
    if (Files.exists(root)) {
      val stream = Files.walk(root)
      try stream.iterator().asScala.toVector.sortBy(_.getNameCount).reverse.foreach(Files.deleteIfExists)
      finally stream.close()
    }
  }
}

package morphhdl

import spinal.core._

/** Standalone condition-receiver regression.
  * No signal is classified using its emitted name. @dontName leaves the
  * compiler free to attach removable source-location provenance in when().
  */
class LaneConditionCoverageExample(ppc: ElabInt) extends Component {
  setDefinitionName("LaneConditionCoverageExample")
  val io = new Bundle {
    val x = in UInt(13 bits)
    val y = in UInt(12 bits)
    val hTotal = in UInt(13 bits)
    val vTotal = in UInt(12 bits)
    val witnessIn = in Bits(ppc bits)
    val witnessOut = out Bits(ppc bits)
    val singleX = out UInt(13 bits)
    val sharedX = out UInt(13 bits)
    val sharedY = out UInt(12 bits)
    val nestedX = out UInt(13 bits)
    val nestedY = out UInt(12 bits)
    val priority = out Bits(2 bits)
    val mixedX = out UInt(13 bits)
    val booleanRhs = out Bool()
    val protectedX = out UInt(13 bits)
    val protectedBoolean = out Bool()
    val keptGeneratedX = out UInt(13 bits)
  }
  io.witnessOut := io.witnessIn

  // A single-use compiler-created condition.
  io.singleX := io.x + 1
  when(io.x === io.hTotal - 1) { io.singleX := 0 }

  // Separate when statements keep the two receiver trees distinct.
  @dontName val shared = Bool()
  shared := io.x === io.hTotal - 1
  io.sharedX := io.x + 1
  io.sharedY := io.y
  when(shared) { io.sharedX := 0 }
  when(shared) { io.sharedY := io.y + 1 }

  io.nestedX := io.x + 1
  io.nestedY := io.y
  when(io.x === io.hTotal - 1) {
    io.nestedX := 0
    io.nestedY := io.y + 1
    when(io.y === io.vTotal - 1) { io.nestedY := 0 }
  }

  // The first branch wins when hTotal=1 and x=0.
  when(io.x === 0) {
    io.priority := B(0, 2 bits)
  } elsewhen(io.x === io.hTotal - 1) {
    io.priority := B(1, 2 bits)
  } otherwise {
    io.priority := B(2, 2 bits)
  }

  @dontName val mixed = Bool()
  mixed := io.y === io.vTotal - 1
  io.booleanRhs := mixed
  io.mixedX := io.x
  when(mixed) { io.mixedX := 0 }

  // Explicit user identity plus protection: a generated-name lookalike.
  val when_example_l42 = Bool()
  when_example_l42.setName("when_example_l42")
  when_example_l42.addAttribute("keep")
  when_example_l42 := io.x === io.hTotal - 1
  io.protectedBoolean := when_example_l42
  io.protectedX := io.x + 1
  when(when_example_l42) { io.protectedX := 0 }

  // Independently exercise protection on a compiler-name-eligible signal.
  @dontName val keptGenerated = Bool()
  keptGenerated.addAttribute("keep")
  keptGenerated := io.x === io.hTotal - 1
  io.keptGeneratedX := io.x + 1
  when(keptGenerated) { io.keptGeneratedX := 0 }
}

package morphhdl

import java.nio.file.{Files, Paths}
import spinal.core._
import morphhdl.frontend.HdlBool

/** All modes use the real public parameterized entry point, never a fallback. */
object LaneInliningRegressionWriter {
  def main(args: Array[String]): Unit = {
    require(args.length == 1, "Usage: LaneInliningRegressionWriter OUTPUT_DIRECTORY")
    for (round <- Vector("first", "repeat"); mode <- Vector("default", "enabled", "disabled");
         topology <- Vector("lane", "conditions", "receivers")) {
      val directory = Paths.get(args(0), round, mode, topology)
      Files.createDirectories(directory)
      val config = SpinalConfig(targetDirectory = directory.toString,
        oneFilePerComponent = false, headerWithDate = false, headerWithRepoHash = true)
      config.netlistFileName = "design.v"
      val selected = mode match {
        case "default" => config
        case "enabled" => MorphWireAssignmentPasses(config, enabled = true)
        case "disabled" => MorphWireAssignmentPasses(config, enabled = false)
      }
      MorphVerilog(selected) {
        val ppc = HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1
        topology match {
          case "lane" => new LaneExpressionExample(ppc)
          case "conditions" => new LaneConditionCoverageExample(ppc)
          case "receivers" => new LaneReceiverCoverageExample(ppc)
        }
      }
    }
    println("LANE REGRESSIONS: generated all 18 production artifacts")
  }
}

package morphhdl

import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path}
import scala.collection.JavaConverters._
import org.scalatest.funsuite.AnyFunSuite
import spinal.core._
import morphhdl.frontend.HdlBool

/** Production API tests. HDL simulation/formal checks accompany these artifacts. */
class LaneWhenInliningRegressionTests extends AnyFunSuite {
  private def emit(mode: String = "default", customize: SpinalConfig => Unit = _ => ())(factory: ElabInt => Component): String = {
    val dir = Files.createTempDirectory("lane-when-regression-")
    try {
      val base = SpinalConfig(targetDirectory = dir.toString, oneFilePerComponent = false,
        headerWithDate = false, headerWithRepoHash = true)
      base.netlistFileName = "design.v"
      customize(base)
      val config = mode match {
        case "default" => base
        case "enabled" => MorphWireAssignmentPasses(base, enabled = true)
        case "disabled" => MorphWireAssignmentPasses(base, enabled = false)
      }
      MorphVerilog(config) {
        factory(HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1)
      }
      new String(Files.readAllBytes(dir.resolve("design.v")), StandardCharsets.UTF_8)
    } finally {
      val paths = Files.walk(dir)
      try paths.iterator().asScala.toVector.sortBy(_.getNameCount).reverse.foreach(Files.deleteIfExists(_))
      finally paths.close()
    }
  }
  private def assignments(v: String, fragment: String): Vector[String] =
    v.split("\n").filter(line => line.trim.startsWith("assign ") && line.contains(fragment)).toVector
  private lazy val lane = emit()(new LaneExpressionExample(_))
  private lazy val disabledLane = emit("disabled")(new LaneExpressionExample(_))
  private lazy val conditions = emit()(new LaneConditionCoverageExample(_))
  private lazy val receivers = emit()(new LaneReceiverCoverageExample(_))

  test("all four laneDe comparisons inline fixed extensions through the process-separation tag") {
    val namedClass = Class.forName("morphhdl.examples.NamedWireExpressionNativePhase")
    val namedConstructor = namedClass.getConstructor(java.lang.Boolean.TYPE)
    for (unnamedOnly <- Vector(false, true)) {
      val phase = namedConstructor.newInstance(Boolean.box(unnamedOnly))
        .asInstanceOf[spinal.core.internals.Phase]
      assert(phase.hasNetlistImpact)
    }
    for (name <- Vector("UnnamedWireExpressionNativePhase", "ProductionWireAssignmentPhase")) {
      val constructor = Class.forName("morphhdl.examples." + name).getConstructor()
      val first = constructor.newInstance().asInstanceOf[spinal.core.internals.Phase]
      val second = constructor.newInstance().asInstanceOf[spinal.core.internals.Phase]
      assert(first.hasNetlistImpact && second.hasNetlistImpact)
      assert(first ne second)
    }
    assert(!lane.contains("_zz_laneDe"), lane)
    for (n <- 0 until 4) {
      assert(lane.contains(s"laneDe[$n] = ((io_running && ({3'd0, laneX_$n} < io_hActive)) && ({4'd0, laneY_$n} < io_vActive));"), lane)
    }
    assert(lane.contains("reg        [3:0]    laneDe;"), lane)
  }
  test("laneFrameEnd retains 16-bit modular subtraction while inlining both extensions") {
    assert(!lane.contains("_zz_laneFrameEnd"), lane)
    for (n <- 0 until 4) {
      assert(lane.contains(s"laneFrameEnd[$n] = ((io_running && ({3'd0, laneX_$n} == (io_hActive - 16'h0001))) && ({4'd0, laneY_$n} == (io_vActive - 16'h0001)));"), lane)
    }
  }
  test("small generated conditions inline at all split and nested receivers without rematerialization") {
    assert(assignments(lane, "when_").isEmpty, lane)
    assert(!lane.contains("_zz_when"), lane)
    for (n <- 0 until 4) {
      assert(lane.contains(s"if((laneX_$n == (io_hTotal - 13'h0001)))"), lane)
      assert(lane.contains(s"if((laneY_$n == (io_vTotal - 12'h001)))"), lane)
    }
    assert(lane.split("always @", -1).length == disabledLane.split("always @", -1).length)
  }
  test("default and explicit enable are identical and repeated generation is deterministic") {
    assert(lane == emit("enabled")(new LaneExpressionExample(_)))
    assert(lane == emit()(new LaneExpressionExample(_)))
    assert(disabledLane == emit("disabled")(new LaneExpressionExample(_)))
  }
  test("disabled generation retains the legacy carrier forms and symbolic output geometry") {
    assert(disabledLane.contains("assign _zz_laneDe = {3'd0, laneX_0};"))
    assert(disabledLane.contains("assign when_"))
    for (v <- Vector(lane, disabledLane)) {
      assert(v.contains("parameter integer PPC4 = 0"))
      assert(v.contains("[((PPC4 * 3) + 1)-1:0]    io_de"))
      assert(v.contains("[((PPC4 * 3) + 1)-1:0]    io_frameEnd"))
    }
  }
  test("single shared priority and mixed Boolean RHS conditions inline; two protected identities survive") {
    assert(conditions.contains("assign io_booleanRhs = (io_y == (io_vTotal - 12'h001));"), conditions)
    assert(conditions.contains("if((io_x == 13'h0))"), conditions)
    val declarations = conditions.split("\n").filter(line => line.contains("wire") && line.contains("when_") && !line.contains("_zz_"))
    assert(declarations.length == 2, conditions)
    assert(declarations.forall(_.contains("(* keep *)")), conditions)
    assert(conditions.contains("if(when_example_l42)"), conditions)
    assert(conditions.contains("assign io_protectedBoolean = when_example_l42;"), conditions)
  }
  test("whole Bool and disjoint bit receivers agree while overlapping dynamic and protected receivers retain fences") {
    assert(!receivers.contains("_zz_io_whole"), receivers)
    assert(!receivers.contains("_zz_lanes"), receivers)
    assert(receivers.contains("_zz_overlapping"), receivers)
    assert(receivers.contains("_zz_dynamicallySelected"), receivers)
    assert(receivers.contains("(* keep *) reg        [3:0]    keptLane;"), receivers)
    assert(receivers.contains("_zz_keptLane"), receivers)
  }
  test("disjoint fixed ranges retain their own widths with the layout-only tag") {
    val v = emit() { ppc => new Component {
      setDefinitionName("LaneFixedRanges")
      val a, b, c = in UInt(18 bits)
      val packedValue = out UInt(36 bits)
      packedValue.addTag(noBackendCombMerge)
      val witnessIn = in Bits(ppc bits)
      val witnessOut = out Bits(ppc bits)
      witnessOut := witnessIn
      packedValue(17 downto 0) := (a + b) + c
      packedValue(35 downto 18) := (a - b) - c
    }}
    assert(!v.contains("_zz_packedValue"), v)
    assert(v.contains("packedValue[17 : 0] = ((a + b) + c);"), v)
    assert(v.contains("packedValue[35 : 18] = ((a - b) - c);"), v)
  }

  private object UnknownIntent extends SpinalTag
  private final class ProtectedCondition(ppc: ElabInt, protection: Int) extends Component {
    setDefinitionName("LaneProtectedCondition")
    val x, total = in UInt(13 bits)
    val value = out UInt(13 bits)
    val witnessIn = in Bits(ppc bits)
    val witnessOut = out Bits(ppc bits)
    witnessOut := witnessIn
    @dontName val condition = x === total - 1
    protection match {
      case 0 => condition.setAsVital()
      case 1 => condition.dontSimplifyIt()
      case 2 => condition.freeze()
      case 3 => condition.addTag(spinal.core.sim.SimPublic)
      case 4 => condition.setName("when_user_l42")
      case 5 => condition.addTag(UnknownIntent)
      case 6 => // The application transformation phase supplies vital intent.
    }
    value := x + 1
    when(condition) { value := 0 }
  }
  for ((label, protection) <- Vector("explicit vital", "dontSimplify", "frozen", "debug", "explicit lookalike", "unknown metadata").zipWithIndex) {
    test(s"$label condition identity is not erased") {
      var fixture: ProtectedCondition = null
      val v = emit() { ppc => fixture = new ProtectedCondition(ppc, protection); fixture }
      val name = fixture.condition.getName()
      assert(v.contains(s"assign $name = "), v)
      assert(v.contains(s"if($name)"), v)
    }
  }
  test("application transformation-phase vital intent is captured before inferred liveness") {
    var fixture: ProtectedCondition = null
    val v = emit(customize = config => {
      config.transformationPhases += new spinal.core.internals.Phase {
        override def hasNetlistImpact: Boolean = false
        override def impl(pc: spinal.core.internals.PhaseContext): Unit =
          fixture.condition.setAsVital()
      }
    }) { ppc => fixture = new ProtectedCondition(ppc, 6); fixture }
    val name = fixture.condition.getName()
    assert(v.contains(s"assign $name = "), v)
    assert(v.contains(s"if($name)"), v)
  }
  test("source dependency written in a potentially coalesced blocking process stays fenced") {
    var condition: Bool = null
    val v = emit() { ppc => new Component {
      setDefinitionName("LaneBlockingCondition")
      val source, enable = in Bool()
      val result = out Bool()
      val witnessIn = in Bits(ppc bits)
      val witnessOut = out Bits(ppc bits)
      witnessOut := witnessIn
      val stage = Bool()
      @dontName val predicate = !stage
      condition = predicate
      stage := source
      result := False
      when(enable) {
        stage := !source
        when(predicate) { result := True }
      }
    }}
    assert(v.contains(s"assign ${condition.getName()} = "), v)
    assert(v.contains(s"if(${condition.getName()})"), v)
  }
  test("more than 32 generated-condition receivers retain their common predicate") {
    var condition: Bool = null
    val v = emit() { ppc => new Component {
      setDefinitionName("LaneConditionExpansionBudget")
      val x, total = in UInt(13 bits)
      val values = out Vec(UInt(13 bits), 33)
      val witnessIn = in Bits(ppc bits)
      val witnessOut = out Bits(ppc bits)
      witnessOut := witnessIn
      @dontName val predicate = x === total - 1
      condition = predicate
      for (n <- 0 until 33) {
        values(n) := x + U(n, 13 bits)
        when(predicate) { values(n) := 0 }
      }
    }}
    assert(v.contains(s"assign ${condition.getName()} = "), v)
  }
}

