package morphhdl.examples

import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path, Paths}
import scala.collection.mutable.ArrayBuffer
import spinal.core._
import spinal.core.internals._
import morphhdl.{LaneExpressionExample, MorphVerilog, MorphWireAssignmentPasses}
import morphhdl.frontend.HdlBool

/** Observes the real production phase; does not replace its implementation. */
private object LaneWhenNativeTrace {
  def install(config: SpinalConfig, output: Path): Unit = {
    config.phasesInserters += { phases: ArrayBuffer[Phase] =>
      val index = phases.indexWhere(_.getClass.getName ==
        "morphhdl.examples.ProductionWireAssignmentPhase")
      require(index >= 0, "production wire-assignment phase missing")
      val production = phases(index)
      val intent = phases.collectFirst { case value: NativeConditionSourceIntent => value }
      val inspector = new NamedWireExpressionNativePhase(conditionSourceIntent = intent)
      phases.update(index, new Phase {
        override def hasNetlistImpact: Boolean = production.hasNetlistImpact
        override def impl(pc: PhaseContext): Unit = {
          val lines = ArrayBuffer.empty[String]
          def width(expression: Expression): Int = expression match {
            case _ if expression.getTypeObject == TypeBool => 1
            case value: WidthProvider => value.getWidth
            case _ => -1
          }
          def snapshot(label: String): Unit = pc.components().foreach {
            case component: LaneExpressionExample =>
              for ((name, target) <- Vector("laneDe" -> component.laneDe,
                  "laneFrameEnd" -> component.laneFrameEnd)) {
                val tags = target.getTags().map(_.getClass.getName).mkString(",")
                lines += s"$label\ttarget=$name\twidth=${target.getBitsWidth}\ttags=$tags\t" +
                  s"symbolic=${ParameterizedWidth.expressionOf(target).map(_.verilog)}"
                target.foreachStatements {
                  case assignment: DataAssignmentStatement =>
                    lines += s"$label\ttarget=$name\treceiver=${assignment.target.getClass.getName}" +
                      s"\treceiverWidth=${width(assignment.target)}\trhs=${assignment.source.opName}"
                    assignment.walkDrivingExpressions {
                      case resize: Resize =>
                        lines += s"$label\tresize=${resize.getClass.getName}\twidth=${width(resize)}" +
                          s"\tinputWidth=${width(resize.input)}\tinputType=${resize.input.getTypeObject}" +
                          s"\tsymbolic=${ParameterizedWidth.resizeExpressionOf(resize).map(_.verilog)}"
                      case _ =>
                    }
                  case _ =>
                }
              }
              component.dslBody.walkStatements {
                case condition: WhenStatement =>
                  lines += s"$label\twhen=${condition.getClass.getName}\tcondition=${condition.cond.opName}" +
                    s"\tconditionType=${condition.cond.getClass.getName}\twidth=${width(condition.cond)}"
                  condition.cond match {
                    case value: BaseType =>
                      value.head.source.walkDrivingExpressions {
                        case source: BaseType =>
                          lines += s"$label\tcondition-source=${source.getName("")}\twidth=${source.getBitsWidth}\t" +
                            s"type=${source.getTypeObject}\tsame-component=${source.component eq component}\t" +
                            s"root=${source.parentScope eq source.rootScopeStatement}\t" +
                            s"null-scope=${source.parentScope == null}\tanalog=${source.isAnalog}\tinout=${source.isInOut}\t" +
                            s"symbolic=${ParameterizedWidth.expressionOf(source)}"
                        case _ =>
                      }
                      var occurrences = 0
                      pc.components().foreach(_.dslBody.walkStatements { statement =>
                        statement.walkDrivingExpressions {
                          case reference: BaseType if reference eq value => occurrences += 1
                          case _ =>
                        }
                      })
                      lines += s"$label\tconditionCarrier=${value.getName("")}\t" +
                        s"origin=${NativeWireNameProvenance.origin(value)}\t" +
                        s"typeNode=${value.isTypeNode}\tnamed=${value.isNamed}\t" +
                        s"root=${value.parentScope eq value.rootScopeStatement}\tcomponent-root=${value.parentScope eq component.dslBody}\t" +
                        s"singleDriver=${value.hasOnlyOneStatement}\toccurrences=$occurrences\t" +
                        s"intent=${intent.exists(_.permits(value))}\tretained=${inspector.retentionReasonFor(pc, value)}\t" +
                        s"frozen=${value.isFrozen()}\ttags=${value.getTags().map(_.getClass.getName).mkString(",")}"
                    case _ =>
                  }
                case _ =>
              }
            case _ =>
          }
          snapshot("before-production")
          production.impl(pc)
          snapshot("after-production")
          Files.createDirectories(output.getParent)
          Files.write(output, (lines.mkString("\n") + "\n").getBytes(StandardCharsets.UTF_8))
        }
      })
    }
  }
}

/** Three executions of the public API: enabled, repeated, and explicitly disabled. */
object LaneWhenInliningArtifactWriter extends App {
  require(args.length == 1, "usage: LaneWhenInliningArtifactWriter OUTPUT_DIRECTORY")
  val output = Paths.get(args(0)).toAbsolutePath.normalize
  def generate(name: String, enabled: Boolean, trace: Boolean): Unit = {
    val directory = output.resolve(name)
    Files.createDirectories(directory)
    val config = MorphWireAssignmentPasses(SpinalConfig(
      targetDirectory = directory.toString,
      oneFilePerComponent = false,
      headerWithDate = false,
      headerWithRepoHash = true
    ), enabled)
    config.netlistFileName = "LaneExpressionExample.v"
    if (trace) LaneWhenNativeTrace.install(config, directory.resolve("native.tsv"))
    MorphVerilog(config) {
      new LaneExpressionExample(
        HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1)
    }
  }
  generate("enabled", enabled = true, trace = false)
  generate("repeat", enabled = true, trace = false)
  generate("disabled", enabled = false, trace = false)
  generate("trace", enabled = true, trace = true)
  def bytes(name: String): Array[Byte] =
    Files.readAllBytes(output.resolve(name).resolve("LaneExpressionExample.v"))
  require(java.util.Arrays.equals(bytes("enabled"), bytes("repeat")),
    "repeated generation changed the final Verilog artifact")
  require(java.util.Arrays.equals(bytes("enabled"), bytes("trace")),
    "read-only native observation changed the final Verilog artifact")
  println("Lane artifact generation: deterministic and observation-neutral")
}

package morphhdl.examples

import java.nio.charset.StandardCharsets
import java.nio.file.Files
import scala.collection.JavaConverters._
import scala.collection.mutable.ArrayBuffer
import org.scalatest.funsuite.AnyFunSuite
import spinal.core._
import spinal.core.internals._
import morphhdl.{MorphVerilog, MorphWireAssignmentPasses}
import morphhdl.frontend.HdlBool

/** Query the very same read-only eligibility proof used by native writeback. */
class SequentialWireRetentionTests extends AnyFunSuite {
  private def inspect(kind: String): (Option[String], String, String, String) = {
    val directory = Files.createTempDirectory("sequential-retention-")
    var predicate: Bool = null
    var inputPort: Bool = null
    var observed = false
    var reason: Option[String] = None
    try {
      val config = MorphWireAssignmentPasses(SpinalConfig(targetDirectory = directory.toString,
        oneFilePerComponent = false, headerWithDate = false))
      config.netlistFileName = "dut.v"
      config.phasesInserters += { phases: ArrayBuffer[Phase] =>
        val index = phases.indexWhere(_.getClass.getName == "morphhdl.examples.ProductionWireAssignmentPhase")
        require(index >= 0)
        val intent = phases.collectFirst { case value: NativeConditionSourceIntent => value }
        phases.insert(index, new Phase {
          override def hasNetlistImpact: Boolean = false
          override def impl(pc: PhaseContext): Unit = {
            reason = new NamedWireExpressionNativePhase(conditionSourceIntent = intent)
              .retentionReasonFor(pc, predicate)
            if (kind == "explicit" || kind == "explicit-declaration") {
              assert(NativeWireNameProvenance.origin(predicate)
                .flatMap(_.explicitName).contains("when_user_l456"))
              // An explicitly named expression result is still a type node.
              // candidateForValue admits type nodes only for generated/unnamed
              // conditions. This is NOT a direct BaseType-to-BaseType alias.
              assert(predicate.isTypeNode == (kind == "explicit"))
              val expression = predicate.head.asInstanceOf[DataAssignmentStatement].source
              assert(expression.isInstanceOf[Operator.Bool.Not], expression)
              assert(expression.asInstanceOf[Operator.Bool.Not].source eq inputPort)
            }
            observed = true
          }
        })
      }
      MorphVerilog(config) {
        val ppc = HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1
        new Component {
          val laneWitness = out Bits(ppc bits)
          laneWitness := 0
          val input = in Bool()
          inputPort = input
          val select = in UInt(2 bits)
          val result = out Bits(8 bits)
          val state = Reg(Bits(8 bits)) init(0)
          @dontName val condition = if (kind == "explicit-declaration") {
            val declaration = Bool()
            declaration := !input
            declaration
          } else !input
          predicate = condition
          kind match {
            case "keep" => condition.addAttribute("keep")
            case "vital" => condition.setAsVital()
            case "explicit" | "explicit-declaration" => condition.setName("when_user_l456")
            case _ =>
          }
          when(condition) {
            if (kind == "partial") state(0) := True else state := 1
          }
          if (kind == "switch") {
            switch(select) { is(0) { when(condition) { state := 2 } } }
          }
          result := state
        }
      }
      assert(observed, "The real production boundary was not observed")
      (reason, predicate.getName(""), inputPort.getName(""),
        new String(Files.readAllBytes(directory.resolve("dut.v")), StandardCharsets.UTF_8))
    } finally {
      val paths = Files.walk(directory)
      try paths.iterator.asScala.toVector.sortBy(_.getNameCount).reverse.foreach(Files.deleteIfExists(_))
      finally paths.close()
    }
  }
  test("safe sequential condition has no native retention diagnostic") {
    val (reason, _, inputName, verilog) = inspect("safe")
    assert(reason.isEmpty, reason)
    assert(!verilog.contains("assign when_"), verilog)
    assert(verilog.contains(s"if((! $inputName))"), verilog)
  }
  for ((kind, expected) <- Vector(
      "keep" -> "WA10-CONDITION-PRESERVATION",
      "vital" -> "WA10-CONDITION-SOURCE-INTENT",
      "explicit" -> "WA10-CONDITION-NOT-A-CANDIDATE",
      "explicit-declaration" -> "WA10-CONDITION-USER-NAME",
      "switch" -> "WA10-CONDITION-RECEIVER-CONTEXT",
      "partial" -> "WA10-CONDITION-UNSUPPORTED-CONTROL")) {
    test(s"$kind receiver is retained with its exact native reason") {
      val (reason, name, _, verilog) = inspect(kind)
      assert(reason.contains(expected), reason)
      assert(name.nonEmpty && verilog.contains(s"assign $name = "), verilog)
      assert(verilog.contains(s"if($name)"), verilog)
    }
  }

  /** Observe the normalized graph, including the intermediary that hid vital intent. */
  private def inspectAlias(shape: String, protectedAlias: Boolean): Unit = {
    val directory = Files.createTempDirectory("alias-source-intent-")
    var alias: UInt = null
    var sourcePort: UInt = null
    var observed = false
    try {
      val config = MorphWireAssignmentPasses(SpinalConfig(targetDirectory = directory.toString,
        oneFilePerComponent = false, headerWithDate = false))
      config.netlistFileName = "dut.v"
      config.phasesInserters += { phases: ArrayBuffer[Phase] =>
        val index = phases.indexWhere(_.getClass.getName == "morphhdl.examples.ProductionWireAssignmentPhase")
        require(index >= 0)
        val intent = phases.collectFirst { case value: NativeConditionSourceIntent => value }.get
        phases.insert(index, new Phase {
          override def hasNetlistImpact: Boolean = false
          override def impl(pc: PhaseContext): Unit = {
            assert(alias.isUnnamed && !alias.isTypeNode && alias.hasOnlyOneStatement)
            assert(alias.head.asInstanceOf[DataAssignmentStatement].source eq sourcePort)
            // Both aliases are now live. Only the captured source intent can
            // distinguish the explicit vital alias from the unprotected one.
            assert(alias.isVital)
            assert(intent.permits(alias) == !protectedAlias)
            val consumers = ArrayBuffer.empty[DataAssignmentStatement]
            alias.component.dslBody.walkStatements {
              case assignment: DataAssignmentStatement if assignment.finalTarget ne alias =>
                var referencesAlias = false
                assignment.walkDrivingExpressions {
                  case value: BaseType if value eq alias => referencesAlias = true
                  case _ =>
                }
                if (referencesAlias) consumers += assignment
              case _ =>
            }
            assert(consumers.nonEmpty)
            if (shape == "whole-register") assert(consumers.exists(_.finalTarget.isReg))
            else {
              // .resized first makes a direct clone, then normalization puts
              // the narrowing Resize on that clone's consumer. This extra
              // combinational hop hid the original alias from a register-only
              // source-intent check; assert both links rather than guessing
              // that the immediate consumer already contains the Resize.
              assert(consumers.forall(_.finalTarget.isComb))
              assert(consumers.forall(_.source eq alias))
              val intermediaries = consumers.map(_.finalTarget)
              var narrowedConsumer = false
              alias.component.dslBody.walkStatements {
                case assignment: DataAssignmentStatement
                    if (shape == "register-slice" && assignment.finalTarget.isReg) ||
                      (shape == "comb-slice" && assignment.finalTarget.isOutput) =>
                  assignment.walkDrivingExpressions {
                    case resize: Resize if resize.size == 13 &&
                        intermediaries.exists(_ eq resize.input) => narrowedConsumer = true
                    case _ =>
                  }
                case _ =>
              }
              assert(narrowedConsumer, "The expected clone-to-slice consumer is missing")
            }
            val reason = new UnnamedWireAliasNativePhase(Some(intent)).retentionReasonFor(pc, alias)
            if (protectedAlias) assert(reason.contains("WA04-NATIVE-SOURCE-INTENT"), reason)
            else assert(reason.isEmpty, reason)
            observed = true
          }
        })
      }
      MorphVerilog(config) {
        val ppc = HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1
        new Component {
          val laneWitness = out Bits(ppc bits)
          laneWitness := 0
          val source = in UInt(18 bits)
          sourcePort = source
          @dontName val direct = UInt(18 bits)
          alias = direct
          direct := source
          if (protectedAlias) direct.setAsVital()
          val width = if (shape == "whole-register") 18 else 13
          val result = out UInt(width bits)
          if (shape == "comb-slice") result := direct.resized
          else {
            val state = Reg(UInt(width bits)) init(0)
            state.setName("state")
            if (shape == "whole-register") state := direct else state := direct.resized
            result := state
          }
        }
      }
      assert(observed, "The production-boundary observer did not run")
      val verilog = new String(Files.readAllBytes(directory.resolve("dut.v")), StandardCharsets.UTF_8)
      val name = alias.getName("")
      if (protectedAlias) {
        assert(name.nonEmpty, verilog)
        assert(verilog.contains(s"assign $name = ${sourcePort.getName()};"), verilog)
        val selected = if (shape == "whole-register") name else s"$name[12:0]"
        assert(verilog.contains((if (shape == "comb-slice") "assign result = " else "state <= ") + selected + ";"), verilog)
      } else {
        assert(alias.parentScope == null, "The unprotected alias must really be removed")
        val selected = if (shape == "whole-register") sourcePort.getName() else s"${sourcePort.getName()}[12:0]"
        assert(verilog.contains((if (shape == "comb-slice") "assign result = " else "state <= ") + selected + ";"), verilog)
      }
    } finally {
      val paths = Files.walk(directory)
      try paths.iterator.asScala.toVector.sortBy(_.getNameCount).reverse.foreach(Files.deleteIfExists(_))
      finally paths.close()
    }
  }

  for (shape <- Vector("whole-register", "register-slice", "comb-slice");
       protectedAlias <- Vector(false, true)) {
    test(s"$shape honors captured vital=$protectedAlias independent of immediate consumer kind") {
      inspectAlias(shape, protectedAlias)
    }
  }
}

package nativeapplication

import java.nio.file.{Files, Path, Paths}

import morphhdl.{MorphVerilog, MorphWireAssignmentPasses}
import morphhdl.frontend.{HdlBool, HdlInt}
import spinal.core._

/** All candidates use the production generator and typed construction APIs. */
object BooleanWidthNormalizationArtifactWriter {
  final class PassThrough(width: ElabInt, definition: String) extends Component {
    setDefinitionName(definition)
    val dataIn = in Bits(width bits)
    val dataOut = out Bits(width bits)
    dataOut := dataIn
  }

  private def config(output: Path, passes: String): SpinalConfig = {
    Files.createDirectories(output)
    val value = SpinalConfig(
      targetDirectory = output.toString,
      oneFilePerComponent = false,
      headerWithDate = false,
      headerWithRepoHash = true
    )
    value.netlistFileName = "generated.v"
    if (passes == "disabled") MorphWireAssignmentPasses(value, enabled = false)
    else value
  }

  private def flag(default: Boolean = false): ElabBool =
    HdlBool.param("PPC4", default = default).asElabBool

  private def mode: ElabInt =
    HdlInt.param("MODE", default = 0, min = 0, max = 3).asElabInt

  private def writeRound(output: Path): Unit = {
    for (passes <- Vector("default", "disabled")) {
      def write(name: String)(top: => Component): Unit =
        MorphVerilog(config(output.resolve(passes).resolve(name), passes))(top)

      write("direct") { new PassThrough(flag().toElabInt * 3 + 1, "Wa11BooleanWidthDirect") }
      write("true-default") { new PassThrough(flag(true).toElabInt * 3 + 1, "Wa11BooleanWidthTrueDefault") }
      write("negated") { new PassThrough((!flag()).toElabInt * 3 + 1, "Wa11BooleanWidthNegated") }
      write("frontend-negated") {
        val predicate = !HdlBool.param("PPC4", default = false)
        new PassThrough(predicate.asElabBool.toElabInt * 3 + 1, "Wa11BooleanWidthFrontendNegated")
      }
      write("repeated") {
        var integer = flag().toElabInt
        (1 to 8).foreach { _ => integer = integer.elabEq(1).toElabInt }
        new PassThrough(integer * 3 + 1, "Wa11BooleanWidthRepeated")
      }
      write("compound") {
        val value = mode
        val predicate = (value >= 1) && !(value >= 3)
        new PassThrough(predicate.toElabInt * 3 + 1, "Wa11BooleanWidthCompound")
      }
      write("frontend-compound") {
        val value = HdlInt.param("MODE", default = 0, min = 0, max = 3)
        val predicate = (value >= HdlInt.literal(1)) && !(value >= HdlInt.literal(3))
        new PassThrough(predicate.asElabBool.toElabInt * 3 + 1, "Wa11BooleanWidthFrontendCompound")
      }
      write("frontend-address-helper") {
        val depth = HdlInt.param("DEPTH", default = 1, min = 1, max = 4)
        val predicate = depth.addressWidth.hdlEq(HdlInt.literal(2))
        new PassThrough(predicate.asElabBool.toElabInt * 3 + 1, "Wa11BooleanWidthFrontendAddressHelper")
      }
      write("zero-roundtrip") {
        var integer = flag().toElabInt
        (1 to 8).foreach { _ => integer = integer.elabEq(0).toElabInt }
        new PassThrough(integer * 3 + 1, "Wa11BooleanWidthZeroRoundtrip")
      }
      write("integer-domain") {
        val value = HdlInt.param("INTEGER_VALUE", default = 0, min = 0, max = 3).asElabInt
        new PassThrough(value.elabEq(1).toElabInt * 3 + 1, "Wa11BooleanWidthIntegerDomain")
      }
      write("signed-arithmetic") {
        val integer = flag().toElabInt
        new PassThrough(ElabInt.literal(1) - integer * -3, "Wa11BooleanWidthSignedArithmetic")
      }
      write("signed-compare") {
        val integer = flag().toElabInt
        new PassThrough(((integer - 2) < 0).toElabInt * 3 + 1, "Wa11BooleanWidthSignedCompare")
      }
      write("signed-minimum") {
        val negative = flag().toElabInt * Int.MinValue
        new PassThrough((negative < 0).toElabInt * 3 + 1, "Wa11BooleanWidthSignedMinimum")
      }
      write("signed-maximum") {
        val positive = flag().toElabInt * Int.MaxValue
        new PassThrough((positive > 0).toElabInt * 3 + 1, "Wa11BooleanWidthSignedMaximum")
      }
      write("integer-sizing") {
        val integer = (mode >= 2).toElabInt
        val doubled = integer + integer
        new PassThrough((doubled > integer).toElabInt * 3 + 1, "Wa11BooleanWidthIntegerSizing")
      }
      write("child") { new BooleanWidthNormalizationChildFixture.Top(flag().toElabInt * 3 + 1) }
    }
  }

  def main(args: Array[String]): Unit = {
    require(args.length == 1, "Usage: BooleanWidthNormalizationArtifactWriter <output-directory>")
    val output = Paths.get(args(0)).toAbsolutePath.normalize
    Vector("first", "repeat").foreach(round => writeRound(output.resolve(round)))
  }
}

package spinal.core

import morphhdl.frontend.{HdlBool, HdlInt}
import org.scalatest.funsuite.AnyFunSuite

/** Exercise the existing native typed child boundary, whose API is package scoped. */
object BooleanWidthNormalizationChildFixture {
  final class Child(width: ElabInt) extends Component {
    setDefinitionName("Wa11BooleanWidthChild")
    val dataIn = in Bits(width bits)
    val dataOut = out Bits(width bits)
    dataOut := dataIn
  }

  final class Top(width: ElabInt) extends Component {
    setDefinitionName("Wa11BooleanWidthChildTop")
    val dataIn = in Bits(width bits)
    val dataOut = out Bits(width bits)
    val child = ElabFormalComponent
      .parameter(width, "CHILD_WIDTH", BigInt(1), BigInt(4))(formal => new Child(formal))
      .setName("child")
    child.dataIn := dataIn
    dataOut := child.dataOut
  }
}

/** WA-11: simplification must retain typed integer semantics and exact authority. */
class BooleanWidthNormalizationTests extends AnyFunSuite {
  private def values(value: ElabInt): Vector[(BigInt, BigInt)] =
    value.expression.exactDomain.getOrElse(fail("missing exact integer evidence")).evaluations

  private def root(value: ElabInt): ElaborationIntegerParameterRoot =
    value.expression.exactDomain.getOrElse(fail("missing exact integer evidence")).root

  private def parameter(name: String, minimum: Int, maximum: Int, default: Int): ElabInt =
    HdlInt.param(name, BigInt(default), BigInt(minimum), BigInt(maximum)).asElabInt

  test("Boolean roots normalize without specializing either default or losing provenance") {
    Vector(false, true).foreach { default =>
      val predicate = HdlBool.param("PPC4", default = default).asElabBool
      val encoded = predicate.toElabInt
      val width = encoded * 3 + 1
      val predicateDomain = predicate.expression.exactDomain.get
      val integerDomain = encoded.expression.exactDomain.get

      assert(encoded.expression.verilog == "PPC4", encoded.expression.verilog)
      assert(encoded.expression.hasExactAuthority)
      assert(integerDomain.root eq predicateDomain.root)
      assert(integerDomain.parameter eq predicateDomain.parameter)
      assert(encoded.parameters == predicate.parameters)
      assert(encoded.sourceLocation == predicate.sourceLocation)
      assert(encoded.sourceLocation.nonEmpty)
      assert(encoded.expression.parameterRoots.head eq predicate.expression.parameterRoots.head)
      assert(integerDomain.hasCompleteCoverage)
      assert(values(encoded) == Vector(BigInt(0) -> BigInt(0), BigInt(1) -> BigInt(1)))
      assert(values(width) == Vector(BigInt(0) -> BigInt(1), BigInt(1) -> BigInt(4)))
      assert(width.expression.default == (if (default) 4 else 1))
      assert(width.minimum == 1 && width.maximum == 4)
    }
  }

  test("repeated Boolean integer round trips do not accumulate conversions") {
    val direct = HdlBool.param("PPC4", default = false).asElabBool.toElabInt
    var result = direct
    (1 to 12).foreach { _ =>
      result = result.elabEq(1).toElabInt
      assert(result.expression.verilog == direct.expression.verilog)
      assert(root(result) eq root(direct))
      assert(values(result) == values(direct))
      assert(result.sourceLocation == direct.sourceLocation)
      assert(result.expression.hasExactAuthority)
    }
    var inverted = direct
    (1 to 8).foreach { iteration =>
      inverted = inverted.elabEq(0).toElabInt
      assert(values(inverted).map(_._2) == (if (iteration % 2 == 0) Vector(BigInt(0), BigInt(1)) else Vector(BigInt(1), BigInt(0))))
      assert(root(inverted) eq root(direct))
      assert(inverted.expression.verilog.count(_ == '?') <= 1, inverted.expression.verilog)
    }
  }

  test("compound predicates and negation retain one integer encoding through round trips") {
    val mode = parameter("MODE", 0, 3, 0)
    val compound = (mode >= 1) && !(mode >= 3)
    val cases = Vector(
      compound -> Vector(0, 1, 1, 0),
      !compound -> Vector(1, 0, 0, 1)
    )
    cases.foreach { case (predicate, expected) =>
      val first = predicate.toElabInt
      var encoded = first
      (1 to 8).foreach { _ => encoded = encoded.elabEq(1).toElabInt }
      assert(encoded.expression.verilog.count(_ == '?') <= 1, encoded.expression.verilog)
      assert(encoded.expression.verilog == first.expression.verilog)
      assert(root(encoded) eq root(mode))
      assert(values(encoded) == expected.zipWithIndex.map { case (value, index) =>
        BigInt(index) -> BigInt(value)
      })
      assert(values(encoded * 3 + 1).map(_._2) == expected.map(value => BigInt(value * 3 + 1)))
    }
  }

  test("integer domains containing non Boolean values cannot be returned from equality encoding") {
    Vector(-1, 0, 1, 2).foreach { default =>
      val integer = parameter("INTEGER_VALUE", -1, 2, default)
      val encoded = integer.elabEq(1).toElabInt
      assert(encoded.expression.verilog != "INTEGER_VALUE", encoded.expression.verilog)
      assert(encoded.expression.verilog.contains("=="), encoded.expression.verilog)
      assert(encoded.expression.verilog.count(_ == '?') <= 1, encoded.expression.verilog)
      assert(root(encoded) eq root(integer))
      assert(encoded.parameters == integer.parameters)
      assert(values(encoded) == (-1 to 2).map(value =>
        BigInt(value) -> (if (value == 1) BigInt(1) else BigInt(0))
      ).toVector)
      assert(encoded.minimum == 0 && encoded.maximum == 1)
      val unsupportedWidthRoot = intercept[ParameterizedVerilogException] {
        ParameterizedWidth.validatedWidthExpression((encoded * 3 + 1).bits)
      }
      assert(unsupportedWidthRoot.code == "SPINAL-PARAMETERIZED-VERILOG-PARAMETER-DOMAIN-INVALID")
    }
  }

  test("integer arithmetic uses signed 32 bit values at both boundaries") {
    val encoded = HdlBool.param("PPC4", default = false).asElabBool.toElabInt
    assert(values(encoded * Int.MinValue).map(_._2) == Vector(BigInt(0), BigInt(Int.MinValue)))
    assert(values(encoded * Int.MaxValue).map(_._2) == Vector(BigInt(0), BigInt(Int.MaxValue)))
    assert(values((encoded * Int.MinValue < 0).toElabInt).map(_._2) == Vector(BigInt(0), BigInt(1)))
    assert(values((encoded * Int.MaxValue > 0).toElabInt).map(_._2) == Vector(BigInt(0), BigInt(1)))

    val nearMinimum = parameter("MINIMUM", Int.MinValue, Int.MinValue + 1, Int.MinValue)
    assert(values((nearMinimum < 0).toElabInt).map(_._2) == Vector(BigInt(1), BigInt(1)))
    val nearMaximum = parameter("MAXIMUM", Int.MaxValue - 1, Int.MaxValue, Int.MaxValue)
    assert(values((nearMaximum > 0).toElabInt).map(_._2) == Vector(BigInt(1), BigInt(1)))

    val highError = intercept[ParameterizedVerilogException] { encoded * Int.MaxValue + 1 }
    assert(highError.code == "SPINAL-ELAB-DOMAIN-EVIDENCE-RESULT-OUT-OF-RANGE")
    val lowError = intercept[ParameterizedVerilogException] { encoded * Int.MinValue - 1 }
    assert(lowError.code == "SPINAL-ELAB-DOMAIN-EVIDENCE-RESULT-OUT-OF-RANGE")
  }

  test("predicate encodings stay integers when addition would overflow one bit") {
    val mode = parameter("MODE", 0, 3, 0)
    val encoded = (mode >= 2).toElabInt
    val doubled = encoded + encoded
    val predicate = doubled > encoded
    assert(values(doubled).map(_._2) == Vector(0, 0, 2, 2).map(BigInt(_)))
    assert(values(predicate.toElabInt).map(_._2) == Vector(0, 0, 1, 1).map(BigInt(_)))
  }

  test("normalization retains branch projection restrictions and global legal domains") {
    val integer = parameter("INTEGER_VALUE", 0, 2, 0)
    var projected: ElabInt = null
    ElaborationDomainContext.withAdmitted(root(integer), Set(BigInt(0), BigInt(1)), None) {
      projected = integer.elabEq(1).toElabInt.elabEq(1).toElabInt
      assert(projected.minimum == 0 && projected.maximum == 1)
      assert(root(projected) eq root(integer))
      assert(projected.parameters.head.maximum == 2)
      assert(projected.expression.projectionProvenance.nonEmpty)
    }
    val error = intercept[ParameterizedVerilogException] { projected.minimum }
    assert(error.code == "SPINAL-ELAB-DOMAIN-PROJECTION-SCOPE-EXPANSION")
    val complete = integer.elabEq(1).toElabInt
    assert(values(complete).last == (BigInt(2) -> BigInt(0)))
  }

  test("normalization does not relax independent root or invalid width diagnostics") {
    val first = HdlBool.param("SAME", default = false).asElabBool
    val second = HdlBool.param("SAME", default = false).asElabBool
    val independent = intercept[ParameterizedVerilogException] { first && second }
    assert(independent.code == "SPINAL-ELAB-INT-INDEPENDENT-ROOTS-UNSUPPORTED")
    val width = intercept[ParameterizedVerilogException] { first.toElabInt.bits }
    assert(width.code == "SPINAL-ELAB-INT-WIDTH-DOMAIN-INVALID")
  }

  test("frontend predicates retain portable address width helper support") {
    val depth = HdlInt.param("DEPTH", default = 1, min = 1, max = 4)
    val predicate = depth.addressWidth.hdlEq(HdlInt.literal(2)).asElabBool
    val encoded = predicate.toElabInt
    assert(values(encoded) == Vector(1 -> 0, 2 -> 0, 3 -> 1, 4 -> 1).map {
      case (input, output) => BigInt(input) -> BigInt(output)
    })
    assert(encoded.expression.verilog.count(_ == '?') <= 2, encoded.expression.verilog)
    assert(encoded.sourceLocation == predicate.sourceLocation)
  }

  test("copied normalized integer metadata cannot reacquire exact authority") {
    val integer = HdlBool.param("PPC4", default = false).asElabBool.toElabInt
    val copied = integer.expression.copy()
    assert(copied.exactDomain.nonEmpty)
    assert(!copied.hasExactAuthority)
    val failure = intercept[ParameterizedVerilogException] {
      ElabInt.fromExpression(copied).elabEq(1).toElabInt
    }
    assert(failure.code == "SPINAL-ELAB-DOMAIN-EXACT-AUTHORITY-MISSING")
  }
}

