      rejected("CONTROL-ARITY") { proof.replay(source(0)) }
      rejected("CONTROL-ARITY") { proof.replayWithWidth(source(0), evidence(0).width) }
      val replacement = inputs()
      rejected("CONTROL-BINDING") {
