      }
      val proof = TypedBalancedReductionBridgeReplay.certify(callback, evidence(0), evidence)
      proof.validateFreshness()
      val peer = source(1).asInstanceOf[Bits]
      peer.setWidth(4)
      rejected("VALUE-EVIDENCE") { proof.validateFreshness() }
      peer.setWidth(3)
