def stress_bench() -> str:
    inputs = [('clkA', 1), ('clkB', 1), ('rstA', 1), ('rstB', 1), ('enableA', 1), ('enableB', 1),
              ('block', 1), ('forceRun', 1), ('priority', 1), ('clear', 1), ('allowB', 1),
              ('value', 18), ('extra', 18), ('signedValue', 18)]
    outputs = [('countA', 13), ('priorA', 13), ('totalA', 13), ('sumTruncA', 13),
               ('countB', 12), ('totalB', 12), ('sameEdgeA', 1), ('signedA', 8), ('signedWideA', 20)]
    lines = ['`timescale 1ns/1ps', 'module stress_tb;']
    for name, width in inputs:
        lines.append(f'reg [{width-1}:0] {name}=0;')
    for name, width in outputs:
        lines.append(f'wire [{width-1}:0] ref_{name}, opt_{name};')
    for module, prefix in [('StressReference', 'ref'), ('StressOptimized', 'opt')]:
        ports = [f'.io_{name}({name})' for name, _ in inputs]
        ports += [f'.io_{name}({prefix}_{name})' for name, _ in outputs]
        lines.append(f'{module} {prefix}_dut({",".join(ports)});')
    ref = '{' + ','.join('ref_' + n for n, _ in outputs) + '}'
    opt = '{' + ','.join('opt_' + n for n, _ in outputs) + '}'
    lines += ['integer i, samples=0;', "reg [31:0] rng=32'hcd497ec1;", 'task check; begin',
              'samples=samples+1;', f'if ({ref} !== {opt}) $fatal(1,"stress mismatch sample=%0d", samples);',
              'end endtask', 'initial begin',
              'clkA=0;clkB=1;rstA=0;rstB=1;#2;rstA=1;rstB=0;#2;check;',
              'clkA=1;clkB=0;#2;check;',
              f'if (^{ref} === 1\'bx) $fatal(1,"reference not initialized by both resets");',
              'clkA=0;clkB=1;rstA=0;rstB=1;']
    lines += ['for(i=0;i<16384;i=i+1) begin',
              'rng=rng^(rng<<13);rng=rng^(rng>>17);rng=rng^(rng<<5);',
              '{enableA,enableB,block,forceRun,priority,clear,allowB}=rng[6:0];',
              'value=rng[17:0];extra={rng[7:0],rng[31:22]};signedValue=rng[31:14];',
              'rstA=(i%43==0);rstB=(i%61!=0);#2;check;',
              'clkA=1;#2;check;', 'clkB=0;#2;check;', 'clkA=0;clkB=1;#2;check;',
              'end', '$display("PASS stress: 2 clock domains, 16384 cycles, samples=%0d",samples);',
              '$finish;', 'end', 'endmodule']
    return '\n'.join(lines) + '\n'


def main() -> None:
    truncation = truncation_validator()
    truncation.truncation_self_test()
    parser = argparse.ArgumentParser()
    parser.add_argument('directory', type=Path, help='Untouched GenerateRemainingWireMatrix output')
    args = parser.parse_args()
    root = args.directory.resolve()
    logs = root / 'checks'
    logs.mkdir(exist_ok=True)
    for tool in ('iverilog', 'vvp', 'yosys'):
        if not shutil.which(tool):
            raise RuntimeError(f'Required verification tool is missing: {tool}')
    duties = sorted(root.glob('*/*.v'))
    before = {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in duties}
    receipts: list[str] = []
    for reset in ('async', 'sync', 'boot'):
        versions = {mode: (root / f'{reset}-{mode}' / 'RemainingWireRepro.v')
                    for mode in ('default', 'repeat', 'enabled', 'disabled')}
        default = versions['default'].read_text()
        assert versions['default'].read_bytes() == versions['repeat'].read_bytes(), 'Non-deterministic generation'
        assert versions['default'].read_bytes() == versions['enabled'].read_bytes(), 'Default is not standard enabled flow'
        assert not re.search(r'\bwhen_\w+|\b_zz_timing_[hv]Total\w*', default), default
        assert 'timing_hTotal <= timing_proposedHTotal[12:0];' in default, default
        assert 'timing_vTotal <= timing_proposedVTotal[11:0];' in default, default
        assert 'parameter integer PPC4 = 0' in default
        assert len(re.findall(r'^\s*reg\s', default, flags=re.M)) == 6, default
        disabled = versions['disabled'].read_text()
        assert len(re.findall(r'^\s*assign when_\w+\s*=', disabled, flags=re.M)) == 4, disabled
        # Disabling the production pipeline restores Spinal's earlier native
        # cleanup too: that path already slices named totals directly. Its
        # historical distinction is retained conditions + arithmetic carriers,
        # not the enabled-pipeline's former two direct-total aliases.
        for axis, high in (('h', 12), ('v', 11)):
            assert f'timing_{axis}Total <= timing_proposed{axis.upper()}Total[{high}:0];' in disabled, disabled
            assert re.search(rf'assign _zz_timing_proposed{axis.upper()}Total\w*\s*=', disabled), disabled
        bench = logs / f'tb-{reset}.v'
        bench.write_text(timing_bench(reset))
        for mode, dut in versions.items():
            for ppc in (0, 1):
                label = f'timing-{reset}-{mode}-ppc{ppc}'
                exe = logs / (label + '.vvp')
                run(['iverilog', '-g2001', '-s', 'tb', f'-Ptb.PPC4={ppc}', '-o', str(exe), str(bench), str(dut)], logs / (label + '-compile.log'))
                run(['vvp', str(exe)], logs / (label + '-simulation.log'))
                receipts.append(label)
        for ppc in (0, 1):
            script = logs / f'equiv-{reset}-ppc{ppc}.ys'
            cmds = []
            for mode, name in [('disabled', 'gold'), ('default', 'gate')]:
                cmds += [f'read_verilog {versions[mode]}',
                         f'hierarchy -top RemainingWireRepro -chparam PPC4 {ppc}',
                         'proc', 'opt', 'check -assert', 'async2sync', 'opt',
                         f'rename RemainingWireRepro {name}', f'design -stash {name}']
            cmds += ['design -copy-from gold -as gold gold', 'design -copy-from gate -as gate gate',
                     'equiv_make gold gate equiv', 'hierarchy -top equiv', 'opt_clean',
                     'equiv_simple', 'equiv_induct -undef -seq 6', 'equiv_status -assert']
            script.write_text('\n'.join(cmds) + '\n')
            run(['yosys', '-Q', '-s', str(script)], script.with_suffix('.log'))
            receipts.append(f'equivalence-{reset}-ppc{ppc}')
            for mode in ('default', 'disabled'):
                synthesis = logs / f'synth-{reset}-{mode}-ppc{ppc}.ys'
                synthesis.write_text(f'read_verilog {versions[mode]}\nhierarchy -top RemainingWireRepro -chparam PPC4 {ppc}\nsynth -top RemainingWireRepro\ncheck -assert\n')
                run(['yosys', '-Q', '-s', str(synthesis)], synthesis.with_suffix('.log'))
                receipts.append(f'synthesis-{reset}-{mode}-ppc{ppc}')
    assert (root / 'async-default/RemainingWireRepro.v').read_bytes() == (root / 'traced/RemainingWireRepro.v').read_bytes(), 'Trace changed the emitted DUT'
    assert (root / 'stress-default/StressOptimized.v').read_bytes() == (root / 'stress-repeat/StressOptimized.v').read_bytes()
    stress_dut = (root / 'stress-default/StressOptimized.v').read_text()
    assert 'sourceWord' in stress_dut
    reference = (root / 'stress-disabled/StressReference.v').read_text()
    source = truncation.validate_register_truncation(reference, stress_dut, 'a_sumTrunc')
    assert re.sub(r'\s+', '', source) == '(io_value+io_extra)', 'Arithmetic slice source changed'
    bench = logs / 'stress_tb.v'
    bench.write_text(stress_bench())
    exe = logs / 'stress.vvp'
    run(['iverilog', '-g2001', '-s', 'stress_tb', '-o', str(exe), str(bench),
         str(root / 'stress-default/StressOptimized.v'), str(root / 'stress-disabled/StressReference.v')], logs / 'stress-compile.log')
    run(['vvp', str(exe)], logs / 'stress-simulation.log')
    receipts.append('two-clock-multiple-use-signed-priority-enable-miter')
    # Mutate only the independent EXPECTED model, never the emitted Verilog.
    for mutation in ('MUTATE_PRIORITY', 'MUTATE_COUNTER'):
        exe = logs / (mutation + '.vvp')
        run(['iverilog', '-g2001', '-s', 'tb', '-D' + mutation, '-o', str(exe),
             str(logs / 'tb-async.v'), str(root / 'async-default/RemainingWireRepro.v')], logs / (mutation + '-compile.log'))
        run(['vvp', str(exe)], logs / (mutation + '-detected.log'), expect_failure=True)
        receipts.append('detected-' + mutation)
    after = {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in duties}
    assert before == after, 'Verification modified emitted Verilog'
    (logs / 'receipt.json').write_text(json.dumps({'passed': receipts, 'unmodified_dut_sha256': after}, indent=2) + '\n')
    print(f'PASS: {len(receipts)} simulation, equivalence, synthesis and mutation checks; deterministic output and untouched DUT digests')


if __name__ == '__main__':
    main()

import java.nio.file.{Files, Paths}
import spinal.core._
import morphhdl.{MorphVerilog, MorphWireAssignmentPasses}
import morphhdl.frontend.HdlBool

/** Independent of application RTL. Both clocks deliberately use one predicate. */
class SequentialConsumerStress(ppc: ElabInt) extends Component {
  val io = new Bundle {
    val clkA, clkB, rstA, rstB, enableA, enableB = in Bool()
    val block, forceRun, priority, clear, allowB = in Bool()
    val value, extra = in UInt(18 bits)
    val signedValue = in SInt(18 bits)
    val countA, priorA, totalA, sumTruncA = out UInt(13 bits)
    val countB, totalB = out UInt(12 bits)
    val sameEdgeA = out Bool()
    val signedA = out SInt(8 bits)
    val signedWideA = out SInt(20 bits)
    val lanes = out Bits(ppc bits)
  }
  @dontName val shared = !io.block || io.forceRun
  val sourceWord = io.value + io.extra
  val domainA = ClockDomain(io.clkA, io.rstA, clockEnable = io.enableA,
    config = ClockDomainConfig(clockEdge = RISING, resetKind = ASYNC,
      resetActiveLevel = HIGH, clockEnableActiveLevel = HIGH))
  val domainB = ClockDomain(io.clkB, io.rstB, clockEnable = io.enableB,
    config = ClockDomainConfig(clockEdge = FALLING, resetKind = SYNC,
      resetActiveLevel = LOW, clockEnableActiveLevel = LOW))
  val a = new ClockingArea(domainA) {
    val count = Reg(UInt(13 bits)) init(3)
    val prior = Reg(UInt(13 bits)) init(7)
    val total = Reg(UInt(13 bits)) init(0)
    val sumTrunc = Reg(UInt(13 bits)) init(0)
    val sameEdge = Reg(Bool()) init(False)
    val signedSmall = Reg(SInt(8 bits)) init(-2)
    val signedWide = Reg(SInt(20 bits)) init(0)
    @dontName val preEdge = count === 3
    @dontName val direct = UInt(18 bits)
    direct := sourceWord
    @dontName val signedAlias = SInt(18 bits)
    signedAlias := io.signedValue
    sameEdge := preEdge
    signedSmall := signedAlias.resize(8)
    signedWide := signedAlias.resize(20)
    // This real arithmetic node MUST still get a legal Verilog select base.
    sumTrunc := (io.value + io.extra).resize(13)
    when(shared) {
      count := count + 1
      total := direct.resized
    } otherwise {
      count := 0
    }
    when(preEdge) { prior := count } elsewhen(io.clear) { prior := 0 }
    when(io.priority) {
      count := 9
      total := io.value.resized
    }
    when(shared) { when(io.clear) { total := direct.resized } }
  }
  val b = new ClockingArea(domainB) {
    val count = Reg(UInt(12 bits)) init(5)
    val total = Reg(UInt(12 bits)) init(0)
    when(shared) {
      count := count + 2
      total := sourceWord.resized
    } otherwise { count := 0 }
    when(!io.allowB) { count := 1 }
  }
  io.lanes := 0
  io.countA := a.count
  io.priorA := a.prior
  io.totalA := a.total
  io.sumTruncA := a.sumTrunc
  io.sameEdgeA := a.sameEdge
  io.signedA := a.signedSmall
  io.signedWideA := a.signedWide
  io.countB := b.count
  io.totalB := b.total
}

object GenerateRemainingWireMatrix extends App {
  require(args.length == 1, "Supply an output directory")
  val root = Paths.get(args(0)).toAbsolutePath
  def config(directory: String, mode: String, reset: ResetKind = ASYNC): SpinalConfig = {
    val base = SpinalConfig(targetDirectory = root.resolve(directory).toString,
      oneFilePerComponent = true, headerWithDate = false, headerWithRepoHash = true,
      defaultConfigForClockDomains = ClockDomainConfig(resetKind = reset))
    mode match {
      case "enabled" => MorphWireAssignmentPasses(base, enabled = true)
      case "disabled" => MorphWireAssignmentPasses(base, enabled = false)
      case "default" | "repeat" => base
    }
  }
  for ((name, reset) <- Vector("async" -> ASYNC, "sync" -> SYNC, "boot" -> BOOT);
       mode <- Vector("default", "repeat", "enabled", "disabled")) {
    MorphVerilog(config(s"$name-$mode", mode, reset)) {
      new RemainingWireRepro(
        HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1)
    }
  }
  for (mode <- Vector("default", "repeat", "disabled")) {
    MorphVerilog(config(s"stress-$mode", mode)) {
      val dut = new SequentialConsumerStress(
        HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1)
      dut.setDefinitionName(if (mode == "disabled") "StressReference" else "StressOptimized")
      dut
    }
  }
  val traced = MorphWireAssignmentPasses(config("traced", "default"))
  spinal.core.internals.RemainingWireTrace.install(traced, root.resolve("trace"))
  MorphVerilog(traced) {
    new RemainingWireRepro(
      HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1)
  }
  println("REMAINING-WIRES: matrix generation complete")
}

import spinal.core._
import morphhdl.MorphVerilog
import morphhdl.frontend.HdlBool

class RemainingWireRepro(val ppc: ElabInt) extends Component {
  val io = new Bundle {
    val load, ready, legal, rasterRun, cfgValid, running, accept = in Bool()
    val hActive, hFront, hSync, hBack = in UInt(16 bits)
    val vActive, vFront, vSync, vBack = in UInt(16 bits)
    val hTotal = out UInt(13 bits)
    val vTotal = out UInt(12 bits)
    val controlError, invalidEvent, runningOut = out Bool()
    val x = out UInt(13 bits)
    val lanes = out Bits(ppc bits)
  }
  val timing = new Area {
    val hTotal = Reg(UInt(13 bits)) init(0)
    val vTotal = Reg(UInt(12 bits)) init(0)
    val controlError = Reg(Bool()) init(False)
    val invalidEvent = Reg(Bool()) init(False)
    val running = Reg(Bool()) init(False)
    val x = Reg(UInt(13 bits)) init(0)
    val proposedHTotal = io.hActive.resize(18) + io.hFront.resize(18) +
      io.hSync.resize(18) + io.hBack.resize(18)
    val proposedVTotal = io.vActive.resize(18) + io.vFront.resize(18) +
      io.vSync.resize(18) + io.vBack.resize(18)
    controlError := False
    invalidEvent := False
    when(io.load) {
      when(!io.ready) {
        controlError := True
      } elsewhen(!io.legal) {
        invalidEvent := True
      } otherwise {
        hTotal := proposedHTotal.resized
        vTotal := proposedVTotal.resized
      }
    }
    when(!io.rasterRun || !io.cfgValid) {
      running := False
      x := 0
    } otherwise {
      running := True
      when(!io.running || io.accept) {
        x := 0
      } otherwise {
        x := x + 1
      }
    }
  }
  io.hTotal := timing.hTotal
  io.vTotal := timing.vTotal
  io.controlError := timing.controlError
  io.invalidEvent := timing.invalidEvent
  io.runningOut := timing.running
  io.x := timing.x
  io.lanes := 0
}

object GenerateRemainingWireRepro extends App {
  require(args.length == 1, "Supply an output directory")
  MorphVerilog(SpinalConfig(targetDirectory = args(0),
    oneFilePerComponent = true, headerWithDate = false,
    headerWithRepoHash = true)) {
    new RemainingWireRepro(
      HdlBool.param("PPC4", default = false).asElabBool.toElabInt * 3 + 1)
  }
}

package spinal.core.internals

import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path}
import scala.collection.mutable.ArrayBuffer
import spinal.core._

/** Read-only native observations; no names, tags, expressions or passes change. */
object RemainingWireTrace {
  def install(config: SpinalConfig, directory: Path): Unit = {
    def observer(label: String): Phase = new Phase {
      override def hasNetlistImpact: Boolean = false
      override def impl(pc: PhaseContext): Unit = {
        val lines = ArrayBuffer.empty[String]
        val ids = new java.util.IdentityHashMap[Expression, java.lang.Integer]()
        def id(e: Expression): Int = {
          val old = ids.get(e)
          if (old != null) old.intValue
          else { val next = ids.size; ids.put(e, next); next }
        }
        pc.components().foreach { c =>
          val planned = VerilogEmitterExpressionInlining.redundantWrappers(c, pc.config)
          def describe(e: Expression, depth: Int = 0): String = {
            if (e == null) return "null"
            if (depth > 24) return "depth-limit"
            val detail = e match {
              case b: BaseType => s"name=${b.getName("")},unnamed=${b.isUnnamed},reg=${b.isReg},typeNode=${b.isTypeNode}"
              case r: Resize => s"size=${r.size},input=${describe(r.input, depth + 1)}"
              case other =>
                val children = ArrayBuffer.empty[String]
                other.foreachDrivingExpression(x => children += describe(x, depth + 1))
                children.mkString("children=[", ",", "]")
            }
            s"${id(e)}:${e.getClass.getSimpleName}(approved=${planned.containsKey(e)},$detail)"
          }
          c.dslBody.walkStatements {
            case d: DataAssignmentStatement =>
              lines += s"assign ${d.finalTarget.getName("")} reg=${d.finalTarget.isReg} <- ${describe(d.source)}"
            case w: WhenStatement => lines += s"when ${describe(w.cond)}"
            case _ =>
          }
        }
        Files.createDirectories(directory)
        Files.write(directory.resolve(label + ".txt"), (lines.mkString("\n") + "\n").getBytes(StandardCharsets.UTF_8))
      }
    }
    config.phasesInserters += { phases: ArrayBuffer[Phase] =>
      val pass = phases.indexWhere(_.getClass.getName == "morphhdl.examples.ProductionWireAssignmentPhase")
      require(pass >= 0, "Default production pass is missing")
      phases.insert(pass, observer("before-production"))
      phases.insert(pass + 2, observer("after-production"))
      val emitter = phases.indexWhere(_.isInstanceOf[PhaseVerilog])
      require(emitter >= 0, "Native Verilog emitter is missing")
      phases.insert(emitter, observer("before-emission"))
    }
  }
}
